window.EVA_COURSE_DATA={"source":"Easy Learning English from Zero to Advanced — 240-lesson Study Guide","modules":[{"number":1,"title":"Sound Foundations","level":"PRE-A1"},{"number":2,"title":"First Grammar Building Blocks","level":"PRE-A1"},{"number":3,"title":"First Adult Conversations","level":"PRE-A1"},{"number":4,"title":"People, Objects and Descriptions","level":"A1"},{"number":5,"title":"Daily Routines and Present Simple","level":"A1"},{"number":6,"title":"Actions Happening Now","level":"A1"},{"number":7,"title":"First Past and Future","level":"A1"},{"number":8,"title":"Clearer Descriptions and Quantities","level":"A2"},{"number":9,"title":"Past, Present and Experience","level":"A2"},{"number":10,"title":"Advice, Rules and Arrangements","level":"A2"},{"number":11,"title":"Longer, More Useful Sentences","level":"A2"},{"number":12,"title":"Telling Better Stories","level":"B1"},{"number":13,"title":"Meaning, Advice and Hypotheses","level":"B1"},{"number":14,"title":"Reporting and Passive Voice","level":"B1"},{"number":15,"title":"Nouns, Verbs and Word Families","level":"B1"},{"number":16,"title":"Confident Intermediate Communication","level":"B1"},{"number":17,"title":"Time and Aspect in Real English","level":"B2"},{"number":18,"title":"Speculation, Regret and Conditions","level":"B2"},{"number":19,"title":"Advanced Clauses and Reporting","level":"B2"},{"number":20,"title":"Precision with Everyday Grammar","level":"B2"},{"number":21,"title":"Professional English and Cohesion","level":"B2"},{"number":22,"title":"Word Order, Focus and Emphasis","level":"C1"},{"number":23,"title":"Advanced Time, Modality and Unreal","level":"C1"},{"number":24,"title":"Advanced Clause Compression","level":"C1"},{"number":25,"title":"Advanced Discourse and Communication","level":"C1"},{"number":26,"title":"Mastery of Grammar Choices","level":"C2"},{"number":27,"title":"Idiom, Register and Pragmatics","level":"C2"},{"number":28,"title":"High-Level Writing and Speaking","level":"C2"},{"number":29,"title":"Proficiency Projects and Assessment","level":"C2"}],"lessons":[{"id":"001","title":"Welcome to English: everyday phrases and learning routines","level":"PRE-A1","module":1,"main":"English helps you ask questions, share information and speak with people in everyday life. Learn useful phrases before learning long rules.","how":"Say a short sentence, listen again, and repeat. It is fine to speak slowly; clear meaning matters more than speed.","detail":"Start with useful phrases, not difficult rules. A greeting opens a conversation. A polite request helps when you cannot hear or understand. Repeat the same phrase with a new name or situation.","rules":"","examples":["Hello. My name is Sara.","Please speak slowly.","Could you say that again, please?","Hello, I am Karim. Nice to meet you.","I'm sorry. Could you repeat that, please?","Good afternoon. My name is Lina.","I am learning English for work.","Please write the word on the board.","Can you speak more slowly, please?","Thank you. Now I understand."]},{"id":"002","title":"The Alphabet, Part 1: A to M","level":"PRE-A1","module":1,"main":"The English alphabet has 26 letters. This lesson introduces the letter names from A to M, not every sound those letters can make.","how":"Letter names help you spell your name, fill in forms and check details. A letter name and its sound inside a word are sometimes different.","detail":"A letter has a name, but it can have different sounds in different words. When somebody spells a name, listen for the letter names and confirm difficult letters.","rules":"Letters and sounds are not the same\nThe letter name A is pronounced /eɪ/ in British English. In apple, the same written letter usually has the\nvowel sound /æ/. Learn letter names for spelling and word sounds for speaking.\n\n EXAMPLE A - /eɪ/ - apple\n EXAMPLE C - /siː/ - cat\n\n EXAMPLE E - /iː/ - egg","examples":["A, B, C, D, E, F, G.","H, I, J, K, L, M.","My name begins with M.","A as in Anna; M as in Maria.","Could you spell your surname, please?","A begins the word 'address'.","B begins the word 'bank'.","D begins the word 'doctor'.","F begins the word 'form'.","M begins the word 'manager'."],"supplement":{"letters":[{"letter":"A","ipa":"/eɪ/","word":"address"},{"letter":"B","ipa":"/biː/","word":"bank"},{"letter":"C","ipa":"/siː/","word":"city"},{"letter":"D","ipa":"/diː/","word":"doctor"},{"letter":"E","ipa":"/iː/","word":"email"},{"letter":"F","ipa":"/ef/","word":"form"},{"letter":"G","ipa":"/dʒiː/","word":"garden"},{"letter":"H","ipa":"/eɪtʃ/","word":"hospital"},{"letter":"I","ipa":"/aɪ/","word":"invoice"},{"letter":"J","ipa":"/dʒeɪ/","word":"job"},{"letter":"K","ipa":"/keɪ/","word":"kitchen"},{"letter":"L","ipa":"/el/","word":"London"},{"letter":"M","ipa":"/em/","word":"manager"}],"extraExamples":["Please say the letter A again.","My first name begins with B.","The word city begins with C.","Could you write D in capital form?","My email address begins with E.","This form has an F at the top.","The manager's name starts with G.","H is the first letter of hospital.","The word invoice begins with I.","J is the first letter of James.","K is the first letter of kitchen.","London begins with L.","M stands for Monday on my timetable.","Please spell your first name slowly.","Can you repeat the third letter?","I heard B, but did you say D?","Is that a capital letter or a small letter?","Could you write the letter on the form?","My name contains two letters A.","The first letter is C, not G.","I need to check the spelling.","Please put a capital letter at the beginning.","The next letter is E.","Could you say the letters one by one?","I have written A, B and C.","The form asks for my surname.","The office needs my correct email address.","I will spell it again more slowly.","Thank you for checking the details.","Now I can recognise the letters A to M."],"dialogues":[{"title":"Dialogue 1 — Meeting a new colleague","lines":[["James","Hello. My name is James."],["Priya","Nice to meet you. How do you spell James?"],["James","J-A-M-E-S."],["Priya","Thank you. Let me write that down."]]},{"title":"Dialogue 2 — Reception desk","lines":[["Receptionist","Could you tell me your surname?"],["Visitor","My surname is Malik."],["Receptionist","Could you spell the beginning, please?"],["Visitor","M-A-L."],["Receptionist","Thank you. I'll check the rest."]]},{"title":"Dialogue 3 — A form at work","lines":[["Teacher","Please write your name on the form."],["Learner","Should I use capital letters?"],["Teacher","Begin your name with a capital letter."],["Learner","Thank you. I understand."]]},{"title":"Dialogue 4 — Checking a letter","lines":[["Office worker","Is the first letter B or D?"],["Caller","B, as in bank."],["Office worker","Thank you. I heard B."],["Caller","Yes, that is correct."]]},{"title":"Dialogue 5 — Practising together","lines":[["Emily","Let's practise A to M."],["Learner","A, B, C, D, E, F, G."],["Emily","Good. What comes next?"],["Learner","H, I, J, K, L, M."],["Emily","Well done. Let's repeat them slowly."]]}],"notes":["The English alphabet contains 26 written letters. This lesson focuses on A–M; Lesson 003 covers N–Z.","A capital letter and a small letter represent the same letter name: A/a, B/b and so on. Write personal names and sentence beginnings with a capital letter.","Letter names are used when spelling. The sound in a whole word may be different: the letter name A is /eɪ/, but the first sound of apple is usually /æ/.","Over the telephone, similar-sounding letters can be confused. Say a clear example word, such as B as in bank or D as in doctor."]}},{"id":"003","title":"The Alphabet, Part 2: N to Z","level":"PRE-A1","module":1,"main":"The second half of the English alphabet runs from N to Z. Practise saying each letter name clearly.","how":"Some letter names sound similar, such as M and N. Ask someone to repeat a letter if you are unsure.","detail":"A letter has a name, but it can have different sounds in different words. When somebody spells a name, listen for the letter names and confirm difficult letters.","rules":"Pronouncing Z in British English\nIn standard British English, the final letter Z is called zed. In American English it is usually zee. Both refer to\nthe same letter.\n\n EXAMPLE Z = zed (British)\n\n EXAMPLE Z = zee (American)","examples":["N, O, P, Q, R, S.","T, U, V, W, X, Y, Z.","My surname begins with R.","A as in Anna; M as in Maria.","Could you spell your surname, please?","N begins the word 'name'.","P begins the word 'phone'.","R begins the word 'report'.","S begins the word 'station'.","Z is the final letter of the alphabet."],"supplement":{"letters":[{"letter":"N","ipa":"/en/","word":"nurse"},{"letter":"O","ipa":"/əʊ/","word":"office"},{"letter":"P","ipa":"/piː/","word":"passport"},{"letter":"Q","ipa":"/kjuː/","word":"question"},{"letter":"R","ipa":"/ɑː/","word":"reception"},{"letter":"S","ipa":"/es/","word":"station"},{"letter":"T","ipa":"/tiː/","word":"ticket"},{"letter":"U","ipa":"/juː/","word":"uniform"},{"letter":"V","ipa":"/viː/","word":"visitor"},{"letter":"W","ipa":"/ˈdʌbəl.juː/","word":"website"},{"letter":"X","ipa":"/eks/","word":"X-ray"},{"letter":"Y","ipa":"/waɪ/","word":"year"},{"letter":"Z","ipa":"/zed/","word":"zero"}],"extraExamples":["The word nurse begins with N.","O is the first letter of office.","Please write P in capital form.","Q is often followed by U in English words.","My surname begins with R.","The word station begins with S.","T is the first letter of ticket.","U is the first letter of uniform.","The word visitor begins with V.","Website begins with W.","X is the first letter in X-ray.","Y begins the word year.","The word zero begins with Z.","In Britain, the letter Z is usually called zed.","Please repeat the letter N.","I heard M, but did you say N?","Could you say V more clearly?","The next letter is W.","Please use a capital R.","My name ends with S.","Can you spell your postcode for me?","Please say each letter separately.","I will check the final letter.","Is that P or B?","Could you check the last letter, please?","The letters U and V can sound similar over the telephone.","Write your initials in capital letters.","My second name begins with T.","Thank you for spelling the word.","Now I can say all 26 letter names."],"dialogues":[{"title":"Dialogue 1 — At a travel desk","lines":[["Agent","Could you spell your surname, please?"],["Traveller","R-A-N-A."],["Agent","Does it begin with R?"],["Traveller","Yes, R as in reception."]]},{"title":"Dialogue 2 — A postcode by telephone","lines":[["Caller","My postcode begins with SW."],["Officer","Could you repeat those letters?"],["Caller","S-W, s as in station and double-u."],["Officer","Thank you. I've noted that."]]},{"title":"Dialogue 3 — Checking M and N","lines":[["Teacher","Which letter did you hear, M or N?"],["Learner","I think it was N."],["Teacher","Yes, N, as in nurse."],["Learner","I'll practise the difference."]]},{"title":"Dialogue 4 — British Z","lines":[["James","What do British speakers call the final letter?"],["Emily","We usually call it zed."],["James","And in American English?"],["Emily","It is usually called zee."]]},{"title":"Dialogue 5 — The whole alphabet","lines":[["Emily","Can you say A to Z?"],["Learner","I'll try. I'll speak slowly."],["Emily","That's fine. Pause after each group."],["Learner","Thank you. Let's begin with A to M, then N to Z."]]}],"notes":["This lesson completes the alphabet with N–Z. Combine these letters with A–M from Lesson 002 for the full 26-letter sequence.","In standard British English, the name of Z is usually zed. In American English, zee is usual; these are names for the same letter.","Some letter names are easy to confuse, especially M/N, B/P, U/V and G/J. Ask for repetition or an example word when necessary.","The British name of R is often pronounced /ɑː/ in non-rhotic accents. Letter-name pronunciation varies across speakers and regional accents.","Use capital letters for names, initials and the first word of a sentence; use small letters where normal spelling requires them."]}},{"id":"004","title":"Common Vowel Sounds: hear and repeat","level":"PRE-A1","module":1,"main":"English has vowel letters A, E, I, O and U, but the spoken language has more vowel sounds than five. Listen to sounds inside complete words.","how":"A spelling does not always tell you a vowel sound. Compare short and long sounds in familiar words, then use dictionary audio.","detail":"A, E, I, O and U are vowel letters. Vowel sounds are different from vowel letters: English has more vowel sounds than five. Listen to whole words, not just their spelling.","rules":"The five vowel letters and many vowel sounds\nThere are five main vowel letters: a, e, i, o and u. English has more than five vowel sounds. One letter can\nrepresent different sounds. Use dictionary audio to check an unfamiliar word.\n\n EXAMPLE ship / sheep\n EXAMPLE full / fool\n\n EXAMPLE cat / car (standard British English)\n\nThe letter Y sometimes represents a vowel\nThe letter y can represent a vowel sound, particularly in words such as my, happy and gym. Do not decide\nthe sound from the letter alone.\n\n EXAMPLE my\n\n EXAMPLE happy\n\n EXAMPLE gym","examples":["The vowel in 'sit' differs from the vowel in 'seat'.","The vowel in 'full' differs from the vowel in 'food'.","The words 'cat' and 'car' have different vowel sounds in standard British English.","ship / sheep: the vowel changes the word.","Please repeat the word slowly.","Listen to 'ship' and 'sheep'.","Listen to 'bed' and 'bad'.","The words 'cup' and 'cap' have different vowel sounds.","The word 'food' has a long vowel sound.","Say 'sit', then say 'seat'."]},{"id":"005","title":"Consonant Sounds: clear pronunciation for beginners","level":"PRE-A1","module":1,"main":"Consonants are speech sounds made with some narrowing or closing of the mouth. The way you use your tongue, lips and voice can change the sound.","how":"Listen for the difference between pairs such as /p/ and /b/. Final consonants often matter because they can change a word's meaning.","detail":"Some consonant sounds are voiced and some are not. Put a hand gently on your throat: your voice vibrates for many voiced sounds. Practice with short, familiar words.","rules":"Voiced and voiceless consonants\nSounds such as /b/, /d/ and /v/ involve vibration in your throat. Sounds such as /p/, /t/ and /f/ are\nnormally voiceless. Keep the final consonant clear because it can change a word.\n\n EXAMPLE pat / bat\n EXAMPLE fan / van\n\n EXAMPLE coat / goat","examples":["Pat and bat begin with different consonants.","Fan and van begin with different consonants.","Rice and rise end with different consonant sounds.","fan and van begin with different sounds.","Please say the first sound again.","Listen to 'thin' and 'tin'.","The words 'rice' and 'rise' end differently.","Say 'park' slowly and clearly.","The words 'coat' and 'goat' begin with different sounds.","Practise the final sound in 'desk'."]},{"id":"006","title":"Spelling Names, Email Addresses and Simple Words","level":"PRE-A1","module":1,"main":"When spelling a name or an email address, say each letter clearly and pause between difficult parts. Use 'at' for @ and 'dot' for a full stop in an address.","how":"People may ask 'How do you spell that?' or 'Could you spell it, please?' Check what you heard by repeating it back.","detail":"","rules":"Common symbols in email addresses\nWe say at for @, dot for the full stop and underscore for _. Confirm each important letter or digit when\ngiving an address by telephone.\n\n EXAMPLE name@example.com -> name at example dot com\n\n EXAMPLE alex_smith -> alex underscore smith","examples":["My surname is Khan: K-H-A-N.","My email is sara dot lee at example dot com.","That is M for Monday, not N.","I am writing to confirm our appointment.","Please find the revised schedule attached.","My first name is Lina: L-I-N-A.","Please spell your surname for me.","My postcode is B-T-3, five N-R.","There is an underscore in my username.","My email address begins with 'nina' and ends with '.com'."]},{"id":"007","title":"Numbers, Phone Numbers and Prices","level":"PRE-A1","module":1,"main":"Use numbers to give your age, price, address, telephone number and appointment time. Practise listening to numbers, not only reading them.","how":"In telephone numbers, say digits separately when needed. British speakers often say 'oh' for zero and 'double' for two repeated digits.","detail":"In English, information such as dates, prices and phone numbers needs to be both clear and exact. Say numbers in groups and repeat important details when needed.","rules":"Numbers that are easy to confuse\nCarefully distinguish -teen and -ty endings. Stress can help: fourteen commonly stresses the last syllable in\nisolation, while forty stresses the first. Say long numbers in groups.\n\n EXAMPLE thirteen / thirty\n EXAMPLE fifteen / fifty\n\n EXAMPLE eighteen / eighty","examples":["The total is fourteen pounds.","My appointment is at three thirty.","My number ends in double five, eight, zero.","The meeting starts at nine thirty.","The total is eighteen pounds fifty.","The ticket costs twenty pounds.","My telephone number ends in four two zero.","The meeting starts at half past ten.","The discount is fifteen per cent.","The price is thirty-nine pounds fifty."]},{"id":"008","title":"Greetings, Polite Expressions and Classroom English","level":"PRE-A1","module":1,"main":"A greeting starts a conversation; a polite phrase helps it continue. Match the expression to the situation.","how":"Use 'please' for requests, 'thank you' for appreciation, and 'excuse me' to attract attention or apologise for a small interruption.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"Polite requests\nCould you ...? is usually more polite than a direct command. Add please naturally and thank the other\nperson after receiving help.\n\n EXAMPLE Repeat it. -> Could you repeat it, please?\n\n EXAMPLE Give me the form. -> Could I have the form, please?","examples":["Good morning. How are you?","Excuse me, is this seat free?","Thank you for your help.","Sorry, I did not catch your name.","Could you repeat the instructions, please?","Good afternoon. It's nice to meet you.","Thank you very much for your help.","Excuse me. Where is the reception desk?","I'm sorry I'm late.","You're welcome. Have a good day."]},{"id":"009","title":"What Is a Noun? People, Places, Things and Ideas","level":"PRE-A1","module":2,"main":"A noun names a person, place, thing or idea. Nouns help us name the people and objects we discuss.","how":"Some nouns name things you cannot touch, such as 'time' or 'help'. A single sentence may contain more than one noun.","detail":"A noun names a person, place, thing or idea. Some nouns can be counted; others refer to things we do not usually count individually. Notice the noun's role in a sentence.","rules":"Four useful types of nouns\nCommon nouns name general things; proper nouns name particular people or places; concrete nouns name\nthings we can sense; abstract nouns name ideas or qualities. A noun may belong to more than one group.\n\n EXAMPLE city (common) / London (proper)\n\n EXAMPLE table (concrete) / kindness (abstract)\n\nCountable and uncountable nouns\nA countable noun can usually have a singular and plural form: a chair, two chairs. An uncountable noun\nusually does not take a plural in its basic meaning: some information, some furniture.\n\n EXAMPLE a document / three documents\n\n EXAMPLE some advice (not an advice)","examples":["The manager has a meeting.","London is a large city.","Patience is important at work.","My neighbour owns a restaurant.","Friendship is important in life.","The teacher opened the door.","Manchester is a city in England.","The laptop is on the desk.","Honesty is important at work.","A customer needs information."]},{"id":"010","title":"Subject Pronouns: I, You, He, She, It, We, They","level":"PRE-A1","module":2,"main":"A subject pronoun tells us who or what the sentence is about: I, you, he, she, it, we, they.","how":"Use 'it' for one thing or an animal when appropriate; use 'they' for more than one person or thing, and also for a person whose gender is unknown or not specified.","detail":"","rules":"Singular they\nThey can refer to one person when the person’s gender is unknown, irrelevant or when that is the pronoun\nthe person uses. In standard English, singular they normally takes are.\n\n EXAMPLE Someone left their phone.\n\n EXAMPLE The new employee said they are ready.","examples":["I work in an office.","She lives near the station.","They are ready for the meeting.","We live in the same city.","It looks very expensive.","You have an appointment today.","He drives to work.","It is on the second floor.","We are ready for the meeting.","They live near the hospital."]},{"id":"011","title":"What Is a Verb? Actions and States","level":"PRE-A1","module":2,"main":"A verb tells us about an action, event or state. Most complete English sentences need a verb.","how":"Actions include 'work' and 'drive'. States include 'know', 'need' and 'be'. Look for the word that carries the main action or state.","detail":"","rules":"Verbs: action and state\nAction verbs describe activities, such as write and drive. State verbs describe conditions, opinions,\npossession or feelings, such as know, own and like. Some verbs are used differently depending on meaning.\n\n EXAMPLE I write reports. (action)\n\n EXAMPLE I know the answer. (state)\n\nThe five everyday verb forms\nMany verbs have a base form, a third-person singular -s form, an -ing form, a past form and a past\nparticiple. Regular past forms usually end in -ed; irregular forms must be learned separately.\n\n EXAMPLE work / works / working / worked / worked\n EXAMPLE write / writes / writing / wrote / written\n\n EXAMPLE go / goes / going / went / gone\n\nComparing verb time in simple language\nA verb form helps show whether an event is usual, happening now, finished in the past or connected with\nthe present. The full tense depends on the helpers as well as the main verb.\n\n EXAMPLE I work every day. (routine)\n EXAMPLE I am working now. (in progress)\n\n EXAMPLE I worked yesterday. (past)\n\n EXAMPLE I have worked here for two years. (up to now)","examples":["They work on Fridays.","He needs more time.","The office is quiet.","She thinks the result is correct.","We walk to the station.","I answer emails every morning.","She knows the correct address.","We prepare reports on Fridays.","He believes the information is correct.","They travel by train."]},{"id":"012","title":"The Verb Be: am, is and are","level":"PRE-A1","module":2,"main":"The present form of 'be' changes with the subject: I am, you/we/they are, and he/she/it is.","how":"Use 'be' for identity, jobs, locations and descriptions. In ordinary statements, keep the subject before the form of 'be'.","detail":"","rules":"Be is special\nUnlike most main verbs, be changes for each subject in the present. We use am with I, is with he/she/it and\nare with you/we/they. Be forms questions without do.\n\n EXAMPLE I am ready.\n\n EXAMPLE She is ready.\n EXAMPLE They are ready.\n\n EXAMPLE Are you ready?","examples":["I am an engineer.","She is at home.","We are early today.","You are welcome here.","They are in the waiting room.","I am ready for work.","You are very helpful.","He is a driver.","It is a good idea.","We are in the meeting room."]},{"id":"013","title":"Be: Negative Sentences and Contractions","level":"PRE-A1","module":2,"main":"Make negative statements with 'be' by adding 'not' after am, is or are. In speech, contractions sound natural.","how":"Use 'isn't' for 'is not' and 'aren't' for 'are not'. 'I'm not' is common; do not say 'I amn't' in standard English.","detail":"","rules":"Contractions in speech and writing\nContractions such as isn’t and aren’t are common in conversation and informal writing. Do not confuse it’s\n(it is/it has) with its (possessive).\n\n EXAMPLE She is not -> She isn’t\n EXAMPLE They are not -> They aren’t\n\n EXAMPLE It’s raining. / The dog wagged its tail.","examples":["I am not late.","He isn't available.","They aren't in the meeting.","We are not at home tonight.","It isn't my passport.","I am not busy today.","She is not at her desk.","We aren't late for the train.","They aren't available tomorrow.","It isn't my phone."]},{"id":"014","title":"Be: Yes/No Questions and Short Answers","level":"PRE-A1","module":2,"main":"To form a yes/no question with 'be', put am, is or are before the subject. Use short answers when the situation is clear.","how":"'Are you ...?' takes 'Yes, I am' or 'No, I'm not'. Do not answer 'Yes, I are'.","detail":"","rules":"Question word order with be\nPut am, is or are before the subject for a yes/no question. In short answers, repeat be instead of using do.\n\n EXAMPLE She is a nurse. -> Is she a nurse? -> Yes, she is.\n\n EXAMPLE They are late. -> Are they late? -> No, they aren’t.","examples":["Are you ready? Yes, I am.","Is she your colleague? No, she isn't.","Are they at work? Yes, they are.","Is this your ticket? Yes, it is.","Are we late? No, we aren't.","Am I on the right train? Yes, you are.","Are they open today? No, they aren't.","Is this your office? Yes, it is.","Are we early? Yes, we are.","Is he in the meeting? No, he isn't."]},{"id":"015","title":"A and An: First Articles","level":"PRE-A1","module":2,"main":"Use 'a' before a singular countable noun beginning with a consonant sound; use 'an' before a vowel sound.","how":"Choose by sound, not the first written letter. We say 'an hour' but 'a university'.","detail":"Article choice depends on sound, number and whether the listener can identify the noun. Use a/an for one non-specific singular countable thing; the when the thing is known or identified.","rules":"Choose a or an by SOUND, not only by spelling\nUse an before a vowel sound and a before a consonant sound. Some words begin with a written vowel but\na consonant sound, and some begin with a written consonant but a vowel sound.\n\n EXAMPLE an apple\n\n EXAMPLE an hour (silent h)\n\n EXAMPLE a university (/j/ sound)\n EXAMPLE a European city (/j/ sound)\n\n EXAMPLE an honest answer","examples":["She is a teacher.","I need an umbrella.","It takes an hour.","I need a pen. The pen is on the desk.","She is an engineer.","I need a pen.","She ordered an orange juice.","He is an accountant.","We booked a room.","It is a useful website."]},{"id":"016","title":"Adjectives and Basic Sentence Order","level":"PRE-A1","module":2,"main":"An adjective describes a person, place, thing or idea. An adjective often comes before a noun or after a linking verb such as 'be'.","how":"In a simple statement, normal word order is subject + verb + other information. Do not put an adjective before 'be' in 'The room is quiet'.","detail":"An adjective adds information to a noun. Many adjectives appear before nouns or after linking verbs such as be, seem and feel. Adjectives normally do not change for plural nouns.","rules":"Adjective position\nAn adjective often appears before a noun or after a linking verb. The adjective usually stays the same with\nsingular and plural nouns.\n\n EXAMPLE a useful report\n EXAMPLE two useful reports\n\n EXAMPLE The report is useful.","examples":["We work in a modern office.","The meeting is useful.","This is a quiet street.","It is a quiet office.","The offices are quiet.","She works in a busy hospital.","The office is quiet.","He has a reliable laptop.","They live in a small flat.","That is an important meeting."]},{"id":"017","title":"This, That, These and Those","level":"PRE-A1","module":3,"main":"Use 'this' and 'these' for people or things near you; use 'that' and 'those' for people or things farther away.","how":"'This' and 'that' are singular. 'These' and 'those' are plural. They can come before nouns or stand alone.","detail":"","rules":"Near and far; one and many\nThis and these refer to things nearer to the speaker or in the current discussion; that and those refer to\nmore distant things. Use singular or plural forms correctly.\n\n EXAMPLE this pen / these pens\n\n EXAMPLE that building / those buildings","examples":["This bag is mine.","Those buildings are new.","These files are for you.","That is my old laptop.","These are the documents you requested.","This document is important.","That office is closed.","These forms are ready.","Those cars belong to our neighbours.","Is this your ticket?"]},{"id":"018","title":"There Is and There Are","level":"PRE-A1","module":3,"main":"Use 'there is' for one thing and 'there are' for more than one thing. These phrases tell us that something exists in a place.","how":"In questions, put 'is' or 'are' first: 'Is there ...?' / 'Are there ...?'","detail":"","rules":"Agreement after there is and there are\nUse there is with one countable thing or an uncountable amount. Use there are with more than one\ncountable thing.\n\n  EXAMPLE There is a chair.\n  EXAMPLE There are three chairs.\n\n  EXAMPLE There is some milk.","examples":["There is a bank near my home.","There are two chairs in the room.","Is there a bus stop here?","There is a pharmacy nearby.","There are four people outside.","There is a lift near reception.","There are three people in the queue.","Is there a bus stop nearby?","There aren't any empty rooms.","There is some water on the table."]},{"id":"019","title":"Regular Plural Nouns and Basic ‐s Sounds","level":"PRE-A1","module":3,"main":"Most countable nouns make a plural with -s, but some take -es, such as 'boxes'. Pronunciation changes with the final sound.","how":"The ending may sound like /s/, /z/ or /iz/. Listen to 'cups', 'bags' and 'watches'.","detail":"","rules":"Rule 1 - Usually add -s\nMost countable singular nouns become plural with -s. This includes most nouns ending in a vowel letter\nplus y.\n\n EXAMPLE book -> books\n\n EXAMPLE car -> cars\n EXAMPLE key -> keys\n\n EXAMPLE boy -> boys\n\nRule 2 - Add -es after common hissing sounds\nAdd -es after endings such as -s, -ss, -sh, -ch and -x. The extra syllable usually sounds /ɪz/.\n\n EXAMPLE bus -> buses\n EXAMPLE class -> classes\n\n EXAMPLE dish -> dishes\n EXAMPLE watch -> watches\n\n EXAMPLE box -> boxes\n\nRule 3 - Consonant + y becomes -ies\nWhen a consonant comes directly before final y, change y to i and add -es. If a vowel comes before y,\nnormally keep the y and add -s.\n\n EXAMPLE city -> cities\n\n EXAMPLE baby -> babies\n EXAMPLE country -> countries\n\n EXAMPLE toy -> toys\n\n EXAMPLE day -> days\n\nRule 4 - Endings in -o need checking\nSome nouns ending in -o add -es, but many add only -s. There is no single spelling rule that works for every\n-o noun; check the dictionary for exceptions.\n\n EXAMPLE potato -> potatoes\n EXAMPLE tomato -> tomatoes\n EXAMPLE hero -> heroes\n\n EXAMPLE photo -> photos\n EXAMPLE piano -> pianos\n EXAMPLE video -> videos\n\nRule 5 - Some -f and -fe nouns take -ves\nSeveral common nouns change -f or -fe to -ves, but others simply take -s. Learn frequent examples and\ntheir exceptions.\n\n EXAMPLE leaf -> leaves\n\n EXAMPLE knife -> knives\n\n EXAMPLE wife -> wives\n EXAMPLE roof -> roofs\n\n EXAMPLE chief -> chiefs\n\nRule 6 - Plurals ending in -s have three common sounds\nThe sound depends on the end of the original word: /s/ after many voiceless sounds, /z/ after voiced\nsounds, and /ɪz/ after sibilant sounds.\n\n EXAMPLE cups (/s/)\n EXAMPLE bags (/z/)\n\n EXAMPLE watches (/ɪz/)","examples":["One desk, two desks.","One box, three boxes.","One bus, four buses.","One class, two classes.","One taxi, five taxis.","One chair, two chairs.","One watch, two watches.","One city, three cities.","One glass, two glasses.","One key, four keys."]},{"id":"020","title":"My, Your, His, Her, Our and Their","level":"PRE-A1","module":3,"main":"Possessive adjectives show who something belongs to: my, your, his, her, its, our, their. They appear before nouns.","how":"Do not use an apostrophe in 'its' when it means belonging to it. 'It's' means 'it is' or 'it has'.","detail":"","rules":"Possessive determiner vs possessive pronoun\nA possessive determiner needs a following noun: my bag. A possessive pronoun replaces the noun: mine.\nDo not use an apostrophe in yours, hers, ours or theirs.\n\n EXAMPLE This is my bag. / This bag is mine.\n\n EXAMPLE That is their office. / That office is theirs.","examples":["This is my ticket.","Their office is upstairs.","The company changed its policy.","Our manager is very helpful.","His desk is next to hers.","My office is on the first floor.","Your phone is ringing.","His manager is friendly.","Her bag is on the chair.","Our tickets are in the drawer."]},{"id":"021","title":"Have and Have Got: Talking About Possessions","level":"PRE-A1","module":3,"main":"Use 'have' to talk about possessions, relationships and experiences. 'Have got' often expresses possession in British English.","how":"'I have a car' and 'I've got a car' can mean the same thing. For routine actions such as breakfast, 'have' is used differently.","detail":"","rules":"Have vs have got\nIn many situations have and have got express possession. Have got is especially common in British\nconversation. Use does ... have? with have, but has ... got? with have got.\n\n EXAMPLE Does she have a car?\n EXAMPLE Has she got a car?\n\n EXAMPLE I haven’t got a car.","examples":["I have a laptop.","She's got two brothers.","We have breakfast at seven.","She has got a new phone.","Have they got any children?","I have a new passport.","We have two meetings today.","He has got a bicycle.","Have you got an umbrella?","They don't have a car."]},{"id":"022","title":"Basic Place Words: In, On, Under and Next To","level":"PRE-A1","module":3,"main":"Prepositions such as 'in', 'on', 'under' and 'next to' show location. Often a simple picture makes the meaning clear.","how":"Use 'in' for inside, 'on' for touching the top of a surface, and 'next to' for beside.","detail":"","rules":"In, on and at for place\nIn suggests an area or enclosed space, on suggests a surface, and at indicates a point or location. Real uses\ncan be idiomatic.\n\n EXAMPLE in the office\n EXAMPLE on the desk\n\n EXAMPLE at the station","examples":["The keys are in the bag.","The phone is on the table.","The printer is next to the window.","The receipt is inside the bag.","The hotel is opposite the station.","The keys are under the newspaper.","The restaurant is next to the bank.","Your name is on the form.","The shoes are in the cupboard.","The bus stop is opposite the hotel."]},{"id":"023","title":"Introduce Yourself: Name, Country, Work and Home","level":"PRE-A1","module":3,"main":"A short introduction gives your name and one or two useful facts about you. You do not need long sentences.","how":"For adult conversations, you may mention your work, city or reason for learning English. Ask the other person a simple question too.","detail":"","rules":"","examples":["Hello, I'm Ali. I'm from Doha.","I work in a hotel.","Nice to meet you. What do you do?","I am from Sri Lanka, and I live in Qatar.","I work in a clinic and study English after work.","My name is Nadia, and I am from Jordan.","I live in a small flat near the station.","I work in a travel agency.","I speak Arabic and some English.","I work at the city library."]},{"id":"024","title":"Foundation Review: Read, Listen, Speak and Check","level":"PRE-A1","module":3,"main":"Review makes new words and grammar easier to remember. Use this lesson to bring the first building blocks together.","how":"Check: greetings, alphabet, spelling, be, pronouns, articles, simple nouns and place words. If an answer is difficult, review the earlier lesson.","detail":"Clear communication involves listening, giving relevant information and checking understanding. Use expressions suited to the other person and the situation.","rules":"","examples":["I'm a nurse. I work in a clinic.","There are two desks in my office.","Are you from London? No, I'm not.","Could you explain that point, please?","To summarise, we recommend the second option.","This is my colleague, Aisha.","We are ready for today's lesson.","The folders are on the table.","I have a meeting at three o'clock.","Could you repeat the question, please?"]},{"id":"025","title":"Irregular Plurals and Common Noun Patterns","level":"A1","module":4,"main":"Some plural nouns do not follow the usual -s or -es rule. These forms must be learned and practised.","how":"Common pairs include person/people, child/children, man/men, woman/women, tooth/teeth and foot/feet.","detail":"","rules":"Vowel-changing irregular plurals\nSome nouns change a vowel inside the word rather than simply adding -s. These are common and should be\nlearned as pairs.\n\n EXAMPLE man -> men\n\n EXAMPLE woman -> women\n\n EXAMPLE foot -> feet\n EXAMPLE tooth -> teeth\n\n EXAMPLE mouse -> mice\n\nSpecial endings or completely different words\nA few plurals use special endings or a different word. A person has the plural people in normal everyday\nusage.\n\n EXAMPLE child -> children\n EXAMPLE person -> people\n\n EXAMPLE ox -> oxen\n\nNo change in the plural\nSome nouns have exactly the same form in the singular and plural. Meaning and nearby words indicate\nnumber.\n\n EXAMPLE one sheep / four sheep\n\n EXAMPLE one deer / two deer\n\n EXAMPLE one aircraft / three aircraft\n\nForeign-origin plurals and variable forms\nSome words from Latin or Greek use a special plural. Other words also have a common English plural;\nchoose the form appropriate to the field and variety of English.\n\n EXAMPLE criterion -> criteria\n EXAMPLE phenomenon -> phenomena\n\n EXAMPLE analysis -> analyses\n\n EXAMPLE index -> indexes or indices\n\nA useful caution about fish\nFish is often used as both singular and plural. Fishes can be used when talking about different kinds or\nspecies of fish.\n\n EXAMPLE one fish / six fish\n EXAMPLE several species of fishes","examples":["One person, three people.","The children are at school.","My feet are cold.","One mouse, two mice.","Her teeth are very healthy.","Two men are waiting outside.","Her children are at university.","One tooth, two teeth.","Several people joined the call.","The women work in finance."]},{"id":"026","title":"Countable and Uncountable Nouns: First Steps","level":"A1","module":4,"main":"Countable nouns can be counted: one chair, two chairs. Uncountable nouns are treated as a mass or general idea, such as 'water' or 'advice'.","how":"Use 'a piece of advice' rather than 'an advice'. Some words can be both countable and uncountable with different meanings.","detail":"","rules":"Countability can depend on meaning\nA word may be countable in one meaning and uncountable in another. For example, coffee is a drink in\ngeneral, but two coffees means two cups in a café.\n\n EXAMPLE some coffee / two coffees\n\n EXAMPLE glass (material) / two glasses (drinking vessels)\n\nCommon uncountable nouns that cause mistakes\nIn their normal sense, information, advice, furniture, luggage, equipment and homework are uncountable.\nUse a piece of, an item of or another measure when necessary.\n\n EXAMPLE some advice / a piece of advice\n EXAMPLE new equipment / a piece of equipment\n\n EXAMPLE useful information","examples":["I need two chairs.","We need more information.","Can I have a glass of water?","We bought four tickets.","Can you give me some information?","I bought three notebooks.","We need some advice.","How much water is left?","The chairs are in the hall.","There is very little traffic today."]},{"id":"027","title":"A, An, The and No Article: Everyday Uses","level":"A1","module":4,"main":"Use 'a/an' to introduce one singular countable thing and 'the' when both people know which thing is meant.","how":"Sometimes no article is needed with general plural nouns or uncountable nouns: 'Books are useful'; 'Water is important'.","detail":"Article choice depends on sound, number and whether the listener can identify the noun. Use a/an for one non-specific singular countable thing; the when the thing is known or identified.","rules":"Article meaning at a glance\nA/an introduces one non-specific countable item. The points to something identifiable from context. A\nplural or uncountable noun can have no article when speaking generally.\n\n EXAMPLE I bought a book. The book is useful.\n EXAMPLE Books are useful.\n\n EXAMPLE Water is essential.","examples":["I saw a shop. The shop was closed.","The report is on your desk.","Coffee helps me wake up.","I need a pen. The pen is on the desk.","She is an engineer.","I saw a doctor yesterday.","The doctor gave me advice.","She works in a hospital.","I bought a laptop. The laptop was expensive.","Please close the door."]},{"id":"028","title":"Object Pronouns: Me, Him, Her, Us and Them","level":"A1","module":4,"main":"Object pronouns receive the action or follow a preposition: me, you, him, her, it, us and them.","how":"Do not use a subject pronoun as the object of a verb: 'Please call me', not 'Please call I'.","detail":"","rules":"Subject vs object pronouns\nUse subject pronouns before the main verb and object pronouns after a verb or preposition.\n\n EXAMPLE She called him.\n EXAMPLE He called her.\n\n EXAMPLE Please send it to us.","examples":["Please email me.","I know her from work.","The manager spoke to us.","She called him after work.","They sent it to me yesterday.","Can you call him tomorrow?","They invited us for lunch.","Please give it to her.","The manager asked them to wait.","Could you help me with this form?"]},{"id":"029","title":"Possessive 's and Possessive Pronouns: Mine and Yours","level":"A1","module":4,"main":"Possessive 's often shows who owns something: 'Sara's phone'. Possessive pronouns stand alone: mine, yours, his, hers, ours, theirs.","how":"Compare 'This is my bag' with 'This bag is mine'. Do not add a noun after 'mine'.","detail":"","rules":"Apostrophe position changes meaning\nWith a singular owner, usually add apostrophe + s. With a regular plural already ending in s, add only an\napostrophe. Irregular plurals usually use apostrophe + s.\n\n EXAMPLE the manager’s desk\n EXAMPLE the managers’ desks\n\n EXAMPLE the children’s toys","examples":["That is David's desk.","The blue car is ours.","Is this your coat? Yes, it's mine.","This is my friend's bicycle.","That suitcase is hers.","This is Maria's passport.","That seat is mine.","Are these keys yours?","The largest office is theirs.","Our neighbour's car is blue."]},{"id":"030","title":"Adjectives: Describing People and Places","level":"A1","module":4,"main":"Adjectives give information about size, age, colour, quality or feeling. They help a listener imagine a person or place.","how":"Most adjectives do not change for plural nouns: 'two quiet rooms', not 'two quiets rooms'.","detail":"An adjective adds information to a noun. Many adjectives appear before nouns or after linking verbs such as be, seem and feel. Adjectives normally do not change for plural nouns.","rules":"Adjectives do not normally take plural -s\nEnglish adjectives usually stay unchanged before plural nouns; this differs from some languages.\n\n EXAMPLE one expensive phone\n\n EXAMPLE three expensive phones","examples":["The hotel has a large lobby.","Our new manager is friendly.","It is a comfortable chair.","It is a quiet office.","The offices are quiet.","She is a careful driver.","The station is very busy.","We stayed in a comfortable hotel.","He is an experienced nurse.","The new app is easy to use."]},{"id":"031","title":"Basic Adverbs: Very, Really and Well","level":"A1","module":4,"main":"Adverbs can change the meaning of a verb, adjective or another adverb. 'Very' and 'really' increase strength; 'well' describes how something is done.","how":"'Good' is often an adjective, while 'well' is often an adverb: 'She speaks well'.","detail":"Adverbs can describe how, when, where or how often something happens. Their position changes with the kind of adverb and the message you want to emphasise.","rules":"Adjective or adverb?\nMany adverbs describe how an action happens. An adjective usually describes a noun or follows a linking\nverb. Some adverbs do not end in -ly.\n\n EXAMPLE She is a careful driver.\n EXAMPLE She drives carefully.\n\n EXAMPLE He works hard. (not hardly)","examples":["The new system works well.","The meeting was very useful.","I really like this course.","She speaks clearly during meetings.","We usually arrive early.","She speaks very clearly.","The driver arrived early.","This idea is really helpful.","He explains the rule well.","The meeting went badly."]},{"id":"032","title":"Imperatives and Simple Polite Instructions","level":"A1","module":4,"main":"An imperative starts with the base form of a verb and gives an instruction. Add 'please' or use a question for a more polite tone.","how":"Negative imperatives use 'don't': 'Don't open that file'. In professional settings, consider whether a softer request is better.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"","examples":["Please take a seat.","Turn left at the next street.","Don't share your password.","Please enter your name here.","Don't leave the door open.","Please close the window.","Sign your name here.","Do not touch that button.","Turn right after the bank.","Please wait for your number."]},{"id":"033","title":"Practice: Meet a Colleague and Describe Your Workplace","level":"A1","module":4,"main":"Use several simple patterns together when meeting a colleague: greetings, 'be', jobs, questions and descriptions.","how":"Listen for the other person's answer, then ask a follow-up question instead of repeating the same question.","detail":"","rules":"","examples":["Hi, I'm Noor. I work in accounts.","Where do you work? I work on the third floor.","Our office is busy but friendly.","I am a new member of the team.","The meeting room is next to reception.","This is my colleague, Nadia.","Our office opens at eight.","My department is on the second floor.","We have a small meeting room.","What do you do in your role?"]},{"id":"034","title":"Present Simple: I, You, We and They","level":"A1","module":5,"main":"The present simple describes habits, routines and facts. With I, you, we and they, use the base verb in positive sentences.","how":"Time expressions such as 'every day' and 'on Mondays' often appear with this tense.","detail":"Use the present simple for routines, habits, general facts and many timetables. Questions and negatives usually need do or does; be is different.","rules":"Present simple: base form for most subjects\nUse the base verb with I, you, we and they for habits, routines and general facts. Use do/don’t in questions\nand negatives, not the -s form.\n\n EXAMPLE I work. / We work.\n EXAMPLE Do they work?\n\n EXAMPLE They do not work.","examples":["I start work at nine.","We live near the station.","They usually travel by train.","I start work at eight.","Does she work on Fridays?","I check my emails every morning.","You work very hard.","We take the train to work.","They visit their family on Sundays.","I usually finish at five."]},{"id":"035","title":"Present Simple: He, She and It","level":"A1","module":5,"main":"In the present simple, he, she and it usually take a verb ending in -s or -es. Some verbs change spelling, such as 'study' to 'studies'.","how":"Use 'has' rather than 'haves' and 'does' rather than 'dos'.","detail":"Use the present simple for routines, habits, general facts and many timetables. Questions and negatives usually need do or does; be is different.","rules":"Rule 1 - Add -s after he, she or it\nMost verbs take -s in the third-person singular present simple. It also applies to a single name or singular\nnoun.\n\n EXAMPLE she works\n EXAMPLE he reads\n\n EXAMPLE the shop opens\n\nRule 2 - Add -es after -s, -ss, -sh, -ch, -x or -z\nThe ending is normally a separate /ɪz/ sound for verbs like watches and finishes.\n\n EXAMPLE he watches\n\n EXAMPLE she washes\n EXAMPLE it passes\n\n EXAMPLE he fixes\n\nRule 3 - Consonant + y changes to -ies\nChange final y to i and add -es after a consonant. After vowel + y, normally add -s.\n\n EXAMPLE she studies\n\n EXAMPLE he tries\n EXAMPLE it flies\n\n EXAMPLE she plays\n\n EXAMPLE he enjoys\n\nRule 4 - Important exceptions\nGo and do add -es; have changes to has. Be is completely irregular: he is, not he bes.\n\n EXAMPLE go -> goes\n EXAMPLE do -> does\n EXAMPLE have -> has\n EXAMPLE be -> is\n\nDo not add -s after does in negatives or questions\nThe auxiliary does already shows the third-person singular. The main verb stays in its base form.\n\n EXAMPLE She works.\n EXAMPLE Does she work? (not works)\n\n EXAMPLE She doesn’t work. (not works)","examples":["She works in a bank.","He watches the news.","My sister studies English.","I start work at eight.","Does she work on Fridays?","She lives near the market.","He goes to the gym after work.","The office opens at nine.","My sister studies in London.","Our manager checks the reports."]},{"id":"036","title":"Present Simple: Negative Sentences","level":"A1","module":5,"main":"Make present simple negatives with do not/don't + base verb, or does not/doesn't + base verb for he, she and it.","how":"After 'doesn't', do not add -s to the main verb: 'She doesn't work'.","detail":"Use the present simple for routines, habits, general facts and many timetables. Questions and negatives usually need do or does; be is different.","rules":"Do not + base verb; does not + base verb\nAfter do not or does not, the main verb stays in base form. Contract do not to don’t and does not to doesn’t\nwhen suitable.\n\n EXAMPLE I don’t work on Sundays.\n\n EXAMPLE She doesn’t work on Sundays.","examples":["I don't drink coffee.","He doesn't drive to work.","They don't open on Sundays.","I start work at eight.","Does she work on Fridays?","I don't work on Saturdays.","She doesn't eat meat.","They don't live in this city.","He doesn't like loud music.","We don't start work before eight."]},{"id":"037","title":"Do and Does: Yes/No Questions","level":"A1","module":5,"main":"Present simple yes/no questions begin with do or does, then the subject and the base verb.","how":"Use 'does' with he, she and it. Answer with 'Yes, I do' or 'No, she doesn't' as appropriate.","detail":"","rules":"Do and does question pattern\nPut do/does before the subject and then use the base verb. If the main verb is be, use am/is/are directly\ninstead.\n\n EXAMPLE Do you drive?\n EXAMPLE Does he drive?\n\n EXAMPLE Is he ready?","examples":["Do you work nearby?","Does she speak Arabic?","Do they have a car?","Does your brother work here?","Do you need a receipt?","Do you need any help?","Does your brother drive?","Do they live near here?","Does the shop open on Sunday?","Do we have enough time?"]},{"id":"038","title":"Wh‐ Questions: What, Where, When and Why","level":"A1","module":5,"main":"Wh- questions ask for specific information. What asks about things, where about places, when about time and why about reasons.","how":"In many present simple questions, use question word + do/does + subject + base verb.","detail":"","rules":"Who as subject or object\nWhen who is the subject, a present-simple question may not need do or does. When who is the object, it\nnormally does.\n\n EXAMPLE Who called you?\n\n EXAMPLE Who did you call?","examples":["Where do you live?","What does he do?","Why do they leave early?","When does the shop close?","Why is the bus late?","Where does your sister work?","What time do you start?","When is the next meeting?","Why are you worried?","Who is waiting outside?"]},{"id":"039","title":"Adverbs of Frequency: Always to Never","level":"A1","module":5,"main":"Frequency adverbs say how often something happens: always, usually, often, sometimes, rarely, never.","how":"They normally go before a main verb but after 'be': 'She is usually early'.","detail":"Adverbs can describe how, when, where or how often something happens. Their position changes with the kind of adverb and the message you want to emphasise.","rules":"Where frequency adverbs go\nPut always, usually, often, sometimes and never before most main verbs, but after be.\n\n EXAMPLE She often works late.\n\n EXAMPLE She is often busy.","examples":["I always check my email in the morning.","He sometimes takes the bus.","Our team is usually busy.","She speaks clearly during meetings.","We usually arrive early.","She usually arrives early.","I rarely eat fast food.","We often talk after work.","He never misses an appointment.","They sometimes work from home."]},{"id":"040","title":"Dates, Days, Clock Times and Schedules","level":"A1","module":5,"main":"Use days, months, dates and clock times to discuss schedules. Common forms include 'Monday', '14 May' and 'half past three'.","how":"Say dates clearly and check whether a time is in the morning or evening. Written date order may differ between countries.","detail":"In English, information such as dates, prices and phone numbers needs to be both clear and exact. Say numbers in groups and repeat important details when needed.","rules":"Writing dates in British English\nBritish writing usually uses day-month-year ordering. Write a date in words if numeric order could be\nmisunderstood internationally.\n\n EXAMPLE 24 October 2026\n\n EXAMPLE 24/10/2026 (British order)","examples":["The meeting is on Tuesday.","My flight leaves at 6.45 p.m.","The course starts on the tenth of June.","The meeting starts at nine thirty.","The total is eighteen pounds fifty.","My appointment is on Thursday.","The train arrives at 07:20.","The office closes at half past five.","The conference is on 12 June.","I was born in September."]},{"id":"041","title":"Prepositions of Time: At, On and In","level":"A1","module":5,"main":"Use 'at' with exact times, 'on' with days and dates, and 'in' with months, years and parts of the day.","how":"Say 'at night', not 'in the night' for the usual time expression. There are other fixed exceptions.","detail":"A preposition connects information about place, time, direction or another relationship. Many choices are learned as fixed patterns: interested in, depend on, at night.","rules":"At, on and in: basic timetable rule\nUse at for clock times, on for days and dates, and in for months, seasons and years. No preposition is\nnormally used before next, last or this.\n\n EXAMPLE at 8:30\n\n EXAMPLE on Monday\n EXAMPLE in October\n\n EXAMPLE next Friday (not on next Friday)","examples":["The class starts at eight.","I work on Fridays.","We travel in December.","The files are on the shelf.","We arrived at the station.","We meet at noon.","I was born in 1998.","The class is on Wednesday.","She works in the evening.","Our holiday starts in August."]},{"id":"042","title":"Practice: Describe a Typical Working Day","level":"A1","module":5,"main":"A useful daily-routine description uses the present simple, time words and frequency adverbs.","how":"Put events in order: first, then, after that and finally. Choose times you can say confidently.","detail":"","rules":"","examples":["I get up at six.","I usually take the bus to work.","After work, I cook dinner.","I leave for work at seven thirty.","In the evening, I read for half an hour.","I leave home at seven.","I make breakfast before work.","I check my schedule every morning.","I meet clients in the afternoon.","I usually go to bed at ten."]},{"id":"043","title":"Present Continuous: Positive Sentences","level":"A1","module":6,"main":"Use the present continuous for actions happening now or around now: am/is/are + verb-ing.","how":"Spelling may change: 'make' becomes 'making'; 'run' becomes 'running'.","detail":"Use am, is or are plus an -ing form for actions in progress, temporary situations or certain future arrangements. Some state verbs are not normally used this way.","rules":"Pattern: am/is/are + verb-ing\nChoose the correct form of be and then use the -ing form. It does not describe every present action; for\ngeneral routines use the present simple.\n\n EXAMPLE I am reading.\n EXAMPLE She is reading.\n\n EXAMPLE We are reading.\n\n-ing rule 1 - Usually add -ing\nFor most verbs, simply add -ing. Final y normally stays as y.\n\n EXAMPLE work -> working\n\n EXAMPLE play -> playing\n EXAMPLE study -> studying\n\n EXAMPLE carry -> carrying\n\n-ing rule 2 - Drop silent final -e\nUsually remove a final silent e before adding -ing. Keep -e in common endings -ee and -ye; do not confuse\ndyeing with dying.\n\n EXAMPLE make -> making\n\n EXAMPLE write -> writing\n EXAMPLE agree -> agreeing\n\n EXAMPLE see -> seeing\n\n EXAMPLE dye -> dyeing\n\n-ing rule 3 - Change -ie to -ying\nWith verbs ending in -ie, replace ie with y before -ing.\n\n EXAMPLE die -> dying\n EXAMPLE lie -> lying\n EXAMPLE tie -> tying\n\n-ing rule 4 - Double the last consonant in common short patterns\nFor many one-syllable verbs ending in one vowel letter + one consonant letter, double the last consonant;\ndo not double w, x or y. In longer verbs, stress often decides.\n\n EXAMPLE run -> running\n EXAMPLE sit -> sitting\n\n EXAMPLE stop -> stopping\n\n EXAMPLE swim -> swimming\n EXAMPLE fix -> fixing\n\n EXAMPLE play -> playing\n\n-ing rule 5 - Stress and British -l spelling\nLonger verbs typically double a final consonant if the final syllable is stressed. British English often doubles\nfinal l in travelling even without final stress.\n\n EXAMPLE begin -> beginning\n\n EXAMPLE prefer -> preferring\n EXAMPLE visit -> visiting\n\n EXAMPLE travel -> travelling (British)\n\nCommon -ing spelling mistakes\nCheck the written form before recording the sentence. Frequent mistakes include makeing, runing, lieing\nand studing.\n\n EXAMPLE making (not makeing)\n EXAMPLE running (not runing)\n\n EXAMPLE lying (not lieing)\n\n EXAMPLE studying (not studing)","examples":["I am reading a message.","The receptionist is speaking to a guest.","They are waiting outside.","I am reading an email now.","We are meeting the client tomorrow.","She is reading a message.","We are waiting for a taxi.","The receptionist is helping a guest.","I am preparing dinner.","They are having a meeting."]},{"id":"044","title":"Present Continuous: Negatives and Questions","level":"A1","module":6,"main":"Make present continuous negatives with 'not' after am/is/are. Form questions by moving am/is/are before the subject.","how":"Short answers repeat the auxiliary: 'Are they coming? Yes, they are'.","detail":"Use am, is or are plus an -ing form for actions in progress, temporary situations or certain future arrangements. Some state verbs are not normally used this way.","rules":"Present continuous negatives and questions\nPlace not after am/is/are for negatives. For yes/no questions, move am/is/are before the subject.\n\n EXAMPLE He is working.\n EXAMPLE He isn’t working.\n\n EXAMPLE Is he working?","examples":["I am not using this computer.","Is he working today?","Are you listening? Yes, I am.","I am reading an email now.","We are meeting the client tomorrow.","He isn't driving today.","Are you studying now?","They aren't using the lift.","Is she working this evening?","Why are you smiling?"]},{"id":"045","title":"Present Simple vs Present Continuous","level":"A1","module":6,"main":"Present simple is often for regular habits and facts; present continuous is for actions happening now or temporary situations.","how":"Some state verbs, such as 'know', are not normally continuous when they describe a state.","detail":"Use the present simple for routines, habits, general facts and many timetables. Questions and negatives usually need do or does; be is different.","rules":"Present simple vs present continuous\nPresent simple commonly reports routines, facts and longer-term patterns; present continuous often\nreports current or temporary activity. Some state verbs resist continuous forms in their state meaning.\n\n EXAMPLE I work in a bank. / I’m working from home this week.\n\n EXAMPLE She knows the answer. (not usually is knowing)","examples":["I walk to work every day.","I'm walking to work right now.","She knows the answer.","I start work at eight.","Does she work on Fridays?","I normally drink tea, but today I'm drinking coffee.","She works in a bank, but she is working from home today.","We usually walk, but we are taking the bus now.","He reads the news every morning; he is reading it now.","The shop opens at nine, but it is closed today."]},{"id":"046","title":"Like, Love, Hate and Enjoy + ‐ing","level":"A1","module":6,"main":"After enjoy, like, love and hate, an -ing form is common when speaking about activities. 'Like to' is also possible in some meanings.","how":"Do not follow 'enjoy' directly with 'to' + verb: 'I enjoy reading', not 'I enjoy to read'.","detail":"","rules":"After enjoy, use -ing\nEnjoy is followed by the -ing form, not to + verb. Like and love can often take either form, though context\nmay affect preference.\n\n EXAMPLE I enjoy reading.\n EXAMPLE She likes reading.\n\n EXAMPLE She likes to read.","examples":["I enjoy learning English.","He likes cooking at home.","They hate waiting in long queues.","She enjoys listening to podcasts.","I hate sitting in traffic.","I love walking by the sea.","She enjoys reading at night.","They hate waiting in queues.","We like cooking together.","He doesn't mind working late."]},{"id":"047","title":"Can and Cannot: Ability","level":"A1","module":6,"main":"'Can' expresses present ability. Use the same form with every subject: I can, she can, they can.","how":"After a modal such as 'can', use the base verb without 'to' or -s. 'Cannot' and 'can't' are negative.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"After modal can, use the bare verb\nCan is the same for all subjects. Never add -s or to after it.\n\n EXAMPLE He can swim. (not can swims)\n EXAMPLE She cannot drive.\n\n EXAMPLE Can you help?","examples":["I can swim.","She can speak three languages.","He can't drive yet.","You should check the address.","She might arrive late.","I can type quickly.","She can't drive at night.","Can you swim?","They can speak two languages.","He cannot come to the meeting."]},{"id":"048","title":"Can and Could: Simple Requests","level":"A1","module":6,"main":"'Can you ...?' and 'Could you ...?' are common requests. 'Could' usually sounds a little more polite or less direct.","how":"Use the base verb after both forms. Add 'please' when appropriate; a friendly tone also matters.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Could and can in requests\nCould you ...? is often more tentative or polite than Can you ...? Both are commonly used for requests.\n\n EXAMPLE Can you open the window?\n\n EXAMPLE Could you open the window, please?","examples":["Can you help me, please?","Could you send the file today?","Could I have a receipt, please?","You should check the address.","She might arrive late.","Could you open the window, please?","Can I borrow your pen?","Could you repeat the address?","Can you send me a copy?","Could I speak to the manager?"]},{"id":"049","title":"How Much and How Many: Asking About Quantity","level":"A1","module":6,"main":"Use 'how many' with plural countable nouns and 'how much' with uncountable nouns or prices.","how":"Ask 'How much does it cost?' for price. For a countable item, 'How many tickets ...?' is natural.","detail":"","rules":"Many + countable / much + uncountable\nAsk how many about countable items and how much about uncountable amounts or price.\n\n EXAMPLE How many tickets?\n EXAMPLE How much rice?\n\n EXAMPLE How much is this ticket?","examples":["How many chairs do we need?","How much time do we have?","How much is this jacket?","How much luggage do you have?","How many days will you stay?","How many people are coming?","How much coffee do you drink?","How many tickets should we buy?","How much money do we need?","How much luggage can I take?"]},{"id":"050","title":"Some, Any and A Lot Of","level":"A1","module":6,"main":"'Some' is common in positive sentences; 'any' is common in questions and negatives. 'A lot of' works with many countable and uncountable nouns.","how":"Offers and requests often use 'some': 'Would you like some water?'","detail":"","rules":"Some and any are not absolute rules\nSome is common in positive statements and offers/requests. Any is common in many questions and\nnegatives. Context and meaning matter.\n\n EXAMPLE I have some bread.\n EXAMPLE I don’t have any bread.\n\n EXAMPLE Would you like some tea?","examples":["We have some information.","There aren't any seats left.","She has a lot of work.","There is some milk in the fridge.","We don't have any spare keys.","We need some chairs.","Do you have any questions?","She has a lot of experience.","There isn't any milk left.","I bought some fruit at the market."]},{"id":"051","title":"Practice: Shopping, Restaurants and Phone Calls","level":"A1","module":6,"main":"Combine requests, present tenses and quantity questions in shops, cafés and telephone conversations.","how":"Start with a greeting, explain what you need and close politely. Check prices or dates before agreeing.","detail":"","rules":"","examples":["Could I have two coffees, please?","How much does delivery cost?","May I speak to the manager, please?","I'd like to order a vegetable soup.","Do you have this shirt in a larger size?","Could I see the menu, please?","I'd like a table for two.","How much is this jacket?","Can I pay by card?","Could you tell me when the order will arrive?"]},{"id":"052","title":"Was and Were: Be in the Past","level":"A1","module":7,"main":"'Was' and 'were' are the past forms of 'be'. Use 'was' with I/he/she/it and 'were' with you/we/they.","how":"Use 'wasn't' and 'weren't' for negatives; invert the verb for questions.","detail":"","rules":"Was vs were\nUse was with I/he/she/it and were with you/we/they. In formal unreal conditions, were is often used with\nI/he/she/it: If I were you ...\n\n EXAMPLE I was tired.\n EXAMPLE They were late.\n\n EXAMPLE If I were you, I would wait.","examples":["I was tired yesterday.","They were at the conference.","Were you at home last night?","We were in the same class last year.","Was the shop open on Sunday?","I was at home last night.","They were very busy yesterday.","The meeting was useful.","Were you tired after work?","She wasn't in the office."]},{"id":"053","title":"Past Simple: Regular Verbs","level":"A1","module":7,"main":"For many regular verbs, the past simple ends in -ed. We use it for finished past actions.","how":"Spelling varies: 'live' becomes 'lived', 'stop' becomes 'stopped', and 'study' becomes 'studied'.","detail":"Use the past simple for finished past events. In negatives and most questions, use did plus the base form, not the past form.","rules":"Regular past rule 1 - Add -ed\nMost regular verbs make the past simple and past participle by adding -ed.\n\n EXAMPLE work -> worked\n EXAMPLE clean -> cleaned\n\n EXAMPLE open -> opened\n\nRegular past rule 2 - Final -e takes only -d\nIf the base form already ends in e, add d, not a second e.\n\n EXAMPLE live -> lived\n EXAMPLE move -> moved\n\n EXAMPLE arrive -> arrived\n\nRegular past rule 3 - Consonant + y becomes -ied\nChange y to i and add -ed after a consonant. Keep y after a vowel.\n\n EXAMPLE study -> studied\n EXAMPLE carry -> carried\n\n EXAMPLE play -> played\n\n EXAMPLE enjoy -> enjoyed\n\nRegular past rule 4 - Doubling the last consonant\nMany verbs ending in consonant-vowel-consonant double the final consonant when stressed before -ed.\nBritish spelling often doubles final l.\n\n EXAMPLE stop -> stopped\n\n EXAMPLE plan -> planned\n EXAMPLE prefer -> preferred\n\n EXAMPLE visit -> visited\n\n EXAMPLE travel -> travelled (British)\n\nThree common -ed pronunciations\nThe spelling -ed is pronounced /t/ after some voiceless sounds, /d/ after voiced sounds, and /ɪd/ after a /t/\nor /d/ sound.\n\n EXAMPLE worked /t/\n\n EXAMPLE cleaned /d/\n EXAMPLE wanted /ɪd/\n EXAMPLE needed /ɪd/","examples":["I visited a client yesterday.","She worked late on Monday.","They stopped for lunch.","We visited the office yesterday.","Did you call the supplier?","I cleaned the kitchen yesterday.","She called the customer.","We booked a hotel room.","They finished early.","He studied English last night."]},{"id":"054","title":"Past Simple: Common Irregular Verbs","level":"A1","module":7,"main":"Irregular verbs have special past forms that must be learned through repeated use.","how":"Common changes include go/went, see/saw, buy/bought, have/had and take/took.","detail":"Use the past simple for finished past events. In negatives and most questions, use did plus the base form, not the past form.","rules":"Irregular verb types\nIrregular verbs do not use the normal -ed past rule. Some keep all forms unchanged; some have the same\npast and participle; others have three different forms.\n\n EXAMPLE put / put / put\n\n EXAMPLE buy / bought / bought\n EXAMPLE take / took / taken\n\n EXAMPLE sing / sang / sung\n\nDo not use a past form after did\nAfter did or didn’t, return to the base verb. Remember that the past participle is not always the same as the\npast simple.\n\n EXAMPLE I went. / Did you go? (not went)\n\n EXAMPLE She saw it. / She didn’t see it.\n\nHigh-frequency irregular verb families\nLearning related patterns makes irregular verbs easier to remember. Read the three forms aloud as a group.\n\n EXAMPLE bring / brought / brought\n EXAMPLE think / thought / thought\n\n EXAMPLE teach / taught / taught\n\n EXAMPLE find / found / found","examples":["I went to the bank.","She bought a new phone.","We had a meeting yesterday.","We visited the office yesterday.","Did you call the supplier?","I took a taxi to work.","She wrote a short email.","We ate lunch at noon.","They bought new chairs.","He saw his manager yesterday."]},{"id":"055","title":"Past Simple: Negative Sentences","level":"A1","module":7,"main":"Use did not/didn't + base verb to make a past simple negative, even when the positive past form is irregular.","how":"Do not say 'didn't went'. 'Did' already shows past time.","detail":"Use the past simple for finished past events. In negatives and most questions, use did plus the base form, not the past form.","rules":"Negatives after did\nUse did not + base verb to make most past simple negatives. Be is special: was not / were not.\n\n EXAMPLE They didn’t travel.\n\n EXAMPLE He wasn’t ready.","examples":["I didn't work yesterday.","He didn't buy the tickets.","They didn't go out last night.","We visited the office yesterday.","Did you call the supplier?","I didn't see the message.","She didn't take the train.","We didn't finish the report.","He didn't come to work.","They didn't buy the tickets."]},{"id":"056","title":"Past Simple: Questions","level":"A1","module":7,"main":"Past simple questions normally use did + subject + base verb. 'Be' is an exception: 'Were you ...?'","how":"'When did you arrive?' asks about a completed past event. Answer naturally with a past verb.","detail":"Use the past simple for finished past events. In negatives and most questions, use did plus the base form, not the past form.","rules":"Past questions after did\nUse Did + subject + base verb; never use the past form after did.\n\n EXAMPLE Did she buy it? (not bought)\n\n EXAMPLE When did they arrive?","examples":["Did you call the hotel?","Where did she go?","Were they late?","We visited the office yesterday.","Did you call the supplier?","Did she call you yesterday?","Where did you stay?","Did they finish on time?","What did he say?","When did the flight arrive?"]},{"id":"057","title":"Yesterday, Last, Ago and Story Order","level":"A1","module":7,"main":"Time expressions show when a past action happened: yesterday, last week, two days ago.","how":"For a clear short story, use 'first', 'then', 'after that' and 'finally'.","detail":"","rules":"Past-time phrases\nYesterday, last month, two days ago and in 2020 refer to finished past times. With these expressions, the\npast simple is normally used.\n\n  EXAMPLE I called yesterday.\n\n  EXAMPLE We met two years ago.","examples":["I arrived yesterday.","We met two years ago.","First, we checked in; then we found our room.","I booked the hotel three weeks ago.","Finally, the plane arrived at midnight.","Last week, I visited a museum.","I sent the form two days ago.","First, I called the office; then I travelled there.","We arrived late yesterday.","She changed jobs a month ago."]},{"id":"058","title":"Be Going To: Plans and Intentions","level":"A1","module":7,"main":"Use 'be going to' + base verb for intentions and plans already decided, and for predictions based on clear present evidence.","how":"Use am/is/are before 'going to'. 'I going to' is not a full standard sentence.","detail":"","rules":"Going to: plans and evidence\nUse be going to + base verb for plans and predictions based on present evidence. Be must agree with the\nsubject.\n\n EXAMPLE I am going to apply.\n\n EXAMPLE Look at those clouds. It is going to rain.","examples":["I'm going to study tonight.","She is going to change jobs.","Look at those clouds. It's going to rain.","Are you going to change jobs?","We're going to visit our relatives next weekend.","We're going to move next month.","He's going to call the bank.","I'm going to cook this evening.","Are you going to study tomorrow?","They aren't going to sell the car."]},{"id":"059","title":"Will: Basic Predictions and Decisions","level":"A1","module":7,"main":"'Will' + base verb is common for decisions made now, offers, promises and many predictions.","how":"We often use 'I think' with predictions. The contracted form 'I'll' is common in conversation.","detail":"","rules":"Will: decisions and predictions\nWill + base verb is often used for decisions made now, promises and predictions. It does not take -s with\nhe/she/it.\n\n EXAMPLE I’ll call you later.\n\n EXAMPLE She will help. (not will helps)","examples":["I'll carry that bag for you.","I think it will rain tomorrow.","Don't worry, I'll call you later.","I think you will enjoy the course.","I'll open the window for you.","I think prices will rise.","I'll help you with those bags.","She will probably be late.","Don't worry; I'll call a taxi.","It won't take long."]},{"id":"060","title":"A1 Review and Level Check: Everyday Situations","level":"A1","module":7,"main":"This level check reviews everyday A1 tasks, including routines, past actions, plans and simple conversations.","how":"Make sure you can write and say short sentences without copying. Review any lesson where you make repeated mistakes.","detail":"","rules":"","examples":["She works in a shop.","They visited us last Saturday.","We're going to travel in June.","He doesn't live near the station.","We visited the museum last weekend.","I work in a hospital.","Yesterday, we visited our neighbours.","Are you going to travel next month?","She can't attend the meeting.","There were six people in the room."]},{"id":"061","title":"Comparative Adjectives: Bigger and More Useful","level":"A2","module":8,"main":"Use a comparative adjective to compare two things. Short adjectives often take -er; longer adjectives often use 'more'.","how":"Use 'than' to name the second item. Common irregular forms include good/better and bad/worse.","detail":"An adjective adds information to a noun. Many adjectives appear before nouns or after linking verbs such as be, seem and feel. Adjectives normally do not change for plural nouns.","rules":"Comparative spelling patterns\nShort adjectives often use -er; longer adjectives often use more. Double a final consonant in big -> bigger\nand change consonant + y in happy -> happier.\n\n EXAMPLE small -> smaller\n\n EXAMPLE big -> bigger\n EXAMPLE happy -> happier\n\n EXAMPLE useful -> more useful\n\nIrregular comparative forms\nA few high-frequency adjectives have special forms. Do not say more better.\n\n EXAMPLE good -> better\n EXAMPLE bad -> worse\n\n EXAMPLE far -> farther/further","examples":["This train is faster than the bus.","The new software is more useful.","The second option is better.","It is a quiet office.","The offices are quiet.","This road is wider than that one.","My new phone is lighter.","Taking the train is cheaper than driving.","The second test was more difficult.","This office is quieter than ours."]},{"id":"062","title":"Superlatives: The Best and The Most Helpful","level":"A2","module":8,"main":"A superlative compares one person or thing with a whole group. Use 'the' with most superlatives.","how":"Short adjectives often take -est; longer adjectives often take 'most'. Good becomes best, and bad becomes worst.","detail":"Comparisons depend on what you compare and how many things are involved. Short adjectives often use -er/-est; longer ones often use more/most.","rules":"Superlative spelling and article\nShort adjectives usually take -est; longer ones use most. We normally use the before a superlative.\n\n EXAMPLE big -> the biggest\n\n EXAMPLE happy -> the happiest\n EXAMPLE useful -> the most useful\n\n EXAMPLE good -> the best","examples":["This is the cheapest ticket.","She is the most experienced person on the team.","Monday was the busiest day.","This room is quieter than that one.","It is the most useful option.","This is the safest route.","She is the youngest member of the team.","Monday is our busiest day.","That was the most useful workshop.","This is the least expensive option."]},{"id":"063","title":"As ... As and Not As ... As","level":"A2","module":8,"main":"Use 'as + adjective + as' to say two things are equal in a particular way.","how":"Use 'not as ... as' when one thing has less of that quality. The adjective stays in its basic form.","detail":"","rules":"Equality with as ... as\nUse the base adjective between two as words. A negative comparison uses not as ... as.\n\n  EXAMPLE This room is as large as that one.\n\n  EXAMPLE This laptop is not as expensive as the other.","examples":["This room is as bright as that one.","The bus isn't as fast as the train.","My phone is as useful as my laptop.","The new desk is as wide as the old one.","Today isn't as warm as yesterday.","My room is as large as yours.","This job isn't as stressful as the last one.","She speaks as clearly as her teacher.","The second plan is as good as the first.","The taxi isn't as cheap as the bus."]},{"id":"064","title":"Adverbs of Manner and Simple Comparisons","level":"A2","module":8,"main":"An adverb of manner explains how an action happens. Many end in -ly, such as 'carefully' and 'slowly'.","how":"Some have special forms: 'good' becomes 'well'; 'fast' is both an adjective and adverb. Adverbs can also be compared.","detail":"Adverbs can describe how, when, where or how often something happens. Their position changes with the kind of adverb and the message you want to emphasise.","rules":"Adverb spelling exceptions\nMany adverbs use -ly, but words such as fast and hard are already adverbs. Good becomes well when\ndescribing how an action is performed.\n\n EXAMPLE careful -> carefully\n\n EXAMPLE good -> well\n EXAMPLE fast -> fast\n\n EXAMPLE hard -> hard","examples":["Please drive carefully.","She speaks more clearly now.","He works hard every day.","She speaks clearly during meetings.","We usually arrive early.","Please speak slowly.","She answered politely.","He drives more carefully now.","The new printer works faster.","The receptionist explained everything clearly."]},{"id":"065","title":"Too and Enough: Problems and Solutions","level":"A2","module":8,"main":"'Too' before an adjective means more than needed, often creating a problem. 'Enough' means sufficient.","how":"Put 'enough' after an adjective, but before a noun: 'warm enough' and 'enough time'.","detail":"","rules":"Too vs enough\nToo + adjective signals more than wanted; adjective + enough means sufficient. Enough comes before a\nnoun.\n\n EXAMPLE too expensive\n EXAMPLE warm enough\n\n EXAMPLE enough time","examples":["It's too noisy to work here.","We have enough chairs.","The coffee isn't hot enough.","The box is too large for this shelf.","They have not practised enough to take the test.","The suitcase is too heavy to carry.","I am not old enough to retire.","We have enough food for everyone.","The music is too loud.","She is experienced enough to lead the team."]},{"id":"066","title":"Much, Many, A Few, Few, A Little and Little","level":"A2","module":8,"main":"'Many' and 'few' go with plural countable nouns; 'much' and 'little' go with uncountable nouns.","how":"'A few' and 'a little' suggest some amount, often enough. 'Few' and 'little' emphasise a small, perhaps insufficient amount.","detail":"","rules":"A few vs few; a little vs little\nA few and a little usually mean some and are more positive; few and little often stress insufficiency. Use the\nfirst pair for countables and the second for uncountables.\n\n EXAMPLE a few colleagues / few colleagues\n\n EXAMPLE a little money / little money","examples":["We have a few questions.","There is little time left.","How many visitors came?","There are a few seats available.","We have little information about the delay.","We don't have many chairs.","There isn't much coffee left.","A few people arrived early.","Very few tickets are available.","We have a little time before the train."]},{"id":"067","title":"Articles: The and Zero Article in Common Contexts","level":"A2","module":8,"main":"Use 'the' when referring to something specific or already known. Use no article for general plural nouns and many general uncountable nouns.","how":"Fixed places and names may follow special patterns. Check individual examples in a learner's dictionary.","detail":"Article choice depends on sound, number and whether the listener can identify the noun. Use a/an for one non-specific singular countable thing; the when the thing is known or identified.","rules":"Zero article when talking generally\nDo not usually use the for plural or uncountable nouns when referring to things in general. Use the when\nthe listener can identify the specific thing.\n\n EXAMPLE Dogs need exercise.\n\n EXAMPLE The dogs in my garden are friendly.","examples":["The manager in the blue jacket is here.","Doctors need clear information.","The water in this bottle is cold.","I need a pen. The pen is on the desk.","She is an engineer.","I met the doctor you mentioned.","The moon looks bright tonight.","Employees need regular breaks.","She plays tennis on weekends.","The Nile is a long river."]},{"id":"068","title":"Prepositions of Movement and Direction","level":"A2","module":8,"main":"Prepositions such as into, out of, across, along, through and towards show direction or movement.","how":"Compare 'in' (position) with 'into' (movement to the inside). Use an arrow or map when you practise.","detail":"A preposition connects information about place, time, direction or another relationship. Many choices are learned as fixed patterns: interested in, depend on, at night.","rules":"Movement prepositions are not interchangeable\nTo shows destination, into shows movement from outside to inside, onto shows movement to a surface,\nand through shows movement across an enclosed space.\n\n EXAMPLE go to the office\n\n EXAMPLE walk into the room\n EXAMPLE step onto the bus\n\n EXAMPLE walk through the tunnel","examples":["Walk across the bridge.","Go through the tunnel.","She walked into the office.","The files are on the shelf.","We arrived at the station.","Walk towards the entrance.","Drive past the petrol station.","Go up the stairs.","The cat ran under the table.","We walked along the river."]},{"id":"069","title":"Practice: Compare Jobs, Services and Cities","level":"A2","module":8,"main":"Compare two jobs, cities or services using comparatives, superlatives and useful reasons.","how":"Good comparisons identify the feature: cost, speed, comfort, location or quality. Avoid saying something is 'better' without explaining why.","detail":"","rules":"","examples":["The metro is cheaper than a taxi.","The clinic is closer to my home.","This is the most convenient time for me.","I am writing to confirm our appointment.","Please find the revised schedule attached.","This café is quieter than that one.","The train is faster than the bus.","My office is closer to home.","This course is more useful for beginners.","This is the best route to the hospital."]},{"id":"070","title":"Past Continuous: What Was Happening?","level":"A2","module":9,"main":"The past continuous describes an action in progress at a particular past time: was/were + verb-ing.","how":"This form provides the background of a past story. A short completed action may interrupt it.","detail":"The past continuous describes activity in progress at a past moment. It often sets the background for a shorter event in the past simple.","rules":"Past continuous in progress\nUse was/were + -ing for an action in progress at a past moment. The -ing spelling rules are the same as in\nthe present continuous.\n\n EXAMPLE I was working at nine.\n\n EXAMPLE They were waiting when I arrived.","examples":["I was reading at eight last night.","They were working when I arrived.","What were you doing at noon?","I was travelling when you called.","They were working at six o'clock.","She was sleeping at midnight.","We were talking when he arrived.","I was writing an email.","They were waiting in the rain.","What were you doing at eight?"]},{"id":"071","title":"Past Continuous vs Past Simple: When and While","level":"A2","module":9,"main":"Use the past continuous for a longer background action and the past simple for an event that happened during it.","how":"'While' often introduces the background action, and 'when' often introduces the shorter event. Both words can appear in different structures.","detail":"Use the past simple for finished past events. In negatives and most questions, use did plus the base form, not the past form.","rules":"Long background and short event\nThe past continuous often describes the background, while the past simple names the shorter event that\nhappened. When and while can connect the clauses.\n\n EXAMPLE I was cooking when the phone rang.\n\n EXAMPLE While I was cooking, the phone rang.","examples":["I was cooking when the phone rang.","While they were waiting, the train arrived.","It started raining while we were walking.","We visited the office yesterday.","Did you call the supplier?","I was driving when it started to rain.","While she was studying, the phone rang.","He called while we were eating.","They were leaving when the lights went out.","I met him while I was travelling."]},{"id":"072","title":"Used To: Past Habits and Situations","level":"A2","module":9,"main":"'Used to' + base verb describes a past habit or state that is no longer true, or is no longer the same now.","how":"After 'didn't' or 'did', use 'use to' in standard spelling: 'Did you use to ...?'","detail":"","rules":"Used to + base verb\nUsed to describes a past habit or state that is no longer true or no longer applies. The negative is often\ndidn’t use to.\n\n EXAMPLE I used to live here.\n\n EXAMPLE I didn’t use to drive.","examples":["I used to live near the station.","She used to work nights.","Did you use to play tennis?","I didn't use to like coffee.","He used to travel for work every month.","I used to work in a small shop.","She used to live near the river.","We didn't use to own a car.","Did you use to play football?","They used to meet every Friday."]},{"id":"073","title":"Present Perfect: Life Experiences","level":"A2","module":9,"main":"The present perfect connects a past experience to the present: have/has + past participle.","how":"For life experiences, we often use 'ever' in questions and 'never' in answers; do not add a finished past time such as 'yesterday' here.","detail":"The present perfect connects the past with the present. It can describe experience, change, and a period that is still relevant; the past simple often gives the finished time.","rules":"The present perfect structure\nUse have/has + past participle. It can refer to an experience in your life without saying a finished past time.\n\n EXAMPLE I have visited Rome.\n\n EXAMPLE She has never driven a car.","examples":["I've visited Singapore.","Has she ever tried skiing?","They've never worked abroad.","I have worked here for two years.","I joined the team in 2024.","I have travelled to Japan.","Have you ever tried Thai food?","She has never flown abroad.","We have visited that museum before.","He has seen this film twice."]},{"id":"074","title":"Present Perfect: For and Since","level":"A2","module":9,"main":"Use the present perfect with 'for' to give a period of time and 'since' to give a starting point.","how":"A situation can start in the past and continue now: 'I've lived here for three years'.","detail":"The present perfect connects the past with the present. It can describe experience, change, and a period that is still relevant; the past simple often gives the finished time.","rules":"For tells duration; since tells a starting point\nFor gives a period of time; since marks when it began. Choose an appropriate tense depending on whether\nthe situation continues.\n\n EXAMPLE I have worked here for five years.\n\n EXAMPLE I have worked here since 2021.","examples":["I've worked here for five months.","She has lived here since 2022.","We've known each other for years.","I have worked here for two years.","I joined the team in 2024.","I've lived here for three years.","She has worked here since March.","We haven't met for months.","How long have you known him?","He has studied English since January."]},{"id":"075","title":"Present Perfect vs Past Simple: First Contrast","level":"A2","module":9,"main":"Use the past simple for finished actions at a known past time. Use the present perfect when the past connects to the present and no finished time is specified.","how":"Compare 'I saw that film yesterday' with 'I've seen that film'. Both can be correct in different contexts.","detail":"Use the past simple for finished past events. In negatives and most questions, use did plus the base form, not the past form.","rules":"Past simple vs present perfect: essential contrast\nUse the past simple when a finished past time is stated or understood. Use the present perfect when a past\nevent has a connection with now or refers to time up to now.\n\n EXAMPLE I went there yesterday.\n EXAMPLE I have been there before.\n\n EXAMPLE She has lived here for years.","examples":["I sent the email this morning.","I've sent the email, so you can read it now.","Did you go to the conference last year?","We visited the office yesterday.","Did you call the supplier?","I visited Paris in 2022.","I've visited Paris twice.","She finished the report yesterday.","She has finished the report, so we can send it.","Did you see him last week?"]},{"id":"076","title":"Just, Already and Yet","level":"A2","module":9,"main":"'Just' suggests a very recent action; 'already' says something happened earlier than expected; 'yet' often appears in questions and negatives.","how":"These words often occur with the present perfect. Their position in the sentence matters.","detail":"","rules":"Just, already and yet\nAlready and just often appear between have/has and the past participle. Yet often appears at the end of\nquestions and negatives.\n\n EXAMPLE I have just arrived.\n EXAMPLE She has already left.\n\n EXAMPLE Have you finished yet?","examples":["I've just finished the report.","She's already left.","Have you eaten yet?","She hasn't replied yet.","We've already reserved a table.","I've just spoken to her.","We have already eaten lunch.","Has the taxi arrived yet?","They haven't finished yet.","She has just booked the tickets."]},{"id":"077","title":"Been and Gone: Trips and Travel","level":"A2","module":9,"main":"In the present perfect, 'been to' often means visited and returned; 'gone to' often means left and not yet returned.","how":"Context is important: 'She has gone to Paris' suggests she is there or travelling there now.","detail":"","rules":"Been vs gone\nHas been to often means the person visited and returned. Has gone to normally means the person is there\nor on the way, not yet back.\n\n EXAMPLE Mia has been to London. (she returned)\n\n EXAMPLE Mia has gone to London. (she is away)","examples":["I've been to Glasgow twice.","He's gone to the bank; he'll be back soon.","Have you ever been to Wales?","They have been to Japan before.","He's gone to the airport to collect a friend.","She has gone to the shop; she'll return soon.","I've been to Ireland twice.","He's gone to lunch.","Have you ever been to Madrid?","They have gone home for the evening."]},{"id":"078","title":"Practice: Tell a Short Personal Story","level":"A2","module":9,"main":"A clear personal story includes a time, a place, the important event and an ending.","how":"Choose past simple for the main actions and past continuous for useful background details. Add one feeling or lesson.","detail":"","rules":"","examples":["Last year I travelled to Turkey.","I was checking in when my phone rang.","Finally, a staff member helped me.","Two years ago, I started a new job.","At first, I found the work difficult.","Last year, I moved to a new city.","I was nervous on my first day at work.","I had never travelled alone before.","Since then, I've made many friends.","Now I feel comfortable here."]},{"id":"079","title":"Must and Must Not: Strong Rules","level":"A2","module":10,"main":"'Must' expresses a strong rule or obligation. 'Must not' means something is forbidden.","how":"For rules, 'must' and 'have to' can overlap. 'Mustn't' does not mean the same thing as 'don't have to'.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Must not is prohibition\nMustn’t means something is forbidden; do not confuse it with don’t have to, meaning something is not\nnecessary.\n\n EXAMPLE You mustn’t smoke here.\n\n EXAMPLE You don’t have to come early.","examples":["You must wear your ID badge.","Visitors must not park here.","You must follow the safety instructions.","You should check the address.","She might arrive late.","You must wear a seat belt.","You mustn't smoke in the building.","Visitors must show identification.","You must not share your password.","Staff must follow safety instructions."]},{"id":"080","title":"Have To and Do Not Have To: Necessity","level":"A2","module":10,"main":"'Have to' describes necessity; 'don't have to' means an action is not necessary.","how":"Questions use 'do/does': 'Do you have to ...?' Past necessity often uses 'had to'.","detail":"","rules":"Need vs no need\nHave to expresses necessity; do not have to expresses no obligation. Must not has a different meaning: a\nprohibition.\n\n EXAMPLE You have to show ID.\n\n EXAMPLE You don’t have to wear a uniform.","examples":["I have to leave at six.","She doesn't have to work tomorrow.","Do we have to book in advance?","He has to wear a uniform at work.","We don't have to attend the optional session.","I have to arrive before eight.","She does not have to attend tomorrow.","Do you have to wear a uniform?","He has to renew his licence.","You don't have to print the form."]},{"id":"081","title":"Should and Should Not: Giving Advice","level":"A2","module":10,"main":"'Should' and 'shouldn't' give advice or say what is a good idea. The main verb stays in its base form.","how":"Advice is not always a rule. A polite, helpful tone matters when giving advice.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Should + base verb\nAfter should, use the base form and do not add to or -s.\n\n EXAMPLE She should rest. (not should rests)\n\n EXAMPLE Should I call?","examples":["You should check the date.","You shouldn't share that password.","Should I call the office first?","You should check the address.","She might arrive late.","You should drink more water.","He shouldn't miss his appointment.","We should leave early.","Should I call the doctor?","They should check the timetable."]},{"id":"082","title":"May and Might: Possibility","level":"A2","module":10,"main":"'May' and 'might' express possibility when we are not sure. In many everyday statements they have similar meanings.","how":"Do not add 'to' after may or might. Avoid treating a possibility as a fact.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Might, may and could\nMay, might and could describe possibility, depending on context. They are followed by a base verb.\n\n EXAMPLE It might rain.\n EXAMPLE She may come later.\n\n EXAMPLE That could be a mistake.","examples":["It might rain later.","The manager may be in a meeting.","We might visit next month.","You should check the address.","She might arrive late.","It may rain this evening.","She might be at home.","The train may be delayed.","He might know the answer.","We may need more time."]},{"id":"083","title":"Could: Past Ability and Polite Requests","level":"A2","module":10,"main":"'Could' can describe a general ability in the past and can make polite requests in the present.","how":"For a single successful past event, 'managed to' or 'was able to' may be clearer than 'could'.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"","examples":["I could swim when I was eight.","Could you open the window, please?","We managed to solve the problem yesterday.","You should check the address.","She might arrive late.","I could read when I was five.","Could you help me with this box?","She couldn't attend last year.","Could I leave a little early?","We could visit the museum tomorrow."]},{"id":"084","title":"Present Continuous for Future Arrangements","level":"A2","module":10,"main":"The present continuous can describe a future arrangement that has already been organised.","how":"A future time phrase helps make the meaning clear. Compare an arrangement with a general intention.","detail":"Use am, is or are plus an -ing form for actions in progress, temporary situations or certain future arrangements. Some state verbs are not normally used this way.","rules":"Present continuous arrangements\nUse present continuous for a planned arrangement, often with a future time expression.\n\n EXAMPLE We are meeting the client tomorrow.\n\n EXAMPLE She is flying on Tuesday.","examples":["I'm meeting a client tomorrow.","She's flying to Rome on Friday.","Are you working next weekend?","I am reading an email now.","We are meeting the client tomorrow.","I'm meeting a friend tomorrow.","He is seeing his manager on Thursday.","We're having dinner at seven.","Are you seeing the dentist next week?","They aren't travelling this weekend."]},{"id":"085","title":"Present Simple for Timetables and Schedules","level":"A2","module":10,"main":"Use the present simple for official timetables, programmes and scheduled events, even when they refer to the future.","how":"This pattern is common with transport, opening times and organised events.","detail":"Use the present simple for routines, habits, general facts and many timetables. Questions and negatives usually need do or does; be is different.","rules":"Present simple for schedules\nTimetables and fixed schedules may use the present simple to refer to future times.\n\n EXAMPLE The train leaves at 7:15 tomorrow.\n\n EXAMPLE The class starts on Monday.","examples":["The train leaves at 6.20 tomorrow.","The museum opens at ten.","What time does the conference begin?","I start work at eight.","Does she work on Fridays?","The bus leaves at 6:15.","Our flight departs at six.","The meeting begins on Monday.","The train arrives at noon.","The course ends in December."]},{"id":"086","title":"First Conditional: Real Future Possibilities","level":"A2","module":10,"main":"The first conditional describes a real future possibility: if + present simple, will + base verb.","how":"The 'if' clause can come first or second. Do not normally use 'will' directly after 'if' in this basic pattern.","detail":"English uses more than one structure to refer to the future. Use the form that best matches your meaning: an intention, a prior arrangement, a timetable or a prediction.","rules":"First conditional pattern\nUse if + present simple for a real possible future condition; use will + base verb in the main clause when\nappropriate.\n\n EXAMPLE If it rains, we will stay inside.\n\n EXAMPLE We will call you if the parcel arrives.","examples":["If it rains, we'll take a taxi.","I'll call you if I'm late.","If you study, you'll improve.","I am going to apply for the job.","The conference begins on Monday.","If it rains, we'll stay inside.","I will send the document if I finish early.","If she studies regularly, she will progress.","She'll miss the train if she leaves late.","If the price falls, we'll buy it."]},{"id":"087","title":"Practice: Appointments and Workplace Advice","level":"A2","module":10,"main":"When making appointments and giving workplace advice, choose language that is clear, polite and specific.","how":"Use 'should' for suggestions and 'have to' for requirements. Confirm dates and times to avoid mistakes.","detail":"","rules":"","examples":["You should arrive ten minutes early.","Do I have to bring my passport?","I'm meeting the manager on Thursday.","You have to bring your identification.","You should confirm the date by email.","Should we leave now?","Could you confirm my appointment?","I have to finish this by Friday.","If you're free, we can meet tomorrow.","You mustn't share patient details."]},{"id":"088","title":"Zero Conditional: Facts and Regular Results","level":"A2","module":11,"main":"The zero conditional describes general facts and regular results: if + present simple, present simple.","how":"Use it for things that normally happen, not just one possible future event.","detail":"Conditional structures connect a situation and its result. The tense pattern helps show whether something is generally true, possible, imaginary or contrary to past fact.","rules":"Zero conditional pattern\nUse present tense in both clauses for general truths, routines or regularly observed results. Do not confuse\ngeneral facts with a specific future prediction.\n\n EXAMPLE If you heat ice, it melts.\n\n EXAMPLE If I miss the bus, I walk.","examples":["If you heat ice, it melts.","If I'm tired, I go to bed early.","When people practise, they often improve.","If it rains, we will stay inside.","If I had more time, I would practise.","If people exercise regularly, they often feel healthier.","When I drink coffee late, I sleep badly.","If the light is red, drivers stop.","Plants grow if they get enough water.","If you mix red and blue, you get purple."]},{"id":"089","title":"Verb Patterns: ‐ing and To + Verb, Basics","level":"A2","module":11,"main":"Some verbs are followed by -ing, and others by 'to' + base verb. Learn common patterns together with each verb.","how":"Examples: 'enjoy working', 'want to work', 'decide to leave'. Some verbs allow both patterns.","detail":"After a main verb, another verb may take -ing, to + infinitive or a bare infinitive. The choice depends on the first word and sometimes changes meaning.","rules":"Common verbs + -ing\nEnjoy, avoid, finish, consider, suggest and practise are usually followed by an -ing form.\n\n EXAMPLE enjoy reading\n\n EXAMPLE avoid driving\n EXAMPLE finish writing\n\n EXAMPLE suggest leaving\n\nCommon verbs + to-infinitive\nWant, decide, hope, plan, manage and promise are usually followed by to + base verb.\n\n EXAMPLE want to learn\n\n EXAMPLE decide to go\n\n EXAMPLE hope to visit\n\n EXAMPLE promise to help\n\nAfter a preposition, use -ing\nA verb following a preposition normally takes -ing; to can itself be a preposition in expressions such as look\nforward to.\n\n EXAMPLE good at speaking\n\n EXAMPLE interested in learning\n\n EXAMPLE look forward to meeting","examples":["I enjoy reading on the train.","She wants to change jobs.","They decided to wait.","I enjoy learning new words.","I decided to study tonight.","I enjoy reading before bed.","She wants to learn Spanish.","We decided to leave early.","He avoids driving at night.","They hope to travel next year."]},{"id":"090","title":"Relative Clauses: Who, Which and That","level":"A2","module":11,"main":"A defining relative clause identifies which person or thing you mean. 'Who' refers to people; 'which' and 'that' commonly refer to things.","how":"In a defining clause, the information is needed to identify the noun. No commas are used around it.","detail":"A relative clause identifies or adds information about a noun. Some clauses are necessary to identify the noun, while others add extra detail and are separated by commas.","rules":"Defining relative clauses\nWho is used for people, which for things, and that for people or things in many defining clauses. The\nrelative word can sometimes be omitted when it is the object, not the subject.\n\n EXAMPLE The woman who called is here.\n\n EXAMPLE The book (that) I bought is useful.","examples":["The man who called is my boss.","This is the phone that I bought.","A café which opens early is useful.","The colleague who called is here.","My office, which is small, is quiet.","A colleague who speaks Spanish can help.","The woman who helped us is my neighbour.","The train which leaves at six is usually busy.","The woman who called is my manager.","I found the book that you recommended."]},{"id":"091","title":"Because, So, But and Although","level":"A2","module":11,"main":"Link ideas with 'because' for a reason, 'so' for a result, 'but' for contrast and 'although' for unexpected contrast.","how":"Don't normally write 'although ... but ...' together in the same simple clause pattern.","detail":"Linking words tell readers how ideas relate: addition, contrast, reason, result or concession. Choose a connector that matches the relationship and punctuate it correctly.","rules":"Although vs but\nAlthough introduces a dependent clause showing contrast. Do not normally use both although and but to\nlink the same pair of clauses.\n\n EXAMPLE Although it rained, we went out.\n\n EXAMPLE It rained, but we went out.","examples":["I stayed home because I was ill.","It was late, so we left.","Although it was busy, the staff were helpful.","The journey was long, but the meeting was useful.","The data were incomplete; therefore, we checked again.","She left early because she was tired.","It was late, so we took a taxi.","The shop was open, but the café was closed.","Although he was tired, he continued.","We waited because the bus was delayed."]},{"id":"092","title":"Reflexive Pronouns: Myself to Themselves","level":"A2","module":11,"main":"Reflexive pronouns end in -self or -selves: myself, yourself, himself, herself, itself, ourselves, yourselves, themselves.","how":"Use them when the subject and object refer to the same person or group. Also use 'by myself' to mean alone.","detail":"","rules":"Reflexive pronouns match the subject\nUse myself, yourself, himself, herself, itself, ourselves, yourselves or themselves when the action returns to\nthe subject or for emphasis.\n\n EXAMPLE She introduced herself.\n\n EXAMPLE We prepared it ourselves.","examples":["I taught myself to cook.","She prepared the report herself.","We enjoyed ourselves.","He repaired the bicycle himself.","Please help yourselves to some tea.","I cut myself while cooking.","She taught herself to drive.","We prepared the meal ourselves.","He looked at himself in the mirror.","They enjoyed themselves at the party."]},{"id":"093","title":"Someone, Anyone, Nothing and Everything","level":"A2","module":11,"main":"Someone, anyone, no one and everyone refer to people; something, anything, nothing and everything refer to things.","how":"Use 'anyone' in many questions and negatives, but forms change with meaning and context.","detail":"","rules":"Some-/any-/no-/every- words\nSomeone, anyone, no one and everyone act as singular words for verb agreement, even when they refer to\nmany people.\n\n EXAMPLE Everyone is ready.\n\n EXAMPLE Nobody knows.","examples":["Someone is waiting outside.","I don't know anyone here.","Everything is ready.","I haven't heard anything today.","Everybody understood the instructions.","Nobody answered the phone.","Did anyone call me?","Nothing is wrong.","Everything looks ready.","I don't know anybody here."]},{"id":"094","title":"Present Simple Passive: What Is Made Where?","level":"A2","module":11,"main":"Use the present simple passive when the action or result matters more than the person doing it: am/is/are + past participle.","how":"The active sentence focuses on the doer. The passive focuses on the receiver of the action.","detail":"Use the present simple for routines, habits, general facts and many timetables. Questions and negatives usually need do or does; be is different.","rules":"Passive formula\nThe passive uses be + past participle. In the present simple passive, use am/is/are + past participle.\n\n EXAMPLE Tea is grown here.\n\n EXAMPLE These forms are checked daily.","examples":["The invoices are checked daily.","Coffee is grown in many countries.","The office is cleaned every evening.","I start work at eight.","Does she work on Fridays?","The rooms are cleaned daily.","Our products are sold in several countries.","English is spoken around the world.","The forms are checked at reception.","These shoes are made in Italy."]},{"id":"095","title":"Writing: Short Emails, Messages and Punctuation","level":"A2","module":11,"main":"A short professional message needs a clear purpose, key details and a polite closing. Use full stops, capital letters and simple paragraphs.","how":"An email subject should tell the reader what to expect. Keep requests specific and dates easy to find.","detail":"","rules":"A complete short email\nAn email usually needs a clear subject line, suitable greeting, main message and closing. Use capitals and full\nstops, not one long sentence.\n\n EXAMPLE Subject: Meeting time\n\n EXAMPLE Dear Ms Khan, ... Kind regards, ...","examples":["Subject: Meeting on Thursday","Could we move the meeting to 10 a.m.?","Thank you for your help. Kind regards, Sara.","I am writing to confirm our appointment.","Please find the revised schedule attached.","Dear Mr Khan, thank you for your message.","Could you confirm the meeting time?","I have attached the document.","Please let me know if you need anything else.","Kind regards, Sara."]},{"id":"096","title":"A2 Review and Level Check: Daily Life Tasks","level":"A2","module":11,"main":"This level check combines comparison, past and present experiences, modal verbs, conditional sentences and short messages.","how":"Read each question carefully, then explain your choice. Being able to use a form matters more than remembering its name.","detail":"","rules":"","examples":["I've worked here since January.","If it rains, we'll stay inside.","You should check the timetable.","I have never visited that city.","She will phone if the bus is delayed.","I have worked here for a year.","If it rains, I'll take the bus.","Please let me know when you arrive.","The tickets have already been booked.","This is the colleague who helped me."]},{"id":"097","title":"Present Perfect Simple vs Present Perfect Continuous","level":"B1","module":12,"main":"Use the present perfect simple to focus on a finished result or number; use the present perfect continuous to focus on an activity or its duration.","how":"Some state verbs, such as 'know', normally prefer the simple form. Both forms can be possible with different meanings.","detail":"The present perfect connects the past with the present. It can describe experience, change, and a period that is still relevant; the past simple often gives the finished time.","rules":"Present perfect simple vs continuous\nThe simple form often emphasises a result or completed amount; the continuous often emphasises\nduration or ongoing activity. Some state verbs commonly prefer the simple form.\n\n EXAMPLE I have written three emails.\n EXAMPLE I have been writing emails all morning.\n\n EXAMPLE I have known her for years.","examples":["I've written three emails today.","I've been writing emails all morning.","She's known him for years.","I have worked here for two years.","I joined the team in 2024.","He has made five calls today.","He has been making calls all morning.","She has lived here for years.","She has been working since nine.","Have you been waiting long?"]},{"id":"098","title":"For, Since, Recently and Lately: Time Expressions","level":"B1","module":12,"main":"'For' gives duration; 'since' gives a starting point. 'Recently' and 'lately' refer to a period near the present.","how":"With an ongoing activity, both present perfect forms may occur, depending on the verb and emphasis.","detail":"","rules":"Since cannot replace for\nSince introduces a starting point; for introduces a length of time. Recently and lately refer to a period near\nnow.\n\n EXAMPLE since Monday\n\n EXAMPLE since 2020\n EXAMPLE for three days\n\n EXAMPLE for five months","examples":["I've lived here for six years.","She's been busy lately.","We haven't spoken recently.","I haven't spoken to them lately.","We've been preparing since Monday.","We've lived here since 2021.","He's been busy recently.","I haven't seen her lately.","They've worked together for years.","She has studied English for six months."]},{"id":"099","title":"Past Perfect Simple: Earlier Past Events","level":"B1","module":12,"main":"The past perfect shows that one past action happened before another past time or action: had + past participle.","how":"We often combine it with the past simple to make the order of events clear. Do not use it for every action in a simple story.","detail":"The past perfect shows that something was already complete before another past point. Use it when the order would otherwise be unclear.","rules":"Past perfect = had + past participle\nUse past perfect to show an earlier event before another past event when the order needs clarification.\n\n EXAMPLE The meeting had started when I arrived.","examples":["The train had left when we arrived.","She had finished the report before lunch.","I realised I had forgotten my keys.","The train had left before we arrived.","She had completed the report by noon.","The meeting had started when I arrived.","She had left before I called.","We hadn't eaten when the guests came.","Had you seen the report before Monday?","He realised that he'd lost his wallet."]},{"id":"100","title":"Past Simple, Continuous and Perfect Together","level":"B1","module":12,"main":"Past simple moves a story forward; past continuous shows background activity; past perfect moves further back to an earlier event.","how":"Choose based on the time relationship, not only on signal words. A story can contain all three forms.","detail":"Use the past simple for finished past events. In negatives and most questions, use did plus the base form, not the past form.","rules":"Past timeline in one story\nUse past continuous for background, past simple for completed main events, and past perfect when one\npast event happened before another.\n\n EXAMPLE I was walking home when I realised I had lost my keys.","examples":["I arrived while they were talking.","The meeting had started before I arrived.","The phone rang as I was leaving.","We visited the office yesterday.","Did you call the supplier?","I was driving when my phone rang.","She had already left when we arrived.","We were discussing the plan when the manager entered.","He called after he had finished work.","It started raining while they were walking."]},{"id":"101","title":"Future Continuous: Events in Progress","level":"B1","module":12,"main":"Future continuous describes an action that will be in progress at a future time: will be + verb-ing.","how":"It can also be a polite way to ask about someone's plans without sounding too direct.","detail":"English uses more than one structure to refer to the future. Use the form that best matches your meaning: an intention, a prior arrangement, a timetable or a prediction.","rules":"Future continuous form\nUse will be + verb-ing for something expected to be in progress at a future time.\n\n EXAMPLE At eight tomorrow, I will be travelling.","examples":["At eight, I'll be travelling home.","She'll be working tomorrow afternoon.","Will you be using the meeting room later?","I am going to apply for the job.","The conference begins on Monday.","This time tomorrow, I'll be flying to Rome.","At eight, she'll be studying.","We'll be waiting at the station.","Will you be working on Saturday?","They won't be using the office next week."]},{"id":"102","title":"Choosing Future Forms: Will, Going To and Arrangements","level":"B1","module":12,"main":"Choose 'will' for spontaneous decisions and some predictions, 'going to' for intentions and evidence-based predictions, and present continuous for arrangements.","how":"There is overlap. Decide what you want the listener to understand about planning and certainty.","detail":"English uses more than one structure to refer to the future. Use the form that best matches your meaning: an intention, a prior arrangement, a timetable or a prediction.","rules":"Three useful future choices\nWill often marks a decision now or prediction; going to often marks an earlier intention or evidence-based\nprediction; present continuous often marks a confirmed arrangement.\n\n EXAMPLE I’ll answer the phone.\n EXAMPLE I’m going to apply.\n\n EXAMPLE I’m meeting the manager tomorrow.","examples":["I'll answer the phone.","I'm going to take a course next year.","I'm meeting my tutor tomorrow.","I am going to apply for the job.","The conference begins on Monday.","Look at those clouds; it's going to rain.","She is travelling to Paris next week.","I'm meeting my manager tomorrow.","Our flight leaves at six.","I think the new system will help."]},{"id":"103","title":"State and Action Verbs: Know, Think and Have","level":"B1","module":12,"main":"A state verb describes knowledge, feelings, possession or a condition; an action verb describes activity. Some verbs change meaning depending on their use.","how":"'I think it's useful' expresses an opinion; 'I'm thinking about it' describes a mental activity. Not every continuous use is wrong.","detail":"","rules":"A verb can be state or action depending on meaning\nHave can mean possession (usually simple) or an activity (continuous is possible). Think can express opinion\nor an active mental process.\n\n EXAMPLE I have a car. / I’m having lunch.\n\n EXAMPLE I think it’s good. / I’m thinking about it.","examples":["I know the answer.","I'm thinking about a new job.","She has two brothers.","He feels tired this evening.","She is thinking about her new job.","I own a small car.","I'm thinking about the problem.","This soup tastes delicious.","We're having dinner.","He believes the figures are correct."]},{"id":"104","title":"Practice: Explain Experiences and Future Plans","level":"B1","module":12,"main":"To explain work experience, link completed past events to your present skills. To explain future plans, choose the form that matches your intention or arrangement.","how":"Give one clear example, then add a short reason or result. Practise speaking for thirty seconds without reading.","detail":"English uses more than one structure to refer to the future. Use the form that best matches your meaning: an intention, a prior arrangement, a timetable or a prediction.","rules":"","examples":["I've worked in customer service for three years.","I managed a project last summer.","I'm going to improve my presentation skills.","I am going to apply for the job.","The conference begins on Monday.","I've worked here since January.","Last year, I travelled abroad.","I'm going to take a language test.","I might apply for a new role.","By next month, I'll have completed my training."]},{"id":"105","title":"Must and Cannot: Deductions About the Present","level":"B1","module":13,"main":"Use 'must' to make a strong deduction from evidence and 'can't' or 'cannot' to say something seems impossible.","how":"This 'must' means 'I am nearly certain', not 'someone is required'.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Deduction is not an obligation\nMust for deduction means the speaker thinks something is almost certain. Can’t for deduction means the\nspeaker thinks it is impossible.\n\n EXAMPLE His lights are on; he must be home.\n\n EXAMPLE She is in Paris; she can’t be here.","examples":["The lights are on; someone must be home.","That can't be the right address; the number is different.","She must be very busy today.","He must be at the office; his car is outside.","This cannot be our train; it has a different number.","That must be the delivery driver at the door.","That can't be the correct address.","She must be very tired.","This cannot be the only solution.","He must know about the meeting."]},{"id":"106","title":"May, Might and Could: Degrees of Possibility","level":"B1","module":13,"main":"'May', 'might' and 'could' can show uncertain possibility. The context, not the modal alone, often carries the level of confidence.","how":"For a negative possibility, 'may not' or 'might not' can mean perhaps not; 'couldn't' may mean impossible in a particular context.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Degrees of possibility\nMay, might and could all express possibility. The precise confidence depends on context, not a fixed\nnumerical ranking.\n\n EXAMPLE It may be delayed.\n EXAMPLE It might be delayed.\n\n EXAMPLE It could be delayed.","examples":["The delivery may arrive today.","He might be in a meeting.","There could be a delay.","You should check the address.","She might arrive late.","She may join us later.","It might take longer than expected.","The train could be delayed.","Perhaps he is at work.","The figures may change next month."]},{"id":"107","title":"Should, Ought To and Had Better","level":"B1","module":13,"main":"'Should' and 'ought to' give advice or expectation. 'Had better' gives stronger advice, sometimes with an implied consequence.","how":"After 'had better', use the base verb without 'to'. 'Ought to' includes 'to'.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Had better often implies a warning\nHad better + base verb suggests advice where there could be a negative result if the advice is ignored.\n\n EXAMPLE You’d better leave now; the road may close.","examples":["You should keep a copy.","We ought to leave early.","You'd better check the deadline.","You should check the address.","She might arrive late.","You ought to speak to your manager.","We'd better leave now.","She should check the address.","You shouldn't skip breakfast.","He had better keep a copy."]},{"id":"108","title":"Need Not, Do Not Have To and Must Not","level":"B1","module":13,"main":"'Mustn't' means prohibited; 'don't have to' means optional; 'needn't' often means there is no necessity.","how":"These differences matter in workplace policies and daily decisions. Compare a safety rule with a choice.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Mustn’t and don’t have to are different\nMustn’t prohibits an action; don’t have to means the action is optional.\n\n EXAMPLE You mustn’t enter.\n\n EXAMPLE You don’t have to attend.","examples":["You mustn't enter this area.","You don't have to wear a tie.","You needn't bring lunch; food is provided.","You should check the address.","She might arrive late.","You needn't bring your laptop.","We don't have to pay today.","You mustn't park here.","She doesn't need to attend.","Guests must not enter this area."]},{"id":"109","title":"Second Conditional: Imaginary Situations","level":"B1","module":13,"main":"The second conditional imagines an unreal, unlikely or hypothetical present/future situation: if + past form, would + base verb.","how":"With 'be', 'were' is often used in formal or hypothetical 'if I were' expressions. The past form does not necessarily refer to past time.","detail":"Conditional structures connect a situation and its result. The tense pattern helps show whether something is generally true, possible, imaginary or contrary to past fact.","rules":"Second conditional form\nUse if + past simple and would + base verb to discuss unreal, unlikely or imagined present/future situations.\nIn formal contexts, If I were ... is common.\n\n EXAMPLE If I had more time, I would travel.\n\n EXAMPLE If I were you, I would check.","examples":["If I had more time, I'd learn Italian.","If I were you, I'd ask first.","She'd travel more if she earned more.","If it rains, we will stay inside.","If I had more time, I would practise.","If I had more time, I'd study French.","She would travel more if she earned more.","If I were you, I'd ask for help.","We'd buy a house if we could afford it.","What would you do if you won a prize?"]},{"id":"110","title":"Wish + Past Simple: Present Wishes","level":"B1","module":13,"main":"Use 'wish' + past form to describe a present situation you want to be different.","how":"'I wish I knew' means 'I do not know now'. For ability, 'I wish I could ...' is common.","detail":"Use the past simple for finished past events. In negatives and most questions, use did plus the base form, not the past form.","rules":"Wish + past form refers to present regret\nWish is followed by a past form for a present situation we want to be different. The grammatical past form\ndoes not necessarily mean past time.\n\n EXAMPLE I wish I knew the answer.\n\n EXAMPLE I wish I had more time.","examples":["I wish I had more free time.","She wishes she spoke French.","I wish I could drive.","We visited the office yesterday.","Did you call the supplier?","I wish I knew the answer.","She wishes she had a car.","I wish I spoke better English.","He wishes his office were closer.","We wish we had more time."]},{"id":"111","title":"Unless, As Long As and Provided That: Basic Conditions","level":"B1","module":13,"main":"'Unless' means 'if not'. 'As long as' and 'provided that' introduce conditions that must be met.","how":"Avoid unnecessary double negatives: 'Unless it rains, we'll go' means 'If it doesn't rain, we'll go'.","detail":"Conditional structures connect a situation and its result. The tense pattern helps show whether something is generally true, possible, imaginary or contrary to past fact.","rules":"Unless means if not\nUnless introduces an exception or negative condition. Avoid an unnecessary extra negative when unless\nalready means if not.\n\n EXAMPLE Unless you call, I will leave. = If you do not call, I will leave.","examples":["We'll go unless it rains.","You can use the room as long as you book it.","We'll approve it provided that the details are correct.","If it rains, we will stay inside.","If I had more time, I would practise.","Unless you hurry, you'll miss the train.","You can leave as long as you finish.","Provided that the weather is good, we'll go.","I'll help unless I'm working.","You may enter if you have a ticket."]},{"id":"112","title":"Practice: Solve a Problem and Give Advice","level":"B1","module":13,"main":"Problem-solving language combines clear facts, suitable modal verbs and practical suggestions.","how":"Describe the issue first, suggest an action and explain the expected benefit. Listen before you disagree.","detail":"","rules":"","examples":["We might need more time.","You should speak to the supervisor.","If we start now, we'll finish earlier.","If you are uncertain, ask the receptionist.","We might try a different solution.","If I were you, I'd call customer service.","You should keep a record of the problem.","Perhaps the system is temporarily unavailable.","We'd better ask for another appointment.","What would happen if we tried a different method?"]},{"id":"113","title":"Defining Relative Clauses: More Detail","level":"B1","module":14,"main":"A defining relative clause adds necessary information to a noun. The relative pronoun can sometimes be omitted when it is the object.","how":"Do not omit the pronoun when it is the subject: 'The person who called', not 'The person called' with the same meaning.","detail":"A relative clause identifies or adds information about a noun. Some clauses are necessary to identify the noun, while others add extra detail and are separated by commas.","rules":"Defining relative clauses and commas\nA defining clause identifies exactly which person or thing we mean. Do not normally put commas around it.\n\n EXAMPLE The man who works here is helpful.","examples":["The woman who called is from finance.","The report that I sent is final.","The colleague I met was helpful.","The colleague who called is here.","My office, which is small, is quiet.","The man who called is my neighbour.","This is the email that you sent.","The café where we met has closed.","The laptop which I ordered has arrived.","I need a colleague who can translate."]},{"id":"114","title":"Non‐Defining Relative Clauses: Introduction","level":"B1","module":14,"main":"A non-defining relative clause adds extra information, not information needed to identify the noun. Use commas in writing.","how":"Use 'who' for people and 'which' for things; 'that' is not normally used in non-defining relative clauses.","detail":"A relative clause identifies or adds information about a noun. Some clauses are necessary to identify the noun, while others add extra detail and are separated by commas.","rules":"Non-defining relative clauses add extra detail\nPut commas around extra information that is not needed to identify the noun. That is not normally used in\nnon-defining clauses.\n\n EXAMPLE My brother, who lives in Bristol, is visiting.\n\n EXAMPLE London, which is the capital of the UK, is busy.","examples":["My manager, who lives nearby, cycles to work.","The building, which opened in 2010, is modern.","Sara, whose sister is a doctor, called.","The colleague who called is here.","My office, which is small, is quiet.","My brother, who lives in Leeds, is visiting.","The report, which was published yesterday, is online.","Mariam, whose office is upstairs, will join us.","Paris, where I studied, is very busy.","The meeting, which lasted an hour, ended early."]},{"id":"115","title":"Reported Speech: Statements","level":"B1","module":14,"main":"Reported speech tells someone what another person said. We often shift tense back when reporting from a later viewpoint.","how":"Pronouns and time words may also change. When the information is still true, backshift is sometimes optional.","detail":"Reported language tells another person what someone said or asked. Pronouns, time words and verb tenses may change depending on the time and viewpoint of the report.","rules":"Reported statements: backshift may be used\nWhen reporting with a past reporting verb, tense may move back: am -> was, will -> would, can -> could.\nBackshift is not automatic if the fact is still true or the context allows the original tense.\n\n EXAMPLE She said, “I am tired.” -> She said she was tired.","examples":["'I am tired' -> He said he was tired.","'I work here' -> She said she worked there.","They said they would call.","She said that she was ready.","He asked whether the meeting had started.","She said that she was tired.","He told me he would call.","They said they had finished.","Mariam explained that the shop was closed.","She said she couldn't attend."]},{"id":"116","title":"Reported Speech: Questions","level":"B1","module":14,"main":"Reported questions use statement word order, not direct-question word order. Yes/no questions often use 'if' or 'whether'.","how":"Use 'asked' or a similar reporting verb. Remove the question mark when the reported question is part of a statement.","detail":"Reported language tells another person what someone said or asked. Pronouns, time words and verb tenses may change depending on the time and viewpoint of the report.","rules":"Reported questions use statement word order\nIn a reported question, normally remove question word order and do not use a question mark if the whole\nsentence is a statement.\n\n EXAMPLE “Where are you?” -> He asked where I was.\n\n EXAMPLE “Do you work?” -> He asked if I worked.","examples":["'Where are you?' -> He asked where I was.","'Do you work here?' -> She asked if I worked there.","He asked when the meeting started.","She said that she was ready.","He asked whether the meeting had started.","He asked where I lived.","She wanted to know if I was free.","They asked when the meeting started.","He asked whether she had called.","My manager asked why I was late."]},{"id":"117","title":"Reported Commands and Requests","level":"B1","module":14,"main":"To report an instruction or request, use 'told/asked + object + to + verb'. A negative uses 'not to'.","how":"Choose 'asked' for a request and 'told' for an instruction when that distinction matters.","detail":"Reported language tells another person what someone said or asked. Pronouns, time words and verb tenses may change depending on the time and viewpoint of the report.","rules":"Reported commands and requests\nUse tell/ask + object + to-infinitive; negatives use not to.\n\n EXAMPLE “Please wait.” -> She asked me to wait.\n\n EXAMPLE “Don’t enter.” -> He told us not to enter.","examples":["'Wait here.' -> She told me to wait there.","'Please call me.' -> He asked me to call him.","'Don't open it.' -> She told me not to open it.","She said that she was ready.","He asked whether the meeting had started.","She asked me to wait outside.","He told us not to touch the switch.","The doctor advised me to rest.","They asked him to send the file.","The manager told us to arrive early."]},{"id":"118","title":"Passive Voice: Past and Future","level":"B1","module":14,"main":"Build passives with a form of 'be' + past participle. Change the tense of 'be' to show past or future time.","how":"Use passive when the result, action or receiver is more important than the doer.","detail":"English uses more than one structure to refer to the future. Use the form that best matches your meaning: an intention, a prior arrangement, a timetable or a prediction.","rules":"Passive across past and future\nChange the tense of be, not the past participle.\n\n EXAMPLE The room was cleaned.\n\n EXAMPLE The room will be cleaned.","examples":["The report was sent yesterday.","The new bridge will be opened next year.","The documents were checked carefully.","I am going to apply for the job.","The conference begins on Monday.","The letter was sent yesterday.","The documents were signed last week.","The new road will be opened in May.","Was the package delivered?","The results will be announced tomorrow."]},{"id":"119","title":"Passive Voice with Modal Verbs","level":"B1","module":14,"main":"A modal passive uses modal + be + past participle: 'must be completed', 'can be used'.","how":"The modal adds meaning such as ability, obligation or possibility. Keep the past participle after 'be'.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Passive after a modal\nUse modal + be + past participle. For perfect modal passives use modal + have been + past participle.\n\n EXAMPLE The form must be signed.\n\n EXAMPLE The email should have been sent.","examples":["This form must be signed.","The meeting can be postponed.","The issue should be reported.","You should check the address.","She might arrive late.","The form must be completed today.","The tickets can be booked online.","The rules should be followed.","The appointment may be changed.","The report could be sent tomorrow."]},{"id":"120","title":"Practice: Report News and Workplace Updates","level":"B1","module":14,"main":"When reporting workplace updates, choose active voice when the doer matters and passive voice when the result matters.","how":"Use reporting verbs accurately, confirm what you know, and separate facts from rumours.","detail":"In English, information such as dates, prices and phone numbers needs to be both clear and exact. Say numbers in groups and repeat important details when needed.","rules":"","examples":["The manager said the deadline had changed.","The documents were approved yesterday.","She asked whether the figures were correct.","The meeting starts at nine thirty.","The total is eighteen pounds fifty.","The meeting was cancelled yesterday.","The new timetable will be published soon.","She said the office was closed.","He asked whether I had received the email.","The problem must be reported immediately."]},{"id":"121","title":"Tricky Countable and Uncountable Nouns","level":"B1","module":15,"main":"Some nouns that are countable in one language are uncountable in English. Learn their usual patterns as complete phrases.","how":"Common examples include 'advice', 'equipment', 'furniture', 'information' and 'luggage'. Use 'a piece of' or a similar measure when needed.","detail":"","rules":"Common countability traps\nAdvice, homework, equipment and information are normally uncountable. News ends in -s but is\ngrammatically singular.\n\n EXAMPLE This advice is helpful.\n EXAMPLE The news is good.\n\n EXAMPLE I bought two pieces of equipment.","examples":["We need more equipment.","She gave me useful advice.","There are three pieces of luggage.","The company bought new equipment.","Three pieces of information are missing.","We need two pieces of advice.","There is too much furniture in the room.","Could I have a glass of water?","Several people applied for the role.","She bought three loaves of bread."]},{"id":"122","title":"Each, Every, All, Both, Either and Neither","level":"B1","module":15,"main":"'Each' focuses on individuals; 'every' refers to all members separately; 'all' refers to a complete group. 'Both' refers to two.","how":"'Either' means one of two; 'neither' means not one and not the other. Agreement depends on the grammatical structure.","detail":"","rules":"Each/every with singular nouns\nEach and every usually take a singular count noun and singular verb. Both refers to two; all can refer to\nthree or more or to an entire group.\n\n EXAMPLE Every student has a book.\n\n EXAMPLE Both students have books.","examples":["Each employee has a pass.","Both candidates were prepared.","Neither answer is correct.","Both trains stop in the city centre.","Every applicant must sign the form.","Each employee has a badge.","Every room has a window.","Both options are possible.","Neither proposal is affordable.","Either train will take you there."]},{"id":"123","title":"Articles: General and Specific Reference","level":"B1","module":15,"main":"Use articles to show whether you mean any member of a group, a specific item or a general idea.","how":"The first mention often uses 'a/an'; a later or uniquely identified mention often uses 'the'. General plural nouns often have no article.","detail":"Article choice depends on sound, number and whether the listener can identify the noun. Use a/an for one non-specific singular countable thing; the when the thing is known or identified.","rules":"Generic vs specific reference\nUse a/an for one non-specific example, the for an identifiable particular one, and no article for many\ngeneral plurals or uncountables.\n\n EXAMPLE A doctor called. The doctor left a message.\n\n EXAMPLE Doctors help patients.","examples":["I bought a laptop. The laptop was expensive.","The sun is shining.","Managers need clear instructions.","I need a pen. The pen is on the desk.","She is an engineer.","We need a manager for the new branch.","The manager I met yesterday was helpful.","I like music.","She plays the piano.","The sun was shining brightly."]},{"id":"124","title":"Verb + ‐ing vs To + Infinitive","level":"B1","module":15,"main":"The pattern after a verb can change meaning. Some verbs take -ing, some take to-infinitive, and some take both with different meanings.","how":"'Remember to call' means do not forget a future action; 'remember calling' means have a memory of that past action.","detail":"After a main verb, another verb may take -ing, to + infinitive or a bare infinitive. The choice depends on the first word and sometimes changes meaning.","rules":"Meaning changes with stop\nStop doing something means end an activity. Stop to do something means pause one activity for another\npurpose.\n\n EXAMPLE He stopped smoking.\n\n EXAMPLE He stopped to buy water.\n\nMeaning changes with remember\nRemember to do refers to remembering a future duty. Remember doing refers to a memory of a previous\naction.\n\n EXAMPLE Remember to call her.\n\n EXAMPLE I remember calling her.\n\nMeaning changes with try\nTry to do means make an effort. Try doing means test a possible method.\n\n EXAMPLE Try to open the door.\n\n EXAMPLE Try restarting the computer.","examples":["I stopped to buy coffee.","I stopped drinking coffee last year.","She remembered to lock the door.","I enjoy learning new words.","I decided to study tonight.","She stopped smoking last year.","He decided to change jobs.","I remember meeting her before.","Please remember to bring your ticket.","We hope to hear from you soon."]},{"id":"125","title":"Verb + Object + Infinitive","level":"B1","module":15,"main":"Some verbs take an object before an infinitive: ask someone to do something, want someone to do something, tell someone to do something.","how":"Other verbs can take a bare infinitive in certain structures, such as 'let someone go'. Learn the pattern with its verb.","detail":"After a main verb, another verb may take -ing, to + infinitive or a bare infinitive. The choice depends on the first word and sometimes changes meaning.","rules":"Some verbs need an object before to\nTell, ask, encourage, invite, remind and advise can take object + to-infinitive.\n\n EXAMPLE She told me to wait.\n\n EXAMPLE We invited them to join.","examples":["She asked me to wait.","We want you to join us.","The manager let us leave early.","I enjoy learning new words.","I decided to study tonight.","The manager asked us to wait.","She wants her son to study abroad.","I helped him carry the bags.","They allowed the visitors to enter.","He persuaded me to apply."]},{"id":"126","title":"Adjective + Preposition Combinations","level":"B1","module":15,"main":"Many adjectives naturally combine with particular prepositions. These combinations are best learned as phrases.","how":"For example: interested in, good at, worried about, responsible for, proud of. The preposition cannot always be guessed from meaning.","detail":"An adjective adds information to a noun. Many adjectives appear before nouns or after linking verbs such as be, seem and feel. Adjectives normally do not change for plural nouns.","rules":"Learn adjectives and their prepositions as pairs\nThe correct preposition often depends on the adjective. Do not translate a preposition directly from\nanother language.\n\n EXAMPLE interested in\n\n EXAMPLE good at\n\n EXAMPLE responsible for\n EXAMPLE afraid of\n\n EXAMPLE proud of","examples":["I'm interested in finance.","She's good at explaining problems.","He is responsible for recruitment.","It is a quiet office.","The offices are quiet.","I'm interested in the course.","She is responsible for the budget.","We are proud of our results.","He is good at solving problems.","They were worried about the delay."]},{"id":"127","title":"Phrasal Verbs: Get, Give, Take and Put","level":"B1","module":15,"main":"A phrasal verb combines a verb with a particle, and the meaning may differ from the original verb.","how":"Learn phrasal verbs with context and, when necessary, their object pattern. One phrasal verb can have several meanings.","detail":"Learn each phrasal verb as a complete expression. Some particles change the verb's meaning completely: get up means leave your bed, put off means postpone. Check whether the object can come between the verb and particle.","rules":"Phrasal verbs are not always literal\nA phrasal verb combines a verb with one or more particles; its meaning may not be predictable from the\nparts.\n\n EXAMPLE give up = stop trying\n EXAMPLE put off = postpone\n\n EXAMPLE look after = care for","examples":["Please turn off the light.","We need to find out the cause.","She gave up smoking.","Please put off the meeting until Tuesday.","I usually get up at six.","Please fill in the form.","We need to put off the meeting.","He gave up smoking.","She took off her coat.","Could you get back to me tomorrow?"]},{"id":"128","title":"Word Formation: Common Prefixes and Suffixes","level":"B1","module":15,"main":"Prefixes and suffixes help create related words. A prefix often changes meaning; a suffix may change word class.","how":"Examples include unhappy, reuse, helpful, carefully, decision and employment. Check spelling when you add an ending.","detail":"","rules":"Spelling when adding suffixes\nA suffix may change the word class. Consonant + y may change to i, and a final e may disappear before\ncertain suffixes. Always check spelling.\n\n EXAMPLE happy -> happiness\n EXAMPLE decide -> decision\n\n EXAMPLE care -> careful","examples":["Happy -> unhappy.","Employ -> employment.","Careful -> carefully.","Unfair is the opposite of fair.","Careless describes someone who does not take enough care.","Unhappy means not happy.","The new service is reusable.","Her explanation was helpful.","We need to reorganise the files.","He worked carefully and professionally."]},{"id":"129","title":"Connecting Ideas: However, Therefore and Although","level":"B1","module":16,"main":"Linking words make longer writing easier to follow. 'However' marks contrast; 'therefore' marks a result; 'although' introduces a concession.","how":"Punctuation depends on the linker. 'However' often begins a new sentence followed by a comma.","detail":"Linking words tell readers how ideas relate: addition, contrast, reason, result or concession. Choose a connector that matches the relationship and punctuate it correctly.","rules":"Punctuation of connecting adverbs\nHowever and therefore can connect ideas across sentences, but they do not work like although or because.\nUse appropriate punctuation.\n\n EXAMPLE The train was late. However, we arrived on time.\n\n EXAMPLE It rained; therefore, the match was cancelled.","examples":["The task was difficult. However, we finished it.","It was raining; therefore, we stayed in.","Although costs rose, sales improved.","The journey was long, but the meeting was useful.","The data were incomplete; therefore, we checked again.","It rained; however, we went out.","We were late; therefore, we took a taxi.","Although prices rose, demand stayed strong.","The plan is simple; moreover, it is affordable.","We changed the date because the hall was unavailable."]},{"id":"130","title":"Relative Words: Where, When and Whose","level":"B1","module":16,"main":"Relative words can add information about a place, a time or possession: where, when and whose.","how":"A relative clause should connect clearly to the noun it describes. 'Whose' can refer to people and sometimes things.","detail":"","rules":"Whose shows possession\nUse whose for people and sometimes things. Where and when can introduce relative clauses connected to\nplace and time.\n\n EXAMPLE This is the colleague whose desk is near mine.\n\n EXAMPLE Monday is the day when we meet.","examples":["This is the office where I started.","I remember the day when we met.","That's the colleague whose car was stolen.","Monday is the day when our team meets.","She is the colleague whose phone was lost.","This is the hotel where we stayed.","Friday is the day when we meet.","She knows a writer whose books are popular.","That's the office where I started work.","I remember the year when we moved here."]},{"id":"131","title":"Question Tags: Asking for Confirmation","level":"B1","module":16,"main":"A question tag is a short question added to a statement to check or confirm information.","how":"Usually a positive statement takes a negative tag, and a negative statement takes a positive tag. Pronouns and auxiliaries must match.","detail":"","rules":"Tags match the auxiliary and polarity\nA positive statement often takes a negative tag, and vice versa. Match the auxiliary and the subject\npronoun.\n\n EXAMPLE You are ready, aren’t you?\n\n EXAMPLE She doesn’t drive, does she?","examples":["You're coming, aren't you?","She doesn't drive, does she?","They were late, weren't they?","You haven't finished, have you?","It's very quiet today, isn't it?","You work here, don't you?","She isn't coming, is she?","They have finished, haven't they?","He can drive, can't he?","We're early, aren't we?"]},{"id":"132","title":"Indirect Questions: More Polite Language","level":"B1","module":16,"main":"An indirect question embeds a question inside a polite phrase. The embedded part has statement word order.","how":"Start with 'Could you tell me ...?' or 'Do you know ...?' Do not invert the subject inside the embedded question.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"Indirect questions use statement word order\nFor a polite indirect question, do not invert the subject and verb inside the embedded question.\n\n EXAMPLE Where is the station? -> Could you tell me where the station is?","examples":["Where is the station? -> Could you tell me where the station is?","Do you know when the meeting starts?","I'd like to know whether it is available.","Would you mind telling me where reception is?","Could you explain how I can apply?","Could you tell me where the bank is?","Do you know when the shop opens?","I'd like to know if the room is free.","Could you explain how this works?","Would you mind telling me what time it is?"]},{"id":"133","title":"Discourse Markers: Sequencing and Opinions","level":"B1","module":16,"main":"Discourse markers guide a listener or reader through your ideas. They can introduce a point, add information, contrast or conclude.","how":"Choose simple markers that fit the purpose. Too many markers can make speech sound unnatural.","detail":"","rules":"","examples":["First, I'll explain the problem.","For example, we could change the schedule.","To sum up, we need more time.","Secondly, we should consider the budget.","In conclusion, I recommend the second option.","First, let's review the figures.","Next, I'll explain the problem.","In my view, the plan is practical.","On the other hand, it may be costly.","To sum up, we need a clear schedule."]},{"id":"134","title":"Paraphrase and Summarise a Short Text","level":"B1","module":16,"main":"Paraphrasing expresses an idea in new words while keeping its meaning. Summarising gives only the most important points.","how":"Check that a paraphrase does not add information. In academic work, changing words does not remove the need to cite sources.","detail":"","rules":"","examples":["Original: The price rose quickly. Paraphrase: The cost increased rapidly.","Summary: Three teams proposed different solutions.","The report says sales fell in April.","The main point is that the trial saved time.","In short, the article questions the earlier figures.","The article discusses three main issues.","In short, the report recommends a trial.","The writer argues that costs may rise.","The main point is that access has improved.","Put simply, the service needs more staff."]},{"id":"135","title":"Write Clear Paragraphs and Work Emails","level":"B1","module":16,"main":"A clear paragraph begins with a main idea, supports it with detail and ends naturally. Emails need purpose, action and polite tone.","how":"One paragraph is often enough for one idea. Use short, direct sentences before experimenting with complex structures.","detail":"","rules":"","examples":["I'm writing to confirm our appointment.","The new process saves time because it reduces errors.","Please reply by Friday if possible.","I am writing to confirm our appointment.","Please find the revised schedule attached.","Dear Ms Brown, please find the details below.","Our new policy starts on Monday.","Firstly, the change will save time.","Please contact me if you have questions.","Thank you for your continued support."]},{"id":"136","title":"B1 Review and Level Check: Speaking and Writing","level":"B1","module":16,"main":"This B1 review checks story tenses, reported speech, passive forms, modals, connected writing and clearer workplace speaking.","how":"For each wrong answer, identify the reason. Try a short spoken explanation and a six-sentence email without looking at notes.","detail":"","rules":"","examples":["She said she was ready.","The documents were delivered yesterday.","If I had more time, I would volunteer.","I am writing to confirm our appointment.","Please find the revised schedule attached.","I have been studying for six months.","She asked whether the meeting had ended.","The forms should be completed today.","Although the journey was long, we enjoyed it.","Could you tell me how to apply?"]},{"id":"137","title":"Present Perfect Continuous: Uses and Nuances","level":"B2","module":17,"main":"The present perfect continuous highlights activity over a period leading to now. It often explains a present result, such as tiredness or progress.","how":"Compare the activity focus with the present perfect simple's result focus. Not every verb naturally takes the continuous form.","detail":"The present perfect connects the past with the present. It can describe experience, change, and a period that is still relevant; the past simple often gives the finished time.","rules":"Result or duration?\nHave done foregrounds the result or number completed; have been doing highlights the activity over a\nperiod of time. State verbs often resist continuous aspect.\n\n EXAMPLE I have repaired two computers.\n\n EXAMPLE I have been repairing computers all morning.","examples":["I've been studying all afternoon.","She's been working here since May.","I've finished the report.","I have worked here for two years.","I joined the team in 2024.","I've been waiting for an hour.","She's been working on a new project.","We've known each other for years.","The road has been getting busier.","Why have you been studying so late?"]},{"id":"138","title":"Past Perfect Continuous: Duration Before the Past","level":"B2","module":17,"main":"The past perfect continuous describes an activity continuing before a later moment in the past: had been + verb-ing.","how":"Use it to explain a past condition or duration. Past perfect simple may focus more on completion.","detail":"The past perfect shows that something was already complete before another past point. Use it when the order would otherwise be unclear.","rules":"Past perfect continuous form\nUse had been + verb-ing to show an activity continuing up to a past reference point.\n\n EXAMPLE I had been waiting for an hour when the bus arrived.","examples":["She had been waiting for an hour when the bus came.","They were tired because they'd been travelling.","He had been working all day before the meeting.","The train had left before we arrived.","She had completed the report by noon.","He had been working all morning when he stopped.","They had been living abroad before they moved home.","She was tired because she'd been travelling.","How long had you been waiting?","We had been discussing the issue for hours."]},{"id":"139","title":"Future Continuous and Future Perfect Simple","level":"B2","module":17,"main":"Future continuous describes an action in progress at a future time. Future perfect simple describes something completed before a future deadline.","how":"Forms: 'will be working' and 'will have finished'. A time phrase makes the intended meaning clearer.","detail":"English uses more than one structure to refer to the future. Use the form that best matches your meaning: an intention, a prior arrangement, a timetable or a prediction.","rules":"Future perfect vs future continuous\nWill have + past participle focuses on completion by a future point. Will be + -ing focuses on progress at\nthat point.\n\n EXAMPLE By noon, I will have finished.\n\n EXAMPLE At noon, I will be working.","examples":["At noon, I'll be meeting a client.","By Friday, I will have completed the report.","Will you have left by eight?","I am going to apply for the job.","The conference begins on Monday.","By Friday, we will have finished the work.","This time next week, I'll be travelling.","At ten, they will be meeting the director.","By 2030, the company will have opened five branches.","Will you have completed the course by then?"]},{"id":"140","title":"Future in the Past: Was Going To and Would","level":"B2","module":17,"main":"Future in the past looks forward from an earlier past moment. Use 'was/were going to' for a past plan and 'would' for a later event viewed from the past.","how":"A past plan may have happened or may have changed; context tells us what occurred.","detail":"English uses more than one structure to refer to the future. Use the form that best matches your meaning: an intention, a prior arrangement, a timetable or a prediction.","rules":"Future in the past\nUse was/were going to or would when describing what was future from a past viewpoint.\n\n EXAMPLE I was going to call, but I forgot.\n\n EXAMPLE She said she would help.","examples":["I was going to phone, but I forgot.","She said she would email the files.","We were leaving the next day.","I am going to apply for the job.","The conference begins on Monday.","She said she would call the next day.","I was going to write, but I forgot.","They were about to leave when it rained.","He knew the project would take months.","We expected that prices would increase."]},{"id":"141","title":"Will and Would for Habits and Tendencies","level":"B2","module":17,"main":"'Will' can describe present habits or typical behaviour; 'would' can describe repeated past behaviour and typical behaviour in a hypothetical context.","how":"These uses are different from a simple future prediction. Use context to make time and meaning clear.","detail":"","rules":"Would for repeated past actions\nWould can describe repeated past actions in narratives, but used to can also describe past states. Do not\nassume would has the same meaning in every context.\n\n EXAMPLE Every summer, we would visit our grandparents.\n\n EXAMPLE I used to own a bicycle.","examples":["He'll often stay late to help.","Every summer, we would visit our grandparents.","She would always bring extra notes.","He will often sit and read for hours.","As a child, I would visit my grandmother every Sunday.","When we were young, we would meet every weekend.","He will keep asking difficult questions.","She would often stay late to help.","The printer won't start today.","Our neighbour will sometimes play loud music."]},{"id":"142","title":"Be Used To and Get Used To","level":"B2","module":17,"main":"'Be used to' means be familiar or comfortable with something. 'Get used to' means become familiar over time.","how":"After 'to' in these expressions, use a noun or an -ing form, not a base verb. Compare with 'used to + verb' for old habits.","detail":"","rules":"Used to do vs be used to doing\nUsed to + base verb is a past habit; be/get used to + noun or -ing refers to familiarity or becoming familiar.\n\n EXAMPLE I used to drive to work.\n EXAMPLE I am used to driving early.\n\n EXAMPLE I am getting used to it.","examples":["I'm used to early shifts.","She's getting used to driving on the left.","I used to work nights.","We're getting used to the new timetable.","He isn't used to working at weekends.","I'm used to working at night.","She is getting used to the weather.","We're used to taking the train.","It took me months to get used to driving here.","Are you used to speaking English at work?"]},{"id":"143","title":"Narrative Tenses: Changing the Viewpoint","level":"B2","module":17,"main":"Narrative tenses help a speaker choose where to place the listener in time. Past simple advances the story; continuous sets the scene; perfect explains earlier events.","how":"Use enough tense variety to show sequence, but avoid changing forms without a clear reason.","detail":"","rules":"","examples":["It was raining when I arrived.","The guests had already left.","Suddenly, the lights went out.","The bus had already left when she reached the stop.","While he was speaking, the lights went out.","I was walking home when the lights went out.","She had already left by the time I arrived.","The phone rang; nobody answered.","He was reading while the others talked.","It had been raining, so the road was wet."]},{"id":"144","title":"Practice: Time and Aspect in Interviews","level":"B2","module":17,"main":"In interviews, accurate time choices help you describe experience, achievements, ongoing responsibilities and future intentions.","how":"A strong answer connects an action with a measurable or concrete result and remains truthful.","detail":"Clear communication involves listening, giving relevant information and checking understanding. Use expressions suited to the other person and the situation.","rules":"","examples":["I've managed a team for three years.","I was preparing a report when the issue appeared.","By next month, I'll have finished the training.","Could you explain that point, please?","To summarise, we recommend the second option.","I had worked in sales before I moved to finance.","I've been training new staff since April.","By next year, I'll have completed my qualification.","I was preparing the report when the client called.","I used to travel more in my previous role."]},{"id":"145","title":"Must Have and Cannot Have: Past Deductions","level":"B2","module":18,"main":"Use 'must have + past participle' for a strong deduction about the past and 'can't have + past participle' when evidence makes a past event seem impossible.","how":"These express conclusions, not direct observation. State the evidence rather than pretending to know.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Past deductions with must have\nMust have + past participle suggests a very strong conclusion about a past event; can’t have + past\nparticiple rejects a past possibility.\n\n EXAMPLE He must have left.\n\n EXAMPLE She can’t have known.","examples":["The floor is wet; it must have rained.","He can't have sent it yesterday; the file was created today.","She must have missed the train.","You should check the address.","She might arrive late.","He must have taken an earlier flight.","He can't have forgotten the date.","They must have left early.","That couldn't have been the correct answer.","The file must have been deleted accidentally."]},{"id":"146","title":"Might Have, May Have and Could Have","level":"B2","module":18,"main":"'May/might/could have + past participle' expresses possible past explanations without claiming certainty.","how":"Compare with 'must have', which expresses a stronger conclusion. Consider several plausible explanations before choosing one.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Possible past events\nMay/might/could have + past participle describe uncertain past possibilities. Could have may also mean\nunrealised ability or opportunity, depending on context.\n\n EXAMPLE She might have missed the train.\n\n EXAMPLE We could have taken a taxi.","examples":["The package may have arrived early.","She might have taken the wrong exit.","They could have misunderstood the instructions.","You should check the address.","She might arrive late.","He might have taken the wrong bus.","They may have misunderstood the email.","She could have left her phone at home.","The parcel might have arrived already.","We may have chosen the wrong date."]},{"id":"147","title":"Should Have and Ought To Have: Regrets","level":"B2","module":18,"main":"'Should have' and 'ought to have' often express a past action that would have been better, but did not happen.","how":"They can express criticism or regret, so tone matters. Use 'shouldn't have' for an unwise action that did happen.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Should have: expected but not done\nShould have + past participle can criticise a past choice or describe a missed obligation. The opposite\nshouldn’t have can express regret about something done.\n\n EXAMPLE I should have checked.\n\n EXAMPLE I shouldn’t have said that.","examples":["I should have saved the document.","You ought to have checked the date.","We shouldn't have left so late.","You should check the address.","She might arrive late.","I should have called earlier.","You ought to have checked the address.","We shouldn't have ignored the warning.","She should have kept a copy.","They ought to have asked for help."]},{"id":"148","title":"Third Conditional: Imaginary Past","level":"B2","module":18,"main":"The third conditional imagines a different past and its imagined result: if + past perfect, would have + past participle.","how":"The event did not happen as described. This form helps discuss causes, lost chances and regrets.","detail":"Conditional structures connect a situation and its result. The tense pattern helps show whether something is generally true, possible, imaginary or contrary to past fact.","rules":"Third conditional\nUse if + past perfect and would have + past participle for an unreal past result.\n\n EXAMPLE If I had studied, I would have passed.","examples":["If we'd left earlier, we'd have arrived on time.","She would have passed if she'd studied more.","If it hadn't rained, we would have walked.","If it rains, we will stay inside.","If I had more time, I would practise.","If I'd studied more, I would have passed.","She would have arrived on time if she'd left earlier.","If we had booked ahead, we'd have saved money.","He wouldn't have missed the bus if he'd hurried.","What would you have done if you'd known?"]},{"id":"149","title":"Mixed Conditionals: Past and Present Results","level":"B2","module":18,"main":"Mixed conditionals connect different times: a past condition can explain a present result, or a present condition can explain a past result.","how":"Keep the time relationship clear. Do not automatically use the same verb form in both clauses.","detail":"Conditional structures connect a situation and its result. The tense pattern helps show whether something is generally true, possible, imaginary or contrary to past fact.","rules":"Mixed conditionals connect different times\nA common mixed form puts a past unreal condition with a present imagined result. Other time\ncombinations are possible.\n\n EXAMPLE If I had learnt to drive, I would be more independent now.","examples":["If I'd accepted the job, I'd live abroad now.","If she were more careful, she wouldn't have lost the file.","I'd be healthier now if I'd slept more.","If it rains, we will stay inside.","If I had more time, I would practise.","If I'd accepted the role, I'd be living abroad now.","She would be healthier if she'd stopped smoking.","If I were more organised, I wouldn't have missed the deadline.","We'd have finished on time if we were better prepared.","If he had trained earlier, he could lead the team now."]},{"id":"150","title":"Wish and If Only: Regrets About the Past","level":"B2","module":18,"main":"'Wish' and 'if only' with the past perfect express regret about a past situation.","how":"'If only' often sounds more emotional. Use these forms thoughtfully when speaking about decisions.","detail":"","rules":"Wish + past perfect for past regret\nWish + had + past participle refers to an earlier action or situation we want to change.\n\n EXAMPLE I wish I had saved the file.","examples":["I wish I'd kept a copy.","If only we'd left earlier!","She wishes she hadn't missed the meeting.","I wish I had saved the document.","If only she hadn't missed the interview!","I wish I had listened carefully.","If only she had told me sooner!","She wishes she hadn't sold the car.","I wish I'd taken your advice.","If only he had remembered the documents."]},{"id":"151","title":"Would Rather and It Is Time","level":"B2","module":18,"main":"'Would rather' expresses a preference. 'It's time' suggests an action is due, sometimes using a past form for a present expectation.","how":"'I'd rather go' takes the base verb; 'I'd rather you went' uses past form for another person's action now or later.","detail":"","rules":"Would rather + base; would rather someone + past\nWould rather can show a present preference. When it refers to another person’s behaviour, a past form\nmay show the unreal preference.\n\n EXAMPLE I’d rather wait.\n\n EXAMPLE I’d rather you stayed.","examples":["I'd rather stay home tonight.","I'd rather you called tomorrow.","It's time we started the meeting.","I'd rather not discuss the issue today.","It's time we made a final decision.","I would rather take the train.","She'd rather you called tomorrow.","It's time we left for the station.","I'd rather not discuss it now.","It's about time the company changed its policy."]},{"id":"152","title":"Practice: Discuss Decisions and Consequences","level":"B2","module":18,"main":"When discussing decisions, distinguish facts from possible explanations and imagined alternatives.","how":"Use modals to show certainty and conditionals to discuss consequences. Acknowledge what is unknown.","detail":"","rules":"","examples":["We might have missed an earlier warning.","If we'd checked sooner, we could have avoided the delay.","Next time, we should confirm the figures.","We would have succeeded if we had started earlier.","They should have checked the terms before signing.","If we had planned better, we'd have avoided the delay.","We should have checked the figures.","I'd rather choose the less expensive option.","The manager may have misunderstood the request.","It's time we reviewed our priorities."]},{"id":"153","title":"Passive Voice: Complex Forms and Agents","level":"B2","module":19,"main":"Complex passives keep attention on an event, process or outcome. The 'by' phrase is optional when the agent is unknown or unimportant.","how":"Different tenses and infinitive patterns produce forms such as 'has been repaired' and 'is expected to be delivered'.","detail":"The passive focuses on what happens to someone or something. It commonly uses be + past participle; the agent may be omitted when unknown or unimportant.","rules":"Keep agents only when useful\nThe passive can omit the agent when it is unknown, obvious or unimportant. Use by when the agent\nmatters.\n\n EXAMPLE The bridge was built in 1990.\n\n EXAMPLE The bridge was designed by a local architect.","examples":["The system has been updated.","The documents are being reviewed.","The proposal was rejected by the board.","The form was sent yesterday.","All requests must be approved.","The repairs are being carried out today.","The report had been submitted before noon.","The notice was written by the manager.","The new service will have been launched by June.","The contract should have been checked carefully."]},{"id":"154","title":"Reporting Passives: It Is Said That ...","level":"B2","module":19,"main":"Reporting passives allow a cautious or impersonal report: 'It is said that ...' or 'He is believed to ...'.","how":"Use them when reporting claims rather than confirming facts. Do not remove necessary qualifications or sources.","detail":"The passive focuses on what happens to someone or something. It commonly uses be + past participle; the agent may be omitted when unknown or unimportant.","rules":"Reporting passive patterns\nCommon formal patterns are It is said that ... and Subject + is said to ... . Be careful with tense and meaning.\n\n  EXAMPLE It is said that the company will expand.\n\n  EXAMPLE The company is said to be expanding.","examples":["It is believed that the service will expand.","The company is said to be hiring.","He is thought to have left yesterday.","The form was sent yesterday.","All requests must be approved.","It is believed that the system is secure.","The director is said to be abroad.","It has been reported that costs are rising.","The company is thought to have expanded.","The problem is expected to be resolved soon."]},{"id":"155","title":"Causatives: Have and Get Something Done","level":"B2","module":19,"main":"A causative describes arranging for someone else to do a task: have/get something done.","how":"Compare 'I repaired my car' (I did it) with 'I had my car repaired' (another person did it).","detail":"","rules":"Have/get something done\nThe causative form describes arranging for another person to perform a service, though context can also\ndescribe an unwanted experience.\n\n EXAMPLE I had my car repaired.\n\n EXAMPLE She got her hair cut.","examples":["I had my laptop repaired.","She got her hair cut yesterday.","We're having the windows cleaned.","She got the carpet cleaned professionally.","They are having the office renovated.","I had my car repaired yesterday.","She got her hair cut last week.","We're having the office painted.","He will get the documents translated.","Have you had your passport renewed?"]},{"id":"156","title":"Reported Speech: Backshift and Time References","level":"B2","module":19,"main":"Reported speech often shifts tenses, pronouns and time expressions to match the new reporting situation.","how":"Backshift is not always needed when the statement remains true or the report is immediate. Meaning comes first.","detail":"Reported language tells another person what someone said or asked. Pronouns, time words and verb tenses may change depending on the time and viewpoint of the report.","rules":"Reported speech time-reference changes\nYesterday may become the day before, tomorrow may become the following day, and here may become\nthere if the viewpoint changes.\n\n EXAMPLE “I will call tomorrow.” -> She said she would call the following day.","examples":["'I'll call tomorrow' -> She said she'd call the next day.","'I work here' -> He said he worked there.","She told us the meeting had been delayed.","She said that she was ready.","He asked whether the meeting had started.","She said she had seen him the previous day.","He told me he would arrive the following morning.","They said they were working on the proposal.","She explained that she couldn't come that evening.","The manager said the figures had changed."]},{"id":"157","title":"Reporting Verbs: Admit, Deny, Suggest and Promise","level":"B2","module":19,"main":"Reporting verbs add information about the speaker's intention. Different verbs take different patterns, so learn each with a model sentence.","how":"For example, 'deny + -ing', 'promise + to-infinitive', 'suggest + -ing or that-clause', and 'admit + -ing'.","detail":"","rules":"Reporting verbs take different patterns\nUse admit + -ing, deny + -ing, promise + to, suggest + -ing / that-clause, and tell + object + to.\n\n EXAMPLE admitted making an error\n EXAMPLE promised to help\n\n EXAMPLE suggested taking a break","examples":["He denied taking the money.","She promised to reply.","They suggested meeting earlier.","I am writing to confirm our appointment.","Please find the revised schedule attached.","He admitted making a mistake.","She denied copying the text.","He admitted losing the keys.","I promised to send the document.","The trainer encouraged us to practise."]},{"id":"158","title":"Participle Clauses: An Introduction","level":"B2","module":19,"main":"A participle clause uses an -ing or past-participle form to add information without a full separate clause.","how":"The understood subject should be clear and normally match the subject of the main clause, avoiding dangling modifiers.","detail":"","rules":"Participial clauses need a clear subject\nThe implied subject of a participle clause should usually match the subject of the main clause. Avoid\ndangling participles.\n\n EXAMPLE Walking into the office, I saw the manager. (I was walking)","examples":["Walking to work, I saw a colleague.","Built in 1995, the bridge needs repairs.","Having finished, she went home.","Having checked the details, he signed the form.","Made from recycled materials, the bag is light.","Walking to work, I noticed the roadworks.","Designed for adults, the course is practical.","After finishing the report, she went home.","Feeling tired, he took a break.","The documents submitted yesterday need checking."]},{"id":"159","title":"Reduced Relative Clauses","level":"B2","module":19,"main":"A reduced relative clause shortens certain clauses when the meaning remains clear.","how":"An active relative clause can become an -ing phrase; a passive clause may become a past-participle phrase.","detail":"A relative clause identifies or adds information about a noun. Some clauses are necessary to identify the noun, while others add extra detail and are separated by commas.","rules":"Reduced relative clause patterns\nA defining relative clause can sometimes be reduced using a present participle for active meaning or past\nparticiple for passive meaning.\n\n EXAMPLE people who work here -> people working here\n\n EXAMPLE the report that was sent -> the report sent","examples":["The people waiting outside are visitors.","The report sent yesterday is important.","Anyone interested should email me.","The colleague who called is here.","My office, which is small, is quiet.","The woman sitting near the door is my supervisor.","The files stored on this computer are secure.","The people invited to the meeting arrived early.","The road leading to the station is closed.","The results published yesterday were encouraging."]},{"id":"160","title":"Practice: Rewrite and Improve a Report","level":"B2","module":19,"main":"Improving a report means checking accuracy, structure, clarity and whether a passive is useful.","how":"Use reporting verbs for claims, distinguish known facts from opinions, and remove unnecessary repetition.","detail":"","rules":"","examples":["The report was submitted on Monday.","The supplier confirmed that delivery was delayed.","The issue is being investigated.","I am writing to confirm our appointment.","Please find the revised schedule attached.","The notice was issued on Tuesday.","Having checked the figures, we corrected the table.","The report, which was updated yesterday, is online.","It is believed that demand will grow.","We had the equipment checked last month."]},{"id":"161","title":"Articles: Abstract, General and Institutional Uses","level":"B2","module":20,"main":"Articles can signal generic categories, specific reference and special institutional meanings. The pattern may change meaning.","how":"Compare 'go to school' as an activity/institution with 'go to the school' as a particular building. Usage varies with context.","detail":"Article choice depends on sound, number and whether the listener can identify the noun. Use a/an for one non-specific singular countable thing; the when the thing is known or identified.","rules":"Institutions: with or without the\nIn British usage, school, hospital, prison and university may appear without the when discussing their main\ninstitutional purpose, with individual patterns and differences.\n\n EXAMPLE go to school\n EXAMPLE be in hospital (British)\n\n EXAMPLE go to the hospital to visit someone","examples":["Children go to school in September.","I went to the school to meet the headteacher.","The honesty of the report matters.","I need a pen. The pen is on the desk.","She is an engineer.","Education is important for everyone.","She is in hospital after an accident.","He went to the hospital to visit his friend.","The internet has changed our lives.","Employees need regular training."]},{"id":"162","title":"Advanced Determiners and Quantifiers","level":"B2","module":20,"main":"Advanced determiners narrow or measure a noun phrase: several, either, neither, a great deal of, plenty of, a number of and the number of.","how":"Pay attention to agreement. 'A number of people are ...' differs from 'The number of people is ...'.","detail":"First decide whether the noun is countable or uncountable. Then choose the quantity expression that matches the noun and your meaning.","rules":"Both vs either vs neither\nBoth refers to two together, either to one of two, and neither to not one and not the other.\n\n EXAMPLE Both options work.\n EXAMPLE Either option is fine.\n\n EXAMPLE Neither option is suitable.","examples":["A number of staff are absent.","The number of visitors is increasing.","Neither option seems ideal.","There are a few chairs.","We have a little time.","Few applicants met the criteria.","A few employees asked for more time.","Neither of the plans is suitable.","Each of the rooms has a window.","A considerable amount of time was saved."]},{"id":"163","title":"‐ed and ‐ing Adjectives: Feelings and Causes","level":"B2","module":20,"main":"Adjectives ending in -ed often describe a person's feeling; -ing adjectives often describe the thing causing that feeling.","how":"This distinction is common with interested/interesting, bored/boring and surprised/surprising.","detail":"An adjective adds information to a noun. Many adjectives appear before nouns or after linking verbs such as be, seem and feel. Adjectives normally do not change for plural nouns.","rules":"-ed vs -ing adjectives\n-ed adjectives often describe a person’s feelings; -ing adjectives often describe the thing producing the\nfeeling.\n\n EXAMPLE I am bored.\n\n EXAMPLE The lecture is boring.","examples":["I'm interested in the project.","The presentation was interesting.","We were surprised by the result.","It is a quiet office.","The offices are quiet.","I'm interested in the new role.","The workshop was interesting.","She felt exhausted after the flight.","The delay was frustrating.","He was surprised by the news."]},{"id":"164","title":"Gradable and Non‐Gradable Adjectives","level":"B2","module":20,"main":"Gradable adjectives allow degrees, such as 'very cold'; non-gradable adjectives often express an extreme or absolute idea.","how":"Common intensifiers differ: 'very tired' but 'absolutely exhausted'. Real usage has flexibility and context matters.","detail":"An adjective adds information to a noun. Many adjectives appear before nouns or after linking verbs such as be, seem and feel. Adjectives normally do not change for plural nouns.","rules":"Very and absolutely are not interchangeable\nGradable adjectives commonly take very; strongly non-gradable words commonly take absolutely or\ncompletely. Real usage varies by context.\n\n EXAMPLE very cold\n EXAMPLE absolutely freezing\n\n EXAMPLE completely impossible","examples":["The room is very cold.","I'm absolutely exhausted.","The result was completely unexpected.","It is a quiet office.","The offices are quiet.","The room is absolutely freezing.","She is very tired today.","The result was completely impossible.","The new plan is fairly good.","We were absolutely delighted."]},{"id":"165","title":"Adverbs: Position, Focus and Attitude","level":"B2","module":20,"main":"An adverb's position can change emphasis or meaning. Adverbs may describe time, manner, degree or a speaker's attitude.","how":"Compare 'Only Sara called' and 'Sara only called': the focus of 'only' changes.","detail":"Adverbs can describe how, when, where or how often something happens. Their position changes with the kind of adverb and the message you want to emphasise.","rules":"Adverb placement changes focus\nOnly, even and just can change which part of a statement is emphasised. Place them carefully to avoid a\ndifferent meaning.\n\n EXAMPLE Only Maya sent the file.\n\n EXAMPLE Maya only sent the file.","examples":["Only the manager approved it.","She has already replied.","Fortunately, nobody was hurt.","She speaks clearly during meetings.","We usually arrive early.","Fortunately, nobody was injured.","She has only sent the first draft.","He usually works from home.","The results clearly show a change.","Frankly, I disagree with the proposal."]},{"id":"166","title":"Remember, Stop and Try: Changes in Verb Meaning","level":"B2","module":20,"main":"Verbs such as remember, stop and try may take -ing or to-infinitive with a change in meaning.","how":"'Try to open' means make an effort; 'try opening' suggests testing a possible solution.","detail":"","rules":"Three high-value verb contrasts\nRemember to do = do not forget; remember doing = recall a memory. Stop doing = end activity; stop to do\n= pause for a purpose. Try doing = experiment; try to do = make an effort.\n\n EXAMPLE I stopped working. / I stopped to rest.\n\n EXAMPLE Try pressing this button. / Try to reach the button.","examples":["Remember to send the report.","I remember sending it.","Try restarting your computer.","Please remember to post the invitation.","I remember speaking to her last year.","I remember posting the letter.","Remember to lock the door.","He stopped drinking coffee.","She stopped to answer the phone.","Try restarting the computer."]},{"id":"167","title":"Preposition Patterns and Collocations","level":"B2","module":20,"main":"A collocation is a natural combination of words. Many verbs and adjectives take fixed prepositions.","how":"Study a whole phrase: 'depend on', 'apply for', 'aware of', 'good at'. Direct translation may produce unnatural combinations.","detail":"A preposition connects information about place, time, direction or another relationship. Many choices are learned as fixed patterns: interested in, depend on, at night.","rules":"Common fixed preposition patterns\nLearn the phrase as a unit instead of translating one preposition at a time.\n\n EXAMPLE depend on\n\n EXAMPLE interested in\n\n EXAMPLE good at\n EXAMPLE apply for\n\n EXAMPLE apologise for","examples":["We depend on accurate data.","She applied for a new role.","I'm aware of the delay.","The files are on the shelf.","We arrived at the station.","She is responsible for recruitment.","We depend on reliable data.","He insisted on paying the bill.","They are interested in the outcome.","We agreed on a new timetable."]},{"id":"168","title":"Phrasal Verbs: Word Order and Particles","level":"B2","module":20,"main":"Some phrasal verbs allow their object between the verb and particle; others do not. A pronoun often must appear between in separable verbs.","how":"'Turn off the light' and 'turn the light off' are correct, but 'turn it off' is preferred over 'turn off it'.","detail":"Article choice depends on sound, number and whether the listener can identify the noun. Use a/an for one non-specific singular countable thing; the when the thing is known or identified.","rules":"Separable phrasal verbs and pronouns\nWith some transitive phrasal verbs, a noun object can go before or after the particle; a pronoun object\nnormally comes before it.\n\n EXAMPLE turn off the light / turn the light off\n\n EXAMPLE turn it off (not turn off it)","examples":["Please put the file away.","Please put it away.","She looks after her niece.","I need a pen. The pen is on the desk.","She is an engineer.","Please turn off the lights.","Turn the lights off before you leave.","Look after your passport.","We put the meeting off until Friday.","She picked it up from reception."]},{"id":"169","title":"Linking: Cause, Contrast, Concession and Result","level":"B2","module":21,"main":"Cause, contrast, concession and result are different logical relations. Choose connectives that match the actual connection.","how":"'Because' introduces cause; 'therefore' result; 'although' concession; 'whereas' contrast. Punctuation changes across patterns.","detail":"Linking words tell readers how ideas relate: addition, contrast, reason, result or concession. Choose a connector that matches the relationship and punctuate it correctly.","rules":"Contrast, reason and result\nAlthough + clause gives contrast; despite + noun/-ing also gives contrast. Because + clause gives a reason;\ntherefore often introduces a result.\n\n EXAMPLE Although she was tired, she worked.\n\n EXAMPLE Despite being tired, she worked.","examples":["Costs rose because materials were scarce.","Costs rose; therefore, prices increased.","Although the plan was expensive, it worked.","The journey was long, but the meeting was useful.","The data were incomplete; therefore, we checked again.","Costs increased because demand rose.","Although the weather was poor, we travelled.","Despite the delay, the meeting continued.","Therefore, a second review is necessary.","The plan was revised so that everyone could participate."]},{"id":"170","title":"Noun Clauses: That, Whether and Wh‐ Clauses","level":"B2","module":21,"main":"A noun clause acts as a subject, object or complement. It can begin with 'that', 'whether' or a wh-word.","how":"Inside the clause, use statement word order: 'I know where she lives', not 'where does she live'.","detail":"","rules":"Noun clauses can act as sentence parts\nA that-clause or wh-clause may function as a subject, object or complement. Embedded questions use\nstatement word order.\n\n EXAMPLE I know what she wants.\n\n EXAMPLE What matters is accuracy.","examples":["I believe that the plan will work.","Whether we proceed depends on cost.","I understand why she left.","Whether we proceed depends on the budget.","I don't know what caused the delay.","That the plan worked was a pleasant surprise.","We need to know whether the room is free.","What she said was helpful.","The question is why the results changed.","I'm not sure if he has arrived."]},{"id":"171","title":"Complex Noun Phrases: Adding Clear Details","level":"B2","module":21,"main":"A complex noun phrase packs information around a noun using determiners, adjectives, prepositional phrases and relative clauses.","how":"Long phrases can become hard to read. Put modifiers close to the noun they describe and check for ambiguity.","detail":"","rules":"Complex noun phrase: keep the head noun clear\nPre-modifiers usually come before the main noun and relative/prepositional phrases can add detail after it.\nAvoid piling up unclear modifiers.\n\n EXAMPLE a detailed quarterly sales report\n\n EXAMPLE the report from the manager","examples":["The new regional sales manager arrived.","The report on last quarter's costs is ready.","A proposal approved by the board was published.","The large glass entrance doors were locked.","An independent committee of experts reviewed the findings.","A small family-owned business opened nearby.","The long-awaited report was published today.","We attended an important training session for new staff.","The revised budget for next year is ready.","The newly appointed director addressed the team."]},{"id":"172","title":"Hedging: Seem, Tend, Likely and Apparently","level":"B2","module":21,"main":"Hedging makes a statement careful when the evidence is incomplete. Useful forms include 'seems', 'appears', 'tends to', 'is likely to' and 'apparently'.","how":"Hedging should reflect real uncertainty, not hide established facts.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"Hedging avoids overclaiming\nMay, might, seem, appear and tend to signal caution. Use them when evidence is limited.\n\n EXAMPLE The data suggest a possible improvement.\n\n EXAMPLE This approach may help.","examples":["The figures appear to be correct.","Demand is likely to rise.","This method tends to reduce errors.","The problem seems less serious now.","The delay is apparently due to roadworks.","The results seem encouraging.","Prices are likely to increase.","She seems to understand the problem.","He tends to arrive early.","Apparently, the road is closed again."]},{"id":"173","title":"Formal vs Informal Style at Work","level":"B2","module":21,"main":"Formal and informal English differ in word choice, contractions, greetings and sentence structure. The best style depends on audience and purpose.","how":"Use clear, respectful language rather than complicated vocabulary simply to sound professional.","detail":"","rules":"","examples":["Informal: Can you send it over?","Formal: Could you please forward the document?","Informal: Thanks! Formal: Thank you for your assistance.","Informal: Can we meet? Formal: Could we arrange a meeting?","Informal: Sorry about that. Formal: Please accept my apologies.","Informal: Can you send it? Formal: Could you forward the document?","Informal: Sorry I'm late. Formal: Please accept my apologies for the delay.","Informal: I will ask. Formal: I will enquire.","Informal: We need more time. Formal: We would appreciate an extension.","Informal: Let's talk. Formal: Could we arrange a discussion?"]},{"id":"174","title":"Reports and Proposals: Clear Structure","level":"B2","module":21,"main":"A report describes information and findings; a proposal recommends a future action. Both need clear purpose, sections and evidence.","how":"Use headings, an executive summary when appropriate, and recommendations that follow from the findings.","detail":"","rules":"","examples":["Purpose: Review customer waiting times.","Finding: Average waiting time increased in June.","Recommendation: Add staff during peak hours.","I am writing to confirm our appointment.","Please find the revised schedule attached.","Executive summary: The trial reduced waiting times.","Background: The current process takes too long.","Findings: Most users preferred the new form.","Recommendation: Extend the trial for one month.","Next steps: Review performance in June."]},{"id":"175","title":"Present and Defend an Opinion","level":"B2","module":21,"main":"To defend an opinion, state your view, give a reason, support it with evidence and acknowledge a reasonable objection.","how":"Disagree with the idea, not the person. Avoid certainty that the evidence does not support.","detail":"","rules":"","examples":["I believe flexible hours improve productivity.","For example, staff report fewer delays.","However, some roles require fixed coverage.","A short trial would allow us to collect evidence.","Even so, I understand the concern about costs.","I believe this approach is more practical.","One reason is that it saves time.","For example, a short trial would limit risk.","Some people disagree because costs may rise.","However, the long-term benefits are significant."]},{"id":"176","title":"B2 Review and Level Check: Integrated Skills","level":"B2","module":21,"main":"The B2 level check combines complex time forms, deduction, conditionals, passive voice, cohesive writing and clear argument.","how":"For speaking, explain a decision and its alternative. For writing, produce a short evidence-based proposal.","detail":"","rules":"","examples":["She might have missed the message.","The contract has been approved.","If we'd planned better, we'd have saved time.","The forms should be checked before submission.","It's the timing that makes this decision difficult.","She might have forgotten the appointment.","The report has been approved.","Had we known, we would have changed the plan.","Despite higher costs, the project continued.","The new procedure is expected to reduce delays."]},{"id":"177","title":"Inversion After Negative Adverbials","level":"C1","module":22,"main":"Inversion places an auxiliary before the subject after certain negative or limiting expressions at the start of a clause.","how":"This is formal or emphatic and is not needed in ordinary conversation. Examples include 'Never have I ...' and 'Rarely do we ...'.","detail":"Adverbs can describe how, when, where or how often something happens. Their position changes with the kind of adverb and the message you want to emphasise.","rules":"Negative inversion needs an auxiliary\nAfter a fronted negative adverbial such as Never or Rarely, invert the auxiliary and subject in formal English.\nUse do-support if necessary.\n\n EXAMPLE Never have I seen this.\n\n EXAMPLE Rarely do we receive complaints.","examples":["Never have I seen such a result.","Rarely do we receive complaints.","Not only did she call, but she also wrote.","She speaks clearly during meetings.","We usually arrive early.","Never have I seen such a clear report.","Rarely does he arrive late.","Not only did she call, but she also emailed.","Under no circumstances should you share passwords.","Seldom have we faced such a difficult decision."]},{"id":"178","title":"Conditional Inversion: Had, Were and Should","level":"C1","module":22,"main":"Formal conditionals sometimes omit 'if' and invert an auxiliary: 'Had I known', 'Were I', 'Should you need'.","how":"These patterns preserve the meaning of a corresponding if-clause but change tone and style.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"Formal if-less conditions\nWere, had and should can introduce formal conditional inversion when if is omitted.\n\n EXAMPLE Had I known, I would have helped.\n\n EXAMPLE Were I to choose, I would wait.","examples":["Had I known, I would have called.","Were it possible, we would help.","Should you require assistance, contact reception.","You should check the address.","She might arrive late.","Had I known earlier, I would have helped.","Were the data available, we could decide.","Should you need help, please call.","Had they left on time, they would have arrived earlier.","Were I in your position, I would ask for advice."]},{"id":"179","title":"Cleft Sentences: It Is ... That and What ... Is","level":"C1","module":22,"main":"A cleft sentence moves focus onto one part of an idea. 'It was X that ...' and 'What ... was X' are common patterns.","how":"Use clefts for contrast, correction and emphasis; use a normal sentence when no special focus is needed.","detail":"Writers and speakers can change normal word order to highlight an idea. Marked structures may sound formal or emphatic; use them only when they improve the message.","rules":"Cleft sentences highlight information\nIt-clefts and what-clefts can emphasise one element of a sentence without changing the basic event\ndescribed.\n\n  EXAMPLE It was on Monday that we met.\n\n  EXAMPLE What I need is a clear answer.","examples":["It was Emily who found the error.","What we need is more time.","It was on Monday that the change began.","Never have I seen such a clear result.","What mattered most was the timing.","It was Nadia who found the error.","What I need is a quiet place to work.","It is the timing that worries us.","What the team wants is more training.","It was yesterday that the system stopped."]},{"id":"180","title":"Fronting for Focus and Contrast","level":"C1","module":22,"main":"Fronting moves information to the beginning of a sentence for topic, focus or contrast.","how":"This is often useful in presentations and writing but may sound marked in ordinary talk. Check the sentence still reads clearly.","detail":"Writers and speakers can change normal word order to highlight an idea. Marked structures may sound formal or emphatic; use them only when they improve the message.","rules":"Fronting can be emphatic\nMoving information to the beginning can contrast or emphasise it. Ordinary neutral word order is often\nsafer in everyday writing.\n\n EXAMPLE This book, I really enjoyed.\n\n EXAMPLE That decision, I cannot support.","examples":["That proposal, we rejected.","In the corner stood a small desk.","What I need now is a clear answer.","Never have I seen such a clear result.","What we need is more time.","This proposal, I strongly support.","Across the street stood a small café.","Into the room walked the director.","That problem, we can solve later.","On the wall hung an old photograph."]},{"id":"181","title":"Emphatic Do and Other Auxiliary Emphasis","level":"C1","module":22,"main":"An emphatic 'do', 'does' or 'did' can strengthen an affirmative statement, especially when correcting a misunderstanding.","how":"Use the base verb after emphatic do. Stress the auxiliary when speaking: 'I DID send it'.","detail":"Writers and speakers can change normal word order to highlight an idea. Marked structures may sound formal or emphatic; use them only when they improve the message.","rules":"Emphatic do in affirmative statements\nDo/does/did can add emphasis in positive statements; the main verb stays in the base form.\n\n EXAMPLE I do agree.\n EXAMPLE She does work hard.\n\n EXAMPLE He did call.","examples":["I do understand your concern.","She does work hard.","He did send the email yesterday.","Never have I seen such a clear result.","What we need is more time.","I do understand the concern.","She does know the answer.","We did send the invitation.","He did apologise for the delay.","They do appreciate your help."]},{"id":"182","title":"Ellipsis and Substitution: Avoiding Repetition","level":"C1","module":22,"main":"Ellipsis leaves out words that are understood; substitution replaces repeated words with forms such as 'one', 'so' or 'do'.","how":"These devices make English more natural and less repetitive, but the listener must know what is missing.","detail":"","rules":"Avoid repeated words only when meaning stays clear\nEllipsis omits understood information. Substitution uses words like one, do or so. The omitted meaning\nmust be recoverable.\n\n EXAMPLE I prefer the blue one.\n\n EXAMPLE She can speak French, and he can too.","examples":["I can help, and Sara can too.","I need a larger one.","She said it was possible, and I think so too.","Some employees prefer mornings; others, evenings.","She chose the first option, and I did too.","I ordered tea, and she did too.","Some people agreed; others didn't.","Would you like the blue one or the red one?","He can speak French, and I can too.","I thought she would call, but she didn't."]},{"id":"183","title":"Marked Word Order and Topicalisation","level":"C1","module":22,"main":"Marked word order changes the normal arrangement to highlight a topic or contrast. This is common in conversation and some literary styles.","how":"In everyday language, you may use a topic phrase followed by a pause: 'That report, I haven't read it yet'.","detail":"Writers and speakers can change normal word order to highlight an idea. Marked structures may sound formal or emphatic; use them only when they improve the message.","rules":"","examples":["That idea, I really like.","On the table lay a letter.","As for next week, we have no plans.","Never have I seen such a clear result.","What we need is more time.","That suggestion, I cannot accept.","At the back of the room sat the director.","Such an outcome, nobody expected.","On the desk lay an unsigned letter.","The first report, we have already checked."]},{"id":"184","title":"Advanced Punctuation and Parenthetical Information","level":"C1","module":22,"main":"Punctuation guides meaning and reading pace. Commas mark many non-defining clauses, while dashes and brackets can add parenthetical information.","how":"Use a colon for a clear explanation or list and a semicolon for closely linked independent clauses when appropriate.","detail":"","rules":"Semicolons and colons have different jobs\nA semicolon can join closely related independent clauses; a colon can introduce an explanation or list\nfollowing a complete clause.\n\n EXAMPLE The results were clear; we changed the plan.\n\n EXAMPLE Bring three things: a pen, ID and a notebook.","examples":["The manager, who joined in June, is leaving.","We need three things: time, money and support.","The report was brief; the findings were clear.","The new policy - announced on Friday - starts today.","She listed the advantages: speed, cost and safety.","The manager - who joined last month - is leaving.","We need three items: a pen, a form and a passport.","She replied, 'I'll call tomorrow.'","The proposal (revised on Monday) is attached.","The decision was clear; the team agreed."]},{"id":"185","title":"Practice: Use Focus and Emphasis Naturally","level":"C1","module":22,"main":"Effective emphasis draws attention to a real contrast or key idea. Choose inversion, cleft sentences or lexical emphasis only when useful.","how":"Too many emphatic structures sound unnatural. A plain sentence is often the clearest choice.","detail":"","rules":"","examples":["It was the deadline that caused the problem.","Never had the team faced such pressure.","What matters most is accuracy.","What worries me is the lack of reliable data.","Not until Friday did we hear the final decision.","Never had the team worked so quickly.","It was the budget that caused concern.","That point, I agree with completely.","What we need is more reliable evidence.","She did finish the project on time."]},{"id":"186","title":"Present Simple and Continuous: Advanced Meanings","level":"C1","module":23,"main":"Advanced use of the present simple and continuous includes temporary trends, habitual irritation and scheduled commentary.","how":"An -ing form can express repeated behaviour with an attitude: 'He's always interrupting'. A present simple can make live commentary vivid.","detail":"Use the present simple for routines, habits, general facts and many timetables. Questions and negatives usually need do or does; be is different.","rules":"The present continuous can signal temporary or repeated irritation\nPresent continuous is not limited to this instant. With always, it can express an emotional judgement about\na repeated action.\n\n EXAMPLE I’m staying with friends this month.\n\n EXAMPLE He’s always losing his keys!","examples":["Sales are increasing this quarter.","He's always misplacing his keys.","The striker passes, shoots and scores.","I start work at eight.","Does she work on Fridays?","Water freezes at zero degrees Celsius.","We're seeing more enquiries this month.","He is always leaving his phone behind.","She works in finance, but she's working on a special project today.","The train leaves at seven every morning."]},{"id":"187","title":"Future Perfect Continuous","level":"C1","module":23,"main":"Future perfect continuous focuses on how long an activity will have continued by a future point: will have been + verb-ing.","how":"Use it with a future reference point and duration. Compare with future perfect simple when completion is the main point.","detail":"English uses more than one structure to refer to the future. Use the form that best matches your meaning: an intention, a prior arrangement, a timetable or a prediction.","rules":"Future perfect continuous\nUse will have been + verb-ing for the duration of an activity up to a future time.\n\n EXAMPLE By June, she will have been working here for ten years.","examples":["By May, I'll have been working here for ten years.","At noon, she will have been travelling for six hours.","By then, we'll have been waiting all morning.","I am going to apply for the job.","The conference begins on Monday.","By June, I'll have been working here for five years.","At noon, she will have been travelling for eight hours.","Next month, we'll have been living here for a decade.","By Friday, they will have been testing the system for six weeks.","How long will you have been studying by December?"]},{"id":"188","title":"Future in the Past: Unfulfilled Plans","level":"C1","module":23,"main":"Future in the past can show a plan that was later cancelled or an expected event that did not happen.","how":"Past forms such as 'was going to', 'was about to', and 'would have' carry different meanings. Say what changed if relevant.","detail":"English uses more than one structure to refer to the future. Use the form that best matches your meaning: an intention, a prior arrangement, a timetable or a prediction.","rules":"","examples":["We were going to leave, but the road closed.","I was about to call when she arrived.","She would have joined us, but she became ill.","I am going to apply for the job.","The conference begins on Monday.","I was about to leave when the phone rang.","We were going to launch the service, but funding was delayed.","She had intended to call, but she became ill.","They were due to arrive at noon.","He thought the train would have left by then."]},{"id":"189","title":"Unreal Time: As If, It Is Time and Would Rather","level":"C1","module":23,"main":"Unreal-time expressions use forms that look past but refer to present wishes, preferences or imagined behaviour.","how":"Examples include 'as if + past', 'it's time + past' and 'would rather + past' about another person's action.","detail":"","rules":"Unreal expressions\nAs if can be followed by a past form to express an unreal comparison, and It’s time + past form expresses a\npresent recommendation.\n\n EXAMPLE He talks as if he knew everything.\n\n EXAMPLE It’s time we left.","examples":["He acts as if he owned the place.","It's time we made a decision.","I'd rather you didn't mention it.","It's time we stopped arguing.","She acts as though she owns the building.","He talks as if he knew everything.","It's time we updated the software.","I'd rather you didn't call so late.","She looked as though she had seen a ghost.","I'd rather stay home than travel tonight."]},{"id":"190","title":"Modal Probability Across Time","level":"C1","module":23,"main":"Modal expressions convey probability about present, past and future: must, can't, may, might, could and their perfect forms.","how":"State the evidence that supports your conclusion. 'Must have' is not the same as 'had to'.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"","examples":["She must be at work now.","He might have missed the train.","They can't have finished already.","You should check the address.","She might arrive late.","She must be at home now.","They might have taken an earlier train.","He can't have finished so quickly.","The parcel may arrive tomorrow.","She could be working late tonight."]},{"id":"191","title":"Modal Meaning, Stance and Caution","level":"C1","module":23,"main":"Modal verbs also show stance: the speaker's degree of obligation, willingness, certainty, distance or politeness.","how":"Consider how your wording sounds to the audience. 'You must ...' and 'You might want to ...' carry different interpersonal force.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"","examples":["You must submit the form by Friday.","You may wish to review the results.","That would appear to be correct.","You should check the address.","She might arrive late.","You may wish to read the guidance first.","The figures could indicate a new trend.","You must submit your application by Friday.","We would recommend a short trial.","The evidence appears to support the proposal."]},{"id":"192","title":"Need and Dare: Semi‐Modal Patterns","level":"C1","module":23,"main":"'Need' and 'dare' can work as ordinary verbs and, in some structures, as semi-modals. Usage depends on register and dialect.","how":"Compare 'You don't need to go' with 'You needn't go'. Negative 'dare' patterns are less common in everyday conversation.","detail":"A modal verb changes how a statement sounds: ability, permission, advice, possibility, obligation or deduction. It is followed by the base form of the main verb.","rules":"","examples":["You needn't apologise.","Do you need to leave now?","I daren't ask him directly.","You should check the address.","She might arrive late.","You needn't have worried.","Need we say more?","He dared not interrupt the speaker.","Do you dare to disagree?","She doesn't need to repeat the test."]},{"id":"193","title":"Narrative Viewpoint and Literary Tenses","level":"C1","module":23,"main":"Narrative viewpoint shapes tense choice. Writers may use historical present for immediacy and past perfect for events earlier than the story's current point.","how":"Literary tense shifts should be deliberate, not accidental. Observe whose perspective the reader is following.","detail":"","rules":"","examples":["The door opens. Nobody speaks.","She remembered that she had left the key.","By morning, the town was silent.","The street was empty, and the rain kept falling.","He turned the key; the door opened slowly.","The door opens; nobody moves.","She had forgotten where she'd left the keys.","The rain was falling as the bus turned.","He steps forward and speaks quietly.","The room fell silent as the results appeared."]},{"id":"194","title":"Practice: Choose Grammar for Subtle Meaning","level":"C1","module":23,"main":"At an advanced level, several structures may be grammatically correct but suggest different degrees of certainty, focus or formality.","how":"Compare interpretations before choosing. Explain what changes when you replace a form, not simply whether it is correct.","detail":"","rules":"","examples":["She may have left. (uncertain)","She must have left. (strong conclusion)","It was Sara who called. (focus on Sara)","She could have left early, but we are not certain.","It was the cost, not the time, that mattered.","She may have left early: this is possible.","She must have left early: this is a strong deduction.","He would call if he had time.","He will call when he finishes.","The findings appear to suggest an improvement."]},{"id":"195","title":"Participle Clauses: Complex Uses","level":"C1","module":24,"main":"Advanced participle clauses shorten relationships of time, reason, condition or result. The subject relationship must remain clear.","how":"'Having + past participle' can mark an earlier completed action; an -ing form often marks a simultaneous or related activity.","detail":"","rules":"Participles and sequence\nA perfect participle can clearly show that one action happened before another, but unnecessary complexity\nmay sound unnatural.\n\n EXAMPLE Having completed the report, she sent it.","examples":["Having checked the data, we published the report.","Working from home, she saved time.","Seen from above, the city looked tiny.","Having read the letter, she made a decision.","Built in the 1950s, the bridge needs repairs.","Having completed the course, she applied for a job.","Surprised by the news, he called his manager.","Working late, the team missed the last train.","Not knowing the address, I asked for directions.","Once approved, the plan will be published."]},{"id":"196","title":"Absolute Constructions: Introductory Uses","level":"C1","module":24,"main":"An absolute construction adds background information with its own subject, often using a noun plus a participle or adjective phrase.","how":"These are common in formal or literary writing. If a simple clause would be clearer, use the simpler version.","detail":"","rules":"Absolute constructions\nAn absolute construction is a compact phrase with its own subject, used mostly in formal prose; it does not\nreplace an ordinary main clause.\n\n EXAMPLE The meeting over, everyone left.","examples":["The meeting over, everyone left.","Weather permitting, we'll eat outside.","Her hands full, she opened the door carefully.","All the work complete, the team went home.","Time permitting, we'll discuss one more question.","The weather being fine, we walked home.","All things considered, the plan is reasonable.","The meeting finished, we returned to work.","Her eyes closed, she listened carefully.","Budget permitting, the repairs will begin next month."]},{"id":"197","title":"Nominalisation and Information‐Dense Nouns","level":"C1","module":24,"main":"Nominalisation changes a verb or adjective into a noun phrase, often making formal prose denser.","how":"This can help organise complex ideas, but too much nominalisation hides who did what. Compare 'The committee decided' with 'A decision was made'.","detail":"","rules":"Nominalisation can make writing dense\nChanging verbs or adjectives into nouns can create a formal style, but often makes plain sentences harder\nto read. Use it only when it helps.\n\n EXAMPLE We decided -> our decision\n\n EXAMPLE We investigated the issue -> an investigation of the issue","examples":["The company decided to expand.","The decision to expand was announced.","Their careful analysis improved the plan.","The report describes the implementation of the policy.","A rapid reduction in costs would be welcome.","The expansion decision surprised staff.","The decision to expand was announced yesterday.","We investigated the delay.","An investigation into the delay is under way.","The new policy will be implemented next month."]},{"id":"198","title":"Preposition + ‐ing and Complex Verb Patterns","level":"C1","module":24,"main":"After a preposition, a verb normally takes the -ing form: 'interested in working', 'without asking'.","how":"Some expressions include 'to' as a preposition rather than an infinitive marker: 'look forward to meeting'.","detail":"A preposition connects information about place, time, direction or another relationship. Many choices are learned as fixed patterns: interested in, depend on, at night.","rules":"A preposition takes -ing, not bare verb\nAfter a preposition, use an -ing form when a verb follows. To is sometimes a preposition rather than an\ninfinitive marker.\n\n EXAMPLE interested in learning\n EXAMPLE before leaving\n\n EXAMPLE committed to improving","examples":["Thank you for helping.","She's interested in working abroad.","I look forward to hearing from you.","The files are on the shelf.","We arrived at the station.","She apologised for arriving late.","We are committed to improving safety.","He succeeded in finding a solution.","They objected to paying extra.","Thank you for taking the time to help."]},{"id":"199","title":"Reporting Verb Patterns: Complex Structures","level":"C1","module":24,"main":"Advanced reporting verbs vary in how they connect to an object, clause or infinitive. The pattern affects grammar and sometimes meaning.","how":"Compare 'accuse someone of doing', 'warn someone not to do', 'insist that...' and 'urge someone to do'.","detail":"After a main verb, another verb may take -ing, to + infinitive or a bare infinitive. The choice depends on the first word and sometimes changes meaning.","rules":"Reporting verb + correct complement\nReporting verbs are followed by different clause or infinitive patterns. Include needed objects.\n\n EXAMPLE accuse someone of doing\n EXAMPLE persuade someone to do\n\n EXAMPLE deny doing","examples":["They accused him of changing the figures.","She urged us to reconsider.","He insisted that the figures were correct.","I enjoy learning new words.","I decided to study tonight.","She encouraged him to study.","They blamed us for missing the deadline.","He warned the staff not to enter.","The manager congratulated us on finishing early.","I persuaded her to submit the application."]},{"id":"200","title":"Passives Across Tenses and Constructions","level":"C1","module":24,"main":"Passive constructions can combine with different tenses, aspects, modals and infinitives. Build the form from the meaning and time first.","how":"Be alert to long passive chains that sound heavy. An active sentence may be clearer when the agent matters.","detail":"The passive focuses on what happens to someone or something. It commonly uses be + past participle; the agent may be omitted when unknown or unimportant.","rules":"Passive formula is stable across time\nChange the form of be (and sometimes have), then use the past participle. Not every tense creates a natural\npassive in everyday usage.\n\n EXAMPLE is checked\n\n EXAMPLE was checked\n EXAMPLE has been checked\n\n EXAMPLE will be checked","examples":["The site has been monitored for months.","The work is expected to be completed in June.","The files should have been checked earlier.","The form was sent yesterday.","All requests must be approved.","The equipment is being inspected.","The system has been updated.","The report will have been completed by Monday.","He is believed to be abroad.","The contract should have been signed yesterday."]},{"id":"201","title":"Advanced Reference: Determiners and Pronouns","level":"C1","module":24,"main":"Determiners and pronouns help readers track what each noun refers to. Ambiguous reference can make a technically correct sentence unclear.","how":"Words such as this, that, each, another, the former and the latter need an obvious reference.","detail":"","rules":"Reference must be unambiguous\nPronouns such as it, they and this should clearly refer to something nearby. Repeat a noun if the meaning\nmight be unclear.\n\n EXAMPLE The team changed the plan. This decision saved time.","examples":["Two proposals arrived. The former was cheaper.","The team changed the plan. This caused delays.","Each department reviewed its figures.","Of the two proposals, the former is less expensive.","Each of the applicants has received an email.","Two plans were offered; the latter was cheaper.","The service failed twice; this caused delays.","She read several articles, most of which were useful.","Neither option meets our requirements.","The committee reviewed the proposal; its decision was final."]},{"id":"202","title":"Concession: Much As, Despite and Even Though","level":"C1","module":24,"main":"Concession accepts one point without abandoning the main argument. Forms include although, even though, despite, in spite of and much as.","how":"'Despite' takes a noun phrase or -ing form, not a normal finite clause without 'the fact that'.","detail":"Linking words tell readers how ideas relate: addition, contrast, reason, result or concession. Choose a connector that matches the relationship and punctuate it correctly.","rules":"Despite vs although\nAlthough takes a finite clause; despite takes a noun phrase or -ing clause. Despite the fact that can\nintroduce a full clause.\n\n EXAMPLE Although it rained, we went out.\n\n EXAMPLE Despite the rain, we went out.","examples":["Despite the rain, we travelled.","Even though costs rose, profits improved.","Much as I respect that view, I disagree.","The journey was long, but the meeting was useful.","The data were incomplete; therefore, we checked again.","Even though it was raining, we went out.","Despite having little time, she finished.","Much as I respect his view, I disagree.","In spite of the costs, the trial continued.","Although the figures look promising, more research is needed."]},{"id":"203","title":"Practice: Edit and Simplify Complex Prose","level":"C1","module":24,"main":"Complex prose becomes clearer when you find the main subject, main verb and central point, then shorten unnecessary phrases.","how":"Keep essential conditions and evidence. Simplification should not change the writer's degree of certainty or omit a qualification.","detail":"","rules":"","examples":["Wordy: At this point in time. Clear: Now.","Wordy: Due to the fact that. Clear: Because.","Wordy: Make a decision. Often clearer: Decide.","Wordy: A large number of people. Clear: Many people.","Wordy: It is necessary to. Clear: Must.","Wordy: With regard to. Clear: About.","Wordy: In order to. Clear: To.","Wordy: Make use of. Clear: Use.","Wordy: Make a decision. Clear: Decide.","Wordy: Conduct an investigation. Clear: Investigate."]},{"id":"204","title":"Cohesion, Reference and Paragraph Flow","level":"C1","module":25,"main":"Cohesion helps sentences connect through clear reference, repetition of key ideas, synonyms and logical order.","how":"A pronoun such as 'this' should refer to an obvious idea. When unclear, add a noun: 'This delay ...'.","detail":"Linking words tell readers how ideas relate: addition, contrast, reason, result or concession. Choose a connector that matches the relationship and punctuate it correctly.","rules":"Reference chains and cohesion\nA reader should know what this, these, it and they refer to. Link paragraphs with repeated key concepts\nand clear transitions, not a long list of vague connectors.\n\n EXAMPLE The software failed. This failure delayed the work.","examples":["The delivery was late. This delay affected customers.","First, we collected data. Next, we checked it.","The team proposed a solution. The proposal was approved.","The journey was long, but the meeting was useful.","The data were incomplete; therefore, we checked again.","The bus was late. This delayed the meeting.","First, we collected information. Then, we checked it.","The policy changed. As a result, complaints fell.","One issue remains: the cost of maintenance.","The new system is faster. It also uses less power."]},{"id":"205","title":"Discourse Markers in Speech and Writing","level":"C1","module":25,"main":"Discourse markers show the relationship between ideas in talk and writing: contrast, addition, example, result and conclusion.","how":"Use markers that sound natural in the context. Formal writing and casual speech often favour different choices.","detail":"","rules":"","examples":["On the other hand, costs may rise.","For instance, we could pilot the change.","In short, the project is viable.","I am writing to confirm our appointment.","Please find the revised schedule attached.","To begin with, let me explain the background.","For instance, the trial included three sites.","However, some costs remain unclear.","In contrast, the second option is cheaper.","In conclusion, we recommend a further review."]},{"id":"206","title":"Connotation, Word Choice and Register","level":"C1","module":25,"main":"Connotation is the feeling or association attached to a word beyond its basic meaning. Register describes where the word is suitable.","how":"Near-synonyms can differ in politeness and tone: 'persistent' and 'stubborn' do not sound identical.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"Denotation vs connotation\nTwo words may share a core dictionary meaning but differ in attitude, emotion and level of formality.\n\n EXAMPLE slim / skinny\n\n EXAMPLE economical / cheap","examples":["The plan is ambitious. (often positive)","The plan is unrealistic. (negative)","The proposal is economical. (careful use of money)","The word 'stubborn' can sound more negative than 'determined'.","'Affordable' suggests a price people can manage.","'Ambitious' can sound positive; 'unrealistic' is negative.","'Slim' may sound more positive than 'skinny'.","'Residence' sounds more formal than 'home'.","'Childish' often has a negative meaning.","'Confident' and 'arrogant' suggest different attitudes."]},{"id":"207","title":"Pragmatics: Polite Disagreement and Diplomacy","level":"C1","module":25,"main":"Pragmatics is how meaning depends on people, situation and tone. Polite disagreement recognises the other view before explaining a difference.","how":"Use indirectness when helpful, but do not make your main point impossible to understand.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"Polite disagreement\nUse acknowledgment and measured language in a sensitive discussion. Do not bury your point in so many\nsofteners that it becomes unclear.\n\n EXAMPLE I see your point, but I would suggest a different approach.","examples":["I see your point, but I have a concern.","Could we consider another option?","I understand the aim; however, the timing worries me.","I respect your view, but I see one difficulty.","Might we consider an alternative approach?","I understand your point; may I suggest another view?","That's a fair concern, but the figures differ.","Could we explore an alternative?","I may be mistaken, but isn't the deadline Friday?","Would you mind explaining your reasoning?"]},{"id":"208","title":"Hedging vs Emphasis in Arguments","level":"C1","module":25,"main":"Good arguments match their certainty to the evidence. Hedge uncertain claims and emphasise well-supported findings.","how":"Avoid claims such as 'always' or 'proves' without evidence. Separate observations, interpretations and recommendations.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"","examples":["The data suggest a possible improvement.","The results clearly show a fall in waiting time.","This may explain part of the change.","The evidence may indicate an association, not a cause.","The results clearly confirm a rise in attendance.","The findings suggest a possible improvement.","The figures clearly confirm a reduction.","It appears that demand may rise.","The evidence strongly supports a change.","We cannot yet conclude that the policy caused the result."]},{"id":"209","title":"Advanced Collocations and Phrasal Verbs","level":"C1","module":25,"main":"Advanced collocations are natural word partnerships, and phrasal verbs may be more or less formal than single-word alternatives.","how":"Practise phrases in professional context and check whether a particle changes the meaning.","detail":"A phrasal verb combines a verb and a particle. Its meaning and word order may differ from the main verb alone, so learn useful phrases with objects and contexts.","rules":"Collocation sounds natural\nCertain words are commonly used together. Learning a whole phrase can improve accuracy more than\nlearning a single word.\n\n EXAMPLE make a decision\n EXAMPLE heavy rain\n\n EXAMPLE meet a deadline","examples":["We reached a consensus.","The manager brought up a concern.","The team carried out an assessment.","Please fill in this form.","Please turn the computer off.","We reached a compromise.","She raised an important concern.","They carried out a detailed assessment.","The director put forward a proposal.","The plan broke down during negotiations."]},{"id":"210","title":"Mediation: Explain and Summarise Complex Ideas","level":"C1","module":25,"main":"Mediation means helping another person understand information or ideas. You may summarise, simplify, clarify or bridge different viewpoints.","how":"Keep the original meaning and the speaker's level of certainty. Ask what the listener already knows.","detail":"","rules":"","examples":["In simple terms, the plan has three stages.","The report suggests, rather than proves, a link.","Let me check that I've understood your point.","To put that another way, the change reduced waiting times.","The central message is that we need better evidence.","In simple terms, the process has three stages.","The report suggests a link but does not prove one.","The main point is that fewer people were waiting.","Put differently, the new form saves time.","I'll summarise the risks before we decide."]},{"id":"211","title":"Academic Reports and Spoken Presentations","level":"C1","module":25,"main":"Academic and professional presentations need a clear purpose, logical structure, evidence and a conclusion suited to the audience.","how":"Signpost changes between sections; cite sources when using others' information and prepare for relevant questions.","detail":"","rules":"","examples":["Today I'll outline three findings.","The evidence suggests a modest improvement.","To conclude, we recommend a short trial.","I am writing to confirm our appointment.","Please find the revised schedule attached.","My presentation has three parts.","The data indicate a gradual change.","Figure two shows a steady increase.","There are two limitations to consider.","To conclude, further research is needed."]},{"id":"212","title":"C1 Review and Level Check: Extended Tasks","level":"C1","module":25,"main":"The C1 level check reviews complex grammar, focused writing, nuanced meaning, polite disagreement and evidence-based presentations.","how":"Review whether a sentence is not only grammatical but also clear, appropriately formal and faithful to the evidence.","detail":"","rules":"","examples":["Had we known, we would have acted.","Despite the delay, the team finished.","The findings appear to support the plan.","Much as I understand the risks, I support a trial.","Rarely have we received such detailed feedback.","Not until Monday did we receive the data.","Had we known, we would have acted differently.","Despite the delay, we completed the project.","The report appears to support the recommendation.","What matters most is the quality of the evidence."]},{"id":"213","title":"Subtle Meaning: Choosing Among Correct Structures","level":"C2","module":26,"main":"Two sentences can both be correct but differ in focus, timing or attitude. Proficiency means choosing the best one for the purpose.","how":"Compare emphasis, evidence and reader expectations, not just grammar labels.","detail":"","rules":"Grammar choice communicates perspective\nTwo grammatically correct forms may place focus on process, result, distance, politeness or certainty. Ask\nwhich meaning you want to foreground.\n\n EXAMPLE I finished the report. / I have finished the report.","examples":["I sent the report. (past event)","I've sent the report. (present relevance)","It was the report I sent. (focus)","I've been working on this all day. (duration)","I work on this every Monday. (habit)","I sent the file yesterday.","I've sent the file, so you can read it now.","I was sending the file when the connection failed.","I've been sending updates all morning.","I had sent the file before the meeting began."]},{"id":"214","title":"Marked vs Neutral Word Order","level":"C2","module":26,"main":"Neutral word order usually states information directly. Marked order deliberately highlights, contrasts or dramatizes part of it.","how":"Choose marked word order sparingly in formal reporting; clarity and reader expectations remain important.","detail":"Writers and speakers can change normal word order to highlight an idea. Marked structures may sound formal or emphatic; use them only when they improve the message.","rules":"Marked order is contextual\nMoving an element to the front can signal contrast; use normal subject-verb-object order unless there is a\nclear reason not to.\n\n EXAMPLE That offer, I would refuse. / I would refuse that offer.","examples":["Neutral: I had never seen this before.","Marked: Never had I seen this before.","Neutral: The answer is in this report.","Never have I seen such a clear result.","What we need is more time.","Neutral: I had rarely heard such praise.","Emphatic: Rarely had I heard such praise.","Neutral: We realised the mistake only later.","Emphatic: Only later did we realise the mistake.","Neutral: We had never faced this situation."]},{"id":"215","title":"Advanced Ellipsis in Writing and Conversation","level":"C2","module":26,"main":"Complex ellipsis removes repeated language when grammar and context make the missing words clear.","how":"The same words cannot always be omitted in every clause pattern. Read the sentence aloud to check that meaning survives.","detail":"","rules":"Ellipsis needs recoverable meaning\nOnly omit material that readers or listeners can safely infer. Formal writing generally tolerates less\nambiguity than conversation.\n\n EXAMPLE A: Coming tomorrow? B: Probably. (informal)","examples":["Some agreed; others did not.","I asked whether to leave, and she said yes.","If possible, send the file today.","I am writing to confirm our appointment.","Please find the revised schedule attached.","He offered to help, but she refused.","Some agreed to the changes; others did not.","I wanted the red folder, not the blue one.","She said she would return, and she did.","The first method was costly; the second, less so."]},{"id":"216","title":"Complex Coordination and Subordination","level":"C2","module":26,"main":"Coordination joins elements of equal grammatical status; subordination makes one clause depend on another.","how":"Balanced structure helps readers see which facts are equally important and which explain or qualify others.","detail":"","rules":"","examples":["We reviewed the plan and approved the budget.","Although costs rose, the project continued.","The manager signed because the figures were correct.","We revised the plan because the costs had increased.","Although the timetable changed, the work continued.","We planned the visit and booked the tickets.","Because the weather changed, we stayed home.","Although she was tired, she continued working.","We completed the review, but the decision was delayed.","The team met after the figures had been checked."]},{"id":"217","title":"Non‐Finite Clauses and Compact Expression","level":"C2","module":26,"main":"Non-finite clauses use infinitives, -ing forms or past participles without a finite tense marking. They can compress information into shorter structures.","how":"A non-finite phrase must have a clear logical subject, especially in formal writing.","detail":"","rules":"Finite vs non-finite clause\nFinite verbs express tense or agreement; non-finite clauses use infinitives and participles without\nindependent tense. Use the non-finite form only when its subject is clear.\n\n EXAMPLE To improve accuracy, check the figures.\n\n EXAMPLE Walking home, she phoned.","examples":["To reduce costs, we changed supplier.","Having checked the figures, she signed.","Approved yesterday, the plan takes effect today.","To save time, we submitted the application online.","The staff attending the workshop received notes.","Having checked the figures, we signed the report.","To reduce costs, the team changed suppliers.","The documents received yesterday require review.","When asked, she explained the decision.","The plan approved by the committee takes effect in June."]},{"id":"218","title":"Agreement, Collective Nouns and Exceptional Cases","level":"C2","module":26,"main":"Subject-verb agreement may depend on meaning as well as form, especially with collective nouns, quantities and coordinated noun phrases.","how":"British English sometimes uses singular or plural verbs with collective nouns depending on whether the group acts as a unit or as individuals.","detail":"","rules":"Collective nouns in British English\nA collective noun such as team or staff may take a singular verb when viewed as one unit or a plural verb\nwhen its members are emphasised. This variation is especially common in British English.\n\n EXAMPLE The team is ready.\n\n EXAMPLE The team are arguing among themselves.\n\nThe number vs a number\nThe number of + plural noun generally takes a singular verb. A number of + plural noun generally takes a\nplural verb.\n\n EXAMPLE The number of applicants has risen.\n\n EXAMPLE A number of applicants have arrived.\n\nNouns ending in -s may be singular\nCertain subjects that look plural, such as mathematics and news, normally take singular agreement.\n\n EXAMPLE The news is encouraging.\n\n EXAMPLE Mathematics is difficult.","examples":["The team is ready to begin.","The team are arguing among themselves.","A number of people are absent.","Either of the two options is acceptable.","The majority of the employees are satisfied.","A majority of the staff are satisfied.","Mathematics is an interesting subject.","A number of applicants have arrived.","The number of applicants has increased.","Neither of the options is suitable."]},{"id":"219","title":"Articles and Determiners: Fine Meaning Distinctions","level":"C2","module":26,"main":"Small determiner changes can alter whether a noun is general, specific, total or only part of a group.","how":"Compare 'few' with 'a few', 'little' with 'a little', and 'the' with no article. Evaluate the intended attitude as well as number.","detail":"Article choice depends on sound, number and whether the listener can identify the noun. Use a/an for one non-specific singular countable thing; the when the thing is known or identified.","rules":"Small article choices can change reference\nA, the and zero article can distinguish a new example from a known one or an institution from a physical\nbuilding.\n\n EXAMPLE She went to university.\n\n EXAMPLE She went to the university to attend a public lecture.","examples":["Few applicants qualified. (rather negative)","A few applicants qualified. (some did)","The information we received was incomplete.","I need a pen. The pen is on the desk.","She is an engineer.","Few people attended; the turnout was disappointing.","A few people attended; we could still begin.","She has some experience in finance.","She has considerable experience in finance.","Most of the information is confidential."]},{"id":"220","title":"Idiomatic and Figurative Expressions in Context","level":"C2","module":27,"main":"Idioms and figurative expressions have meanings that may not equal the sum of their words. Learn each in context.","how":"Idioms can be culture-specific and often too informal for technical reports. Check tone and audience.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"Idioms are meaning units\nAn idiom often cannot be understood by adding the meanings of individual words. Learn its meaning,\nregister and suitable context.\n\n EXAMPLE break the ice = make people feel more relaxed","examples":["Let's get the ball rolling. (begin)","We're on the same page. (agree)","The launch is just around the corner. (soon)","We need to think outside the box. (be creative)","We called it a day after six hours. (stopped working)","Let's get the ball rolling: let's begin.","We're on the same page: we agree.","The plan is up in the air: it is undecided.","He hit the nail on the head: he was exactly right.","They are back to square one: they must start again."]},{"id":"221","title":"Collocation and Subtle Associations Between Words","level":"C2","module":27,"main":"Collocation is partly about what sounds natural. Near-synonyms may attract different words or levels of formality.","how":"Use learner dictionaries and real examples to confirm a phrase before putting it into professional writing.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"","examples":["We made a decision.","She paid close attention.","The policy had a profound effect.","They made steady progress during the trial.","She paid careful attention to the instructions.","Make a decision, not do a decision.","Pay close attention, not give close attention.","Heavy rain is more natural than strong rain.","A strong argument can be convincing.","The committee reached a consensus."]},{"id":"222","title":"Complex Multi‐Word Verbs and Register","level":"C2","module":27,"main":"Multi-word verbs can be literal, idiomatic, separable or inseparable. Some belong to casual speech, while others are common in formal writing.","how":"Consider meaning, grammar and register together. A simple verb may be clearer for international audiences.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"Register of multi-word verbs\nA multi-word verb can sound everyday while a single-word alternative sounds more formal. Neither is\nalways better.\n\n EXAMPLE put off the meeting / postpone the meeting\n\n EXAMPLE find out / discover","examples":["We looked into the complaint. (investigated)","The plan fell through. (failed to happen)","We carried out the review. (conducted)","Please look over the draft before Friday. (review)","The company carried on despite the delay. (continued)","We looked into the complaint: we investigated it.","The meeting was put off: it was postponed.","The agreement fell through: it did not happen.","She followed up on the enquiry.","The issue was brought up during the discussion."]},{"id":"223","title":"Lexical Bundles in Academic and Professional English","level":"C2","module":27,"main":"Lexical bundles are frequent groups of words used to organise speech and writing, especially in academic and professional contexts.","how":"Use bundles to express relationships such as 'on the basis of' or 'it is important to note that', but avoid unnecessary padding.","detail":"","rules":"","examples":["On the basis of the evidence, we recommend a trial.","It is important to note that the sample was small.","In relation to the budget, costs remain stable.","I am writing to confirm our appointment.","Please find the revised schedule attached.","On the basis of this evidence, we recommend a trial.","It should be noted that the sample was small.","A growing body of research supports this view.","In relation to the first question, the answer is unclear.","The results are consistent with earlier findings."]},{"id":"224","title":"British and American Usage: Smart Choices","level":"C2","module":27,"main":"British and American English differ in some spellings, vocabulary and grammar preferences. Most standard varieties are mutually understandable.","how":"Be consistent within a document. Learn common pairs, and avoid calling a standard regional form 'wrong'.","detail":"","rules":"British and American forms\nUse one spelling system consistently in formal writing unless quoting a source. Some vocabulary and\ngrammar also differ.\n\n EXAMPLE colour / color\n EXAMPLE organise / organize\n\n EXAMPLE at the weekend / on the weekend","examples":["'Colour' (British); 'color' (American).","'Lift' (British); 'elevator' (American).","'At the weekend' is common in British English.","British: 'queue'. American: 'line'.","British: 'petrol'. American: 'gasoline'.","British: colour. American: color.","British: centre. American: center.","British: lorry. American: truck.","British: flat. American: apartment.","British: holiday. American: vacation."]},{"id":"225","title":"Implied Meaning, Politeness and Pragmatics","level":"C2","module":27,"main":"Implied meaning depends on shared context, polite conventions and what is left unsaid. A question may function as a request.","how":"Avoid assuming hidden meaning without evidence. Check understanding when a message could have several interpretations.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"Meaning includes social context\nAn indirect question may function as a polite request rather than a literal request for information about\nability.\n\n EXAMPLE Could you open the window? = a request, not a test of ability.","examples":["'Could you open the window?' is usually a request.","'That's an interesting idea' may signal interest or polite reservation.","'We may need to revisit this' can soften disagreement.","'Could we revisit the timing?' may imply disagreement.","'I'm not sure that will work' is a polite objection.","Could you possibly send it today? (polite request)","That might be difficult. (indirect refusal)","I see what you mean. (acknowledgement)","Perhaps we could revisit that idea. (suggestion)","It's an interesting proposal. (meaning depends on tone)"]},{"id":"226","title":"Tone: Irony, Understatement and Indirectness","level":"C2","module":27,"main":"Irony may say one thing while implying another. Understatement deliberately describes something as less extreme than it is.","how":"These devices depend on tone, context and shared culture, so they can be misunderstood. Use cautiously in professional settings.","detail":"Language choice affects how certain, formal, direct or polite a message feels. Compare alternatives in context instead of memorising a single 'best' expression.","rules":"","examples":["'Well, that went brilliantly' after a disaster may be ironic.","'It's a bit chilly' in freezing weather is understatement.","'Not ideal' may signal a serious concern.","'The plan has a few issues' may mean it has serious problems.","Calling a terrible delay 'a minor setback' is understatement.","'That was helpful' said sarcastically may mean the opposite.","'It's a little cold' may understate freezing weather.","'Not bad' can mean quite good.","'We have a small problem' may understate a serious issue.","'What a lovely day' in heavy rain may be ironic."]},{"id":"227","title":"Rhetorical Emphasis, Parallelism and Rhythm","level":"C2","module":28,"main":"Parallelism uses matching grammatical patterns to make points easier to understand and remember. Rhythm comes from sensible clause length and stress.","how":"Use parallel forms in lists, speeches and persuasive writing. Do not sacrifice accuracy for sound.","detail":"","rules":"Parallel structures improve clarity\nKeep comparable parts of a list in the same grammatical form. This makes arguments easier to follow.\n\n EXAMPLE We aim to reduce costs, improve service and increase access.","examples":["We aim to reduce costs, improve access and increase quality.","We came to listen, to learn and to act.","Clear goals, careful planning, strong results.","We sought not praise but progress, not speed but accuracy.","Clear aims, careful methods, credible results.","We aim to plan carefully, act wisely and learn quickly.","We need evidence, not guesses; clarity, not confusion.","First we listened; then we learned; finally we acted.","This is a plan for today, tomorrow and the future.","The goal is simple: safer systems, faster service, better results."]},{"id":"228","title":"Persuasion, Evidence and Calibrated Claims","level":"C2","module":28,"main":"Persuasive claims need evidence that matches their strength. Distinguish measurable results from possibilities and personal opinions.","how":"Explain what a source supports, including limits. Avoid treating correlation as proof of cause.","detail":"","rules":"Match claim strength to evidence\nUse probability and limitation words honestly. Avoid presenting one study or observation as proof of a\nuniversal fact.\n\n EXAMPLE The survey suggests an association. (not proves all people ...)","examples":["The survey suggests that users prefer shorter forms.","The figures show a six per cent increase in visits.","This evidence supports a pilot, not a full rollout.","The data indicate an improvement, but not its cause.","A small sample limits how confidently we can generalise.","The data indicate a modest increase in demand.","The figures show an eight per cent increase in visits.","This small study cannot establish cause and effect.","The evidence supports a trial, not a full launch.","A larger sample would give us more confidence."]},{"id":"229","title":"Counterarguments, Concessions and Nuanced Reasoning","level":"C2","module":28,"main":"A strong argument presents its view, recognises a counterargument and responds with evidence or a reasoned qualification.","how":"A concession shows fairness without requiring you to abandon your position.","detail":"Linking words tell readers how ideas relate: addition, contrast, reason, result or concession. Choose a connector that matches the relationship and punctuate it correctly.","rules":"","examples":["Some argue that the change is costly.","Although the cost is high, the long-term benefits may justify it.","However, the evidence remains incomplete.","The journey was long, but the meeting was useful.","The data were incomplete; therefore, we checked again.","Some argue that the plan is too expensive.","Nevertheless, the long-term benefits may justify it.","Although the results are promising, risks remain.","Admittedly, the process will take time.","On balance, I support a limited trial."]},{"id":"230","title":"Source Integration, Citation and Responsible Paraphrase","level":"C2","module":28,"main":"When using sources, distinguish your own words from another person's ideas. Paraphrase accurately and cite the original source.","how":"Changing a few words is not enough for responsible paraphrasing. Record the author, title, date and link where available.","detail":"","rules":"Paraphrase with attribution\nA paraphrase should express the idea in your own language and still acknowledge the original source.\nChanging a few words without attribution is not enough.\n\n EXAMPLE According to the report, ...\n\n EXAMPLE The authors argue that ...","examples":["Source claim: Costs fell by ten per cent.","Paraphrase: The report records a ten per cent reduction in costs.","Attribution: According to the published report, costs fell.","I am writing to confirm our appointment.","Please find the revised schedule attached.","The article reports a fall in waiting times.","In my words: The study found shorter delays.","According to the report, costs rose slightly.","The author argues that more evidence is needed.","Always distinguish an author's claim from your own conclusion."]},{"id":"231","title":"Genre Choices: Technical, Legal and Public Information","level":"C2","module":28,"main":"A genre is a type of communication with shared expectations. Technical instructions, legal notices and public information texts have different purposes.","how":"Choose word choice, structure and detail according to the audience. Legal texts need special care; plain-English summaries should not replace formal legal advice.","detail":"","rules":"","examples":["Technical: Restart the device and check the indicator.","Public notice: The office will close at five.","Legal-style: Subject to the following conditions ...","I am writing to confirm our appointment.","Please find the revised schedule attached.","Legal notice: The agreement is effective from 1 June.","Public notice: The library closes at six.","Formal policy: Visitors must register on arrival.","Customer email: We apologise for the inconvenience.","Contract wording: Payment is due within thirty days."]},{"id":"232","title":"Edit Ambiguous, Wordy and Awkward Sentences","level":"C2","module":28,"main":"Editing improves precision, concision and readability without changing meaning. Check reference, wordiness, clause attachment and unnecessary negatives.","how":"An ambiguous pronoun should be replaced with its noun when needed. Prefer simple verbs to empty phrases.","detail":"","rules":"Editing for clarity\nRemove unnecessary words, repair vague pronouns and split overloaded sentences. Correctness is not\nenough if readers cannot follow the meaning.\n\n EXAMPLE Due to the fact that -> because\n\n EXAMPLE at this point in time -> now","examples":["Wordy: Carry out an investigation. Clear: Investigate.","Ambiguous: When Sara met Lina, she was late.","Clear: Sara was late when she met Lina.","Ambiguous: She saw the woman with binoculars.","Clear: Using binoculars, she saw the woman.","Wordy: At this point in time. Clear: Now.","Ambiguous: Sara told Aisha that she was late.","Clear: Sara was late and told Aisha.","Wordy: In the event that. Clear: If.","Awkward: The reason is because... Clear: The reason is that..."]},{"id":"233","title":"Listen to Fast, Varied and Idiomatic English","level":"C2","module":28,"main":"Fast spoken English includes linking, weak forms, contractions and idioms. Listening improves when you predict meaning and check phrases in context.","how":"Do not expect to hear every written sound separately. Listen first for the main idea, then for details.","detail":"Clear communication involves listening, giving relevant information and checking understanding. Use expressions suited to the other person and the situation.","rules":"","examples":["'Going to' may sound reduced in connected speech.","'Could you' may link smoothly in conversation.","'I'll get back to you' means I will reply later.","Could you explain that point, please?","To summarise, we recommend the second option.","In connected speech, words may join together.","'Could you' often sounds like one unit.","Listen for stress on important content words.","Weak vowels often occur in unstressed syllables.","Use the context to infer unfamiliar expressions."]},{"id":"234","title":"Professional Debates and Negotiation Skills","level":"C2","module":29,"main":"A professional debate presents a clear position, listens to alternatives, evaluates evidence and looks for a workable outcome.","how":"In negotiation, separate interests from demands and restate proposals accurately before agreeing.","detail":"Clear communication involves listening, giving relevant information and checking understanding. Use expressions suited to the other person and the situation.","rules":"","examples":["Our main priority is reliability.","I understand your concern about cost.","Could we agree on a two-week trial?","Could you explain that point, please?","To summarise, we recommend the second option.","We need clear terms before we agree.","Can we find a solution that works for everyone?","Could we agree on a smaller trial?","That option would benefit both teams.","Let's confirm the next steps in writing."]},{"id":"235","title":"High‐Stakes Presentations and Difficult Questions","level":"C2","module":29,"main":"A high-stakes presentation needs a focused opening, trustworthy evidence, clear recommendation and preparation for difficult questions.","how":"When unsure, say what you know and what needs checking. Do not invent a figure under pressure.","detail":"Clear communication involves listening, giving relevant information and checking understanding. Use expressions suited to the other person and the situation.","rules":"","examples":["The evidence supports a phased rollout.","That's an important question; let me clarify the assumption.","I don't have that figure here, but I can verify it.","Could you explain that point, please?","To summarise, we recommend the second option.","Today I'll explain three possible options.","The evidence supports a phased approach.","That's an important question; let me clarify.","The figure reflects data from last quarter.","If the assumption changes, so will our recommendation."]},{"id":"236","title":"Literary, Journalistic and Academic Voices","level":"C2","module":29,"main":"Literary, journalistic and academic writing differ in voice, purpose and evidence conventions.","how":"Literary writing may use imagery; journalism usually foregrounds newsworthy facts; academic writing builds a supported argument. Real texts vary.","detail":"","rules":"Different genres use different grammar choices\nLiterary writing, journalism and academic prose have different conventions. Choose grammar and tone that\nsuit audience and purpose.\n\n EXAMPLE News: Officials announced ...\n\n EXAMPLE Research: The findings suggest ...","examples":["Literary: The street breathed after the rain.","Journalistic: The council announced the change on Tuesday.","Academic: The findings suggest a modest association.","I am writing to confirm our appointment.","Please find the revised schedule attached.","Literary: The city woke beneath the rain.","Journalistic: The council announced the change today.","Academic: The findings indicate a modest effect.","Technical: The device shuts down after ten minutes.","Reflective: Looking back, I would have chosen differently."]},{"id":"237","title":"Synthesise Multiple Sources and Attribute Ideas","level":"C2","module":29,"main":"Synthesis combines ideas from more than one source into a new explanation or conclusion while preserving accurate attribution.","how":"Look for agreement, difference and limits between sources. Do not merge conflicting claims as if they were identical.","detail":"","rules":"Synthesis is more than summary\nCompare ideas from different sources, identify agreement and disagreement, and attribute conclusions to\nthe relevant authors.\n\n EXAMPLE Both studies report ...; however, only the second ...","examples":["Source A reports shorter waiting times.","Source B notes rising staff costs.","Together, the reports suggest a trade-off between speed and cost.","I am writing to confirm our appointment.","Please find the revised schedule attached.","The studies reach different conclusions.","Source B notes increased staffing costs.","Taken together, both sources suggest a trade-off.","The first study focuses on hospitals; the second, on clinics.","Neither source alone proves a direct causal link."]},{"id":"238","title":"Capstone Writing: Extended Critical Analysis","level":"C2","module":29,"main":"Extended critical writing starts with a clear question, a focused argument and an outline. Each paragraph should advance the reasoning.","how":"Use credible evidence, consider counterarguments, indicate uncertainty and attribute borrowed ideas. Revise for coherence and accuracy.","detail":"","rules":"","examples":["Claim: Remote work can improve flexibility.","Qualification: The impact varies by role.","Conclusion: A mixed model deserves further evaluation.","I am writing to confirm our appointment.","Please find the revised schedule attached.","The main claim is that flexible work can improve retention.","The evidence is limited to a small survey.","An alternative explanation is that salaries increased.","This argument is persuasive, but not conclusive.","Further research should examine different job roles."]},{"id":"239","title":"Capstone Speaking: Presentation and Discussion","level":"C2","module":29,"main":"A capstone spoken presentation should combine clear structure, appropriate register, signposting, examples and thoughtful responses to questions.","how":"Practise with a timer, record yourself when possible, and check pronunciation of important terms.","detail":"Clear communication involves listening, giving relevant information and checking understanding. Use expressions suited to the other person and the situation.","rules":"","examples":["Today I will assess three possible approaches.","The strongest evidence supports the second option.","Thank you; I will address that concern first.","Could you explain that point, please?","To summarise, we recommend the second option.","Today I will compare three approaches.","The first option is cheaper but slower.","The second offers the strongest evidence.","Let me respond to that concern directly.","To conclude, I recommend a controlled trial."]},{"id":"240","title":"Final Portfolio, C2‐Oriented Assessment and Next Steps","level":"C2","module":29,"main":"Your final portfolio brings together speaking, writing, reading, listening and grammar evidence collected during the course.","how":"This is a C2-oriented learning pathway, not an official test or guarantee of proficiency. Continue using authentic materials, feedback and independent practice.","detail":"","rules":"A realistic final assessment\nAdvanced proficiency cannot be measured from a single written quiz. Combine listening, reading,\nspontaneous speaking, extended writing and feedback over time.\n\n EXAMPLE Keep a portfolio of corrected writing and recorded speaking.\n\n EXAMPLE Compare your performance against appropriate CEFR descriptors.","examples":["Portfolio item: A revised professional report.","Portfolio item: A recorded presentation with reflection.","Portfolio item: A source-based written argument.","I will review my progress at the end of each month.","My next goal is to write clearer professional emails.","My portfolio includes a revised professional report.","I recorded a ten-minute presentation and reflected on it.","I reviewed my speaking strengths and weaknesses.","My next goal is to practise with native and non-native speakers.","I will continue reading, listening, writing and speaking each week."]}]};
